// Create / Destroy
void CTreeWorkCtrl::ToggleStyle(DWORD lStyleMask)
{
	long		lStyleOld;

	lStyleOld = GetStyle();
	BOOL bSetBits = !(lStyleMask&lStyleOld);
	if (bSetBits)
		lStyleOld |= lStyleMask;
	else
		lStyleOld &= ~(lStyleMask);

	SetWindowLongPtr(m_hWnd, GWL_STYLE, lStyleOld);
	SetWindowPos(NULL, 0, 0, 0, 0, SWP_NOMOVE | SWP_NOSIZE | SWP_NOZORDER);

	DWORD dwStyle, dwExStyle;
	GetTreeCtrlStyles(dwStyle, dwExStyle);
	if (dwStyle & lStyleMask)
		ModifyTreeCtrlStyles(lStyleMask, 0, 0, 0);
	else
		ModifyTreeCtrlStyles(0, lStyleMask, 0, 0);
}

void CTreeWorkCtrl::CreateTree()
{
	return;
}

int CTreeWorkCtrl::OnCreate(LPCREATESTRUCT lpCreateStruct)
{
	if (MBaseTreeCtrl::OnCreate(lpCreateStruct) == -1)
		return -1;

	CreateTree();
	AddAllSVGImages(L"");
	SetItemTree(TRUE);
	EnableMultiSelect();
	//ToggleStyle(TVS_LINESATROOT);  
	EndInsertTreeItem();

	return 0;
}

