// Set Tree Item
void CTreeWorkCtrl::SetItemTree(BOOL bInit)
{
	InitializeTree init_tree(this);

	HTREEITEM   hTI;
	// 기존의 Tree Item 지우는 부분 필요

	if (GetCount()) DeleteAllItems();
	// 기존 Work tree의 메모리 지움

	FreeWorkTreeBuffer();

	m_hRootTi = GetRootItem();
	m_hRootTi = InsertTreeItem(m_hRootTi, WORK_ROOT, _LS(IDS_TMWK__MSG2), _T("ico24_treemenu_works_works"));
	CDBDoc* pDoc = CDBDoc::GetDocPoint();
	if (!pDoc)
	{
		TRACE(_LS(IDS_TMWK__MSG1));
		return;
	}

	// Set item list
	hTI = SetAnalysisItemTree(pDoc, bInit);
	hTI = SetGeometryItemTree(pDoc, bInit);
	hTI = SetNamedPlaneItemTree(pDoc, bInit);
	hTI = SetDimensionItemTree(pDoc, bInit);
	hTI = SetTracingItemTree(pDoc, bInit);
	hTI = SetPropertyItemTree(pDoc, bInit);
	hTI = SetInelasticPropertyItemTree(pDoc, bInit);
	hTI = SetBoundaryItemTree(pDoc, bInit);
	hTI = SetMassItemTree(pDoc, bInit);
	hTI = SetStaticLoadsItemTree(pDoc, bInit);
	if (m_bCivil)	hTI = SetEarthPressureParamItemTree(pDoc, bInit);
#if defined(_MGEN_CH)
	hTI = SetStaticLoadsTypeItemTree(pDoc, bInit);
#endif
	hTI = SetTendonItemTree(pDoc, bInit);
	hTI = SetResponseSpectrumItemTree(pDoc, bInit);
	hTI = SetTimeHistoryItemTree(pDoc, bInit);
	hTI = SetMovingLoadItemTree(pDoc, bInit);
	hTI = SetCraneLoadItemTree(pDoc, bInit);
	hTI = SetSettlementItemTree(pDoc, bInit);
	hTI = SetConCurrentReactionItemTree(pDoc, bInit);
	hTI = SetConCurrentJointFoeceItemTree(pDoc, bInit);
	hTI = SetCompositeBridgeItemTree(pDoc, bInit);
	hTI = SetHydrationItemTree(pDoc, bInit);
	hTI = SetStageItemTree(pDoc, bInit);
	hTI = SetGridModelItemTree(pDoc, bInit);
	hTI = SetPushoverItemTree(pDoc, bInit);
	hTI = SetRebarDataItemTree(pDoc, bInit);
	hTI = SetDomainDataItemTree(pDoc, bInit);
	hTI = SetEBeamDataItemTree(pDoc, bInit);
	hTI = SetStripDataItemTree(pDoc, bInit);
	hTI = SetDropPanelDataItemTree(pDoc, bInit);
	hTI = SetColmCapitalDataItemTree(pDoc, bInit);
	hTI = SetInfillStrutDataItemTree(pDoc, bInit);
	hTI = SetFireSteelItemTree(pDoc, bInit);

	SelectItem(m_hRootTi);
	//	if(bInit) ExpandCompletely(m_hRootTi, TRUE); // 최초에 보여줄 때는 모두 펼쳐서...
	if (bInit) Expand(m_hRootTi, TVE_EXPAND);// 최초에 보여줄 때는 한단계만...
	this->FreezeRows(1);
}

// Geometry Item
HTREEITEM CTreeWorkCtrl::SetGeometryItemTree(CDBDoc* pDoc, BOOL bInit)
{
	InitializeTree init_tree(this);

	HTREEITEM hTI = NULL, ThTi = NULL;
	CString   tStr;
	CArray<T_STOR_K, T_STOR_K> aStorKeyList;
	CArray<T_NODE_K, T_NODE_K> aNodeKeyList;
	CArray<T_ELEM_K, T_ELEM_K> aElemKeyList;
	CArray<T_SPAN_K, T_SPAN_K> aSpanPSCKeyList;
	CArray<T_SPAN_K, T_SPAN_K> aSpanCompositeKeyList;
	CArray<T_SPAN_K, T_SPAN_K> aSpanCompositeKeyListVB;
	CArray<T_SPAN_K, T_SPAN_K> aSpanSteelGirdKeyList;
	CArray<T_EFWD_K, T_EFWD_K> aEfwdKeyList; // PSC Value Eff. width
	pDoc->m_pAttrCtrl->GetStorKeyListByModlSort(aStorKeyList);
	pDoc->m_pAttrCtrl->GetNodeKeyList(aNodeKeyList);
	pDoc->m_pAttrCtrl->GetElemKeyList(aElemKeyList, FALSE);
	pDoc->m_pAttrCtrl->GetSpanKeyList(aSpanPSCKeyList, 0);
	pDoc->m_pAttrCtrl->GetSpanKeyList(aSpanCompositeKeyList, 1);
	pDoc->m_pAttrCtrl->GetSpanKeyList(aSpanSteelGirdKeyList, 2);
	pDoc->m_pAttrCtrl->GetSpavKeyList(aSpanCompositeKeyListVB, 1);
	pDoc->m_pAttrCtrl2->GetEfwdKeyList(aEfwdKeyList);
	int nStorCount = aStorKeyList.GetSize();
	int nNodeCount = aNodeKeyList.GetSize();
	int nElemCount = aElemKeyList.GetSize();
	int nSpanPSCCount = aSpanPSCKeyList.GetSize();
	int nSpanCompositeCount = aSpanCompositeKeyList.GetSize();
	int nSpanSteelGirdCount = aSpanSteelGirdKeyList.GetSize();
	int nSpanCompositeCountVB = aSpanCompositeKeyListVB.GetSize();
	int nEfwdCount = aEfwdKeyList.GetSize();
	hTI = SetSub1TreeItem(WORK_STRU_FLD, bInit, nStorCount + nNodeCount + nElemCount + nSpanPSCCount + nSpanCompositeCount + nSpanSteelGirdCount + nSpanCompositeCountVB, 2);
	if (hTI == NULL) return NULL;

	// *********** SUB ITEM ***********
	// === Stor 정보 표시 ===
	if (nStorCount)
	{
		ThTi = InsertTreeItem(hTI, WORK_STOR_FLD, _LS(IDS_TMWK_NC_Stories_d), _T("ico24_structure_building_story"));
		SetItemDisplayCount(ThTi, nStorCount);

		CString strOnOff;
		CString strStorName;
		for (int i = 0; i < nStorCount; i++)
		{
			strStorName = pDoc->m_pAttrCtrl->GetStorNameWithModuleName(aStorKeyList[i]);
			tStr = strStorName;

			T_STOR_D storData;
			pDoc->m_pAttrCtrl->GetStor(aStorKeyList[i], storData);

			T_TDAS_D tdasData;
			const auto hasTdas = pDoc->m_pAttrCtrl2->GetTdas(storData.TdasK, tdasData);
			const auto hasLineGrid = CStorSubData::GetInstance().HasStorKeyForLineGrid(aStorKeyList[i]);
			const auto showTdas = I_GENModelBase::GetCurMySelfST()->IsCurShowTracingStoryKey(aStorKeyList[i]);
			const auto showLineGrid = I_GENModelBase::GetCurMySelfST()->IsCurShowLineGridStoryKey(aStorKeyList[i]);

			if (hasTdas)
			{
				tStr += _T("[") + tdasData.strName + _T("]");
				if (showTdas && !showLineGrid)
				{
					tStr +=_LS(IDS_TM_WORK__On);
				}
				else if (!showTdas && showLineGrid)
				{
					tStr += _LS(IDS_TM_WORK__Off);
				}
			}

			if (hasLineGrid)
			{
				tStr += _T(" (") + _LS(IDS_TM_Line_Grid) + _T(")");
				if (showTdas && !showLineGrid)
				{
					tStr += _LS(IDS_TM_WORK__Off);
				}
				else if (!showTdas && showLineGrid)
				{
					tStr += _LS(IDS_TM_WORK__On);
				}
			}

			if (hasTdas || hasLineGrid)
			{
				if (showTdas && showLineGrid)
				{
					tStr += _LS(IDS_TM_WORK__On);
				}
				else if (!showTdas && !showLineGrid)
				{
					tStr += _LS(IDS_TM_WORK__Off);
				}
			}

			//tStr.Format(strStorName);
			InsertTreeItem(ThTi, WORK_STOR_LST, tStr, _T("ico24_structure_building_story"));
		}
	}

	// === Node 정보 표시 ===
	if (nNodeCount)
	{
		HTREEITEM hTIC = InsertTreeItem(hTI, WORK_NODE_FLD, _LS(IDS_TMWK_NC_MSG3), _T("ico24_nodeelement_nodes_nodestable"));
		SetItemDisplayCount(hTIC, nNodeCount);
	}

	// === Element 정보 표시 ===
	T_ELEM_D elemData;
	if (nElemCount)
	{
		ThTi = InsertTreeItem(hTI, WORK_ELEM_FLD, _LS(IDS_TMWK_NC_MSG4), _T("ico24_nodeelement_element_elementtable"));
		SetItemDisplayCount(ThTi, nElemCount);

		// Element type 별로 정리 
		int trussNum = 0, beamNum = 0, plstrsNum = 0, plstrnNum = 0, plateNum = 0, wallNum = 0, wallopenNum = 0, axisymNum = 0, solidNum = 0, trtensNum = 0, trcompNum = 0;
		for (int i = 0; i < nElemCount; i++)
		{
			pDoc->m_pAttrCtrl->GetElem(aElemKeyList[i], elemData);
			switch (elemData.eltyp)
			{
			case TRUSS_EL:	trussNum += 1;	break;
			case TRTENS_EL: trtensNum += 1;	break;
			case TRCOMP_EL: trcompNum += 1;	break;
			case BEAM_EL:	  beamNum += 1;		break;
			case PLATE_EL:	plateNum += 1;	break;
			case PLSTRS_EL: plstrsNum += 1;	break;
			case PLSTRN_EL: plstrnNum += 1;	break;
			case AXISYM_EL: axisymNum += 1;	break;
			case SOLID_EL:	solidNum += 1;	break;
			case WALL_EL:	  wallNum += 1;		break;
			case WALLOPEN_EL:	wallopenNum += 1;		break;
			default: break;
			}
		}

		if (trussNum)
		{
			HTREEITEM hTIC = InsertTreeItem(ThTi, WORK_TRUSS_LST, _LS(IDS_TMWK_NC_MSG5), _T("ico24_structure_wizard_truss"));
			SetItemDisplayCount(hTIC, trussNum);
		}
		if (trtensNum)
		{
			HTREEITEM hTIC = InsertTreeItem(ThTi, WORK_TRTENS_LST, _LS(IDS_TMWK_NC_MSG6), _T("ico24_structure_wizard_truss"));
			SetItemDisplayCount(hTIC, trtensNum);
		}
		if (trcompNum)
		{
			HTREEITEM hTIC = InsertTreeItem(ThTi, WORK_TRCOMP_LST, _LS(IDS_TMWK_NC_MSG7), _T("ico24_structure_wizard_truss"));
			SetItemDisplayCount(hTIC, trcompNum);
		}
		if (beamNum)
		{
			HTREEITEM hTIC = InsertTreeItem(ThTi, WORK_BEAM_LST, _LS(IDS_TMWK_NC_MSG8), _T("ico24_structure_wizard_beam"));
			SetItemDisplayCount(hTIC, beamNum);
		}
		if (plateNum)
		{
			HTREEITEM hTIC = InsertTreeItem(ThTi, WORK_PLATE_LST, _LS(IDS_TMWK_NC_MSG9), _T("ico24_structure_wizard_plate"));
			SetItemDisplayCount(hTIC, plateNum);
		}
		if (plstrsNum)
		{
			HTREEITEM hTIC = InsertTreeItem(ThTi, WORK_PLSTRS_LST, _LS(IDS_TMWK_NC_MSG10), _T("ico24_structure_wizard_frame"));
			SetItemDisplayCount(hTIC, plstrsNum);
		}
		if (plstrnNum)
		{
			HTREEITEM hTIC = InsertTreeItem(ThTi, WORK_PLSTRN_LST, _LS(IDS_TMWK_NC_MSG11), _T("ico24_structure_wizard_frame"));
			SetItemDisplayCount(hTIC, plstrnNum);
		}
		if (axisymNum)
		{
			HTREEITEM hTIC = InsertTreeItem(ThTi, WORK_AXISYM_LST, _LS(IDS_TMWK_NC_MSG12), _T("ico24_structure_wizard_shell"));
			SetItemDisplayCount(hTIC, axisymNum);
		}
		if (solidNum)
		{
			HTREEITEM hTIC = InsertTreeItem(ThTi, WORK_SOLID_LST, _LS(IDS_TMWK_NC_MSG13), _T("ico24_view_dynamicview_viewpoint"));
			SetItemDisplayCount(hTIC, solidNum);
		}
		if (wallNum)
		{
			HTREEITEM hTIC = InsertTreeItem(ThTi, WORK_WALL_LST, _LS(IDS_TMWK_NC_MSG14), _T("ico24_nodeelement_elements_wall"));
			SetItemDisplayCount(hTIC, wallNum);
		}
		if (wallopenNum)
		{
			HTREEITEM hTIC = InsertTreeItem(ThTi, WORK_WALLOPEN_LST, _LS(IDS_TMWK_NC_MSG_WallOpen), _T("ico24_nodeelement_elements_wallopening"));
			SetItemDisplayCount(hTIC, wallopenNum);
		}
	}

	// === Span 정보 표시 ===  2006.2.20 jkpark
	T_SPAN_D spanData;
	T_SPAV_D spavData;
	if (nSpanPSCCount)
	{
		ThTi = InsertTreeItem(hTI, WORK_SPAN_FLD, _LS(IDS_TMWK_NC_MSG188), _T("ico24_structure_wizard_spaninformation"));
		SetItemDisplayCount(ThTi, nSpanPSCCount);

		for (int i = 0; i < nSpanPSCCount; i++)
		{
			pDoc->m_pAttrCtrl->GetSpan(aSpanPSCKeyList[i], spanData);
			tStr.Format(_T("%s"), spanData.Name);
			InsertTreeItem(ThTi, WORK_SPAN_LST, tStr, _T("ico24_structure_wizard_spaninformation"));
		}
	}
	if (nSpanCompositeCount)
	{
		ThTi = InsertTreeItem(hTI, WORK_SPAN_COMPOSTIE_FLD, _LS(IDS_TMWK_NC_MSG188_COMPOSITE), _T("ico24_structure_wizard_spaninformation"));
		SetItemDisplayCount(ThTi, nSpanCompositeCount);

		for (int i = 0; i < nSpanCompositeCount; i++)
		{
			pDoc->m_pAttrCtrl->GetSpan(aSpanCompositeKeyList[i], spanData);
			tStr.Format(_T("%s"), spanData.Name);
			InsertTreeItem(ThTi, WORK_SPAN_COMPOSTIE_LST, tStr, _T("ico24_structure_wizard_spaninformation"));
		}
	}
	if (nSpanCompositeCountVB)
	{
		ThTi = InsertTreeItem(hTI, WORK_SPAN_COMPOSTIE_VB_FLD, _LS(IDS_TMWK_NC_MSG188_COMPOSITE_VB), _T("ico24_structure_wizard_spaninformation"));
		SetItemDisplayCount(ThTi, nSpanCompositeCountVB);

		for (int i = 0; i < nSpanCompositeCountVB; i++)
		{
			pDoc->m_pAttrCtrl->GetSpav(aSpanCompositeKeyListVB[i], spavData);
			tStr.Format(_T("%s"), spavData.Name);
			InsertTreeItem(ThTi, WORK_SPAN_COMPOSTIE_VB_LST, tStr, _T("ico24_structure_wizard_spaninformation"));
		}
	}
	
	if (nSpanSteelGirdCount)
	{
		ThTi = InsertTreeItem(hTI, WORK_SPAN_STEELGIRDER_FLD, _LS(IDS_TMWK_NC_MSG188_STEELGIRDER), _T("ico24_structure_wizard_spaninformation"));
		SetItemDisplayCount(ThTi, nSpanSteelGirdCount);

		for (int i = 0; i < nSpanSteelGirdCount; i++)
		{
			pDoc->m_pAttrCtrl->GetSpan(aSpanSteelGirdKeyList[i], spanData);
			tStr.Format(_T("%s"), spanData.Name);
			InsertTreeItem(ThTi, WORK_SPAN_STEELGIRDER_LST, tStr, _T("ico24_structure_wizard_spaninformation"));
		}
	}

	// "PSC Value Flange Width" 
	if (nEfwdCount)
	{
		ThTi = InsertTreeItem(hTI, WORK_EFWD_FLD, _LS(IDS_TM_WORKTREE_NC_Efwd), _T("ico24_structure_wizard_effectivewidth"));
		SetItemDisplayCount(ThTi, nEfwdCount);

		T_SECT_D SectD;
		T_EFWD_D EfwdD;
		for (int i = 0; i < nEfwdCount; i++)
		{
			EfwdD.Initialize();
			if (!pDoc->m_pAttrCtrl2->GetEfwd(aEfwdKeyList[i], EfwdD)) ASSERT(0);

			SectD.Initialize();
			if (!pDoc->m_pAttrCtrl->GetSect(aEfwdKeyList[i], SectD)) continue;

			tStr.Format(_T(" %d : %s(PSC Value)"), aEfwdKeyList[i], SectD.SName);
			InsertTreeItem(ThTi, WORK_EFWD_LST, tStr, _T("ico24_structure_wizard_effectivewidth"));
		}
	}

	if (hTI != NULL)
	{
		if (bInit) Expand(hTI, TVE_EXPAND);// 최초에 보여줄 때는 한단계만...
		else ExpandCompletely(hTI, TRUE);
	}

	return hTI;
}

// Static Loads Item
HTREEITEM CTreeWorkCtrl::SetStaticLoadsItemTree(CDBDoc* pDoc, BOOL bInit)
{
	InitializeTree init_tree(this);

	HTREEITEM hTI, ThTi, ThTi2;
	CString   tStr;
	CArray<T_STLD_K, T_STLD_K> aStldKeyList;
	pDoc->m_pAttrCtrl->GetStldKeyList(aStldKeyList);

	// [2010-05-19] Kim, Geun Young (Tel: 2042, gykim@midasit.com) - PMS:4092
	UINT CrackedLCKey;
	CMapEx<UINT, UINT, UINT, UINT> mapKeyList; mapKeyList.InitHashTable(999);
	pDoc->m_pPostCtrl->GetCrackedLCKeyList(&mapKeyList);

	int nStldCount = aStldKeyList.GetSize();

	int nEtcLoadNum = pDoc->m_pAttrCtrl->GetCountTmld()
		+ pDoc->m_pAttrCtrl->GetCountCrpc()
		+ pDoc->m_pAttrCtrl->GetCountIfgs()
		+ pDoc->m_pAttrCtrl2->GetCountCmcs()
		+ pDoc->m_pAttrCtrl->GetCountStbk()
		+ pDoc->m_pAttrCtrl->GetCountUlcb();

	if (nEtcLoadNum && aStldKeyList.GetSize() == 0) nStldCount = 1;
	int nItemCount = nStldCount - mapKeyList.GetCount();

	// === Static Loads 표시 ===
	int nWvep = pDoc->m_pAttrCtrl2->GetCountWvep();
	int nWdfc = pDoc->m_pAttrCtrl2->GetCountWdfc();
	int nPosl = pDoc->m_pAttrCtrl->GetCountPosl();
	int nPosp = pDoc->m_pAttrCtrl->GetCountPosp();

	if (nWvep + nWdfc + nPosl + nPosp > 0 && nItemCount == 0)
		hTI = SetSub1TreeItem(WORK_STLD_FLD, bInit, nItemCount + 1, 26); //load case 는 0개인데 wvep 나 wdfc가 존재한다면.. 강제로 추가.
	else
		hTI = SetSub1TreeItem(WORK_STLD_FLD, bInit, nItemCount, 26);

	if (hTI == NULL) return NULL;

	if (nEtcLoadNum && aStldKeyList.GetSize() == 0) nStldCount = 0;

	// MQC 19877 : Pressure Load 대량 입력모델 속도 개선
	T_PRES_K  presKey;
	T_PRES_D  presData;
	std::map<T_STLD_K, int> mPresCount;
	auto pos = pDoc->m_pAttrCtrl->GetStartPres();
	while (pos)
	{
		pDoc->m_pAttrCtrl->GetNextPres(pos, presKey, presData);
		if (mPresCount.find(presData.LoadCaseKey) != mPresCount.end())
			mPresCount[presData.LoadCaseKey]++;
		else
			mPresCount[presData.LoadCaseKey] = 1;
	}

	T_ARPR_K  arprKey;
	T_ARPR_D  arprData;
	std::map<T_STLD_K, int> mArprCount;
	pos = pDoc->m_pAttrCtrl2->GetStartArpr();
	while (pos)
	{
		pDoc->m_pAttrCtrl2->GetNextArpr(pos, arprKey, arprData);
		if (mArprCount.find(arprData.StldK) != mArprCount.end())
			mArprCount[arprData.StldK]++;
		else
			mArprCount[arprData.StldK] = 1;
	}

	nStldFirePos = -1;
	// === Static Load Case 정보 표시 ===
	T_STLD_D stldData;
	for (int i = 0; i < nStldCount; i++)
	{
		if (mapKeyList.Lookup(aStldKeyList[i], CrackedLCKey)) continue;
		pDoc->m_pAttrCtrl->GetStld(aStldKeyList[i], stldData);
		tStr.Format(_LS(IDS_TMWK__MSG15), i + 1, stldData.LoadCaseName, stldData.Description);
		ThTi = InsertTreeItem(hTI, WORK_STLD_LST, tStr, _T("ico24_load_createloadcases_staticloadcases"));
		if (stldData.LoadCaseName == FIRE_LOAD_CASE_NAME)
			nStldFirePos = i;

		// Self Weight표시
		POSITION  bodfPos;
		T_BODF_K  bodfKey;
		T_BODF_D  bodfData;

		bodfPos = pDoc->m_pAttrCtrl->GetStartBodf();
		while (bodfPos != NULL)
		{
			pDoc->m_pAttrCtrl->GetNextBodf(bodfPos, bodfKey, bodfData);
			if (bodfData.LoadCaseKey == aStldKeyList[i])
			{
				tStr.Format(_LS(IDS_TMWK__MSG16));
				if (bodfData.SX != 0.0) { CString strAdd; strAdd.Format(_LS(IDS_TMWK__MSG17), bodfData.SX); tStr += strAdd; }
				if (bodfData.SY != 0.0) { CString strAdd; strAdd.Format(_LS(IDS_TMWK__MSG18), bodfData.SY); tStr += strAdd; }
				if (bodfData.SZ != 0.0) { CString strAdd; strAdd.Format(_LS(IDS_TMWK__MSG19), bodfData.SZ); tStr += strAdd; }
				tStr += CString(_T("]"));
				InsertTreeItem(ThTi, WORK_BODF_FLD, tStr, _T("ico24_load_structureloadsmasses_selfweight"));
			}
		}

		// Nodal Body Force
		POSITION  nbofPos;
		T_NBOF_K  nbofKey;
		T_NBOF_D  nbofData;

		nbofPos = pDoc->m_pAttrCtrl->GetStartNbof();
		while (nbofPos != NULL)
		{
			pDoc->m_pAttrCtrl->GetNextNbof(nbofPos, nbofKey, nbofData);
			if (nbofData.LoadCaseKey == aStldKeyList[i])
			{
				tStr.Format(_LS(IDS_TBWK_NODAL_BODY_FORCE));
				if (nbofData.dFactorX != 0.0) { CString strAdd; strAdd.Format(_LS(IDS_TBWK_NBOF_FX), nbofData.dFactorX); tStr += strAdd; }
				if (nbofData.dFactorY != 0.0) { CString strAdd; strAdd.Format(_LS(IDS_TBWK_NBOF_FY), nbofData.dFactorY); tStr += strAdd; }
				if (nbofData.dFactorZ != 0.0) { CString strAdd; strAdd.Format(_LS(IDS_TBWK_NBOF_FZ), nbofData.dFactorZ); tStr += strAdd; }
				tStr += CString(_T("]"));
				InsertTreeItem(ThTi, WORK_NBOF_FLD, tStr, _T("ico24_load_structureloadsmasses_nodalbodyforce"));
			}
		}

		// Nodal Loads 표시
		POSITION  cnldPos;
		T_CNLD_K  cnldKey;
		T_CNLD_D  cnldData;
		int       cnldNum = 0;

		cnldPos = pDoc->m_pAttrCtrl->GetStartCnld();
		while (cnldPos != NULL)
		{
			pDoc->m_pAttrCtrl->GetNextCnld(cnldPos, cnldKey, cnldData);
			if (cnldData.LoadCaseKey == aStldKeyList[i]) cnldNum += 1;
		}
		if (cnldNum)
		{
			ThTi2 = InsertTreeItem(ThTi, WORK_CNLD_FLD, _LS(IDS_TMWK_NC_MSG20), _T("ico24_load_structureloadsmasses_nodalloads"));
			SetItemDisplayCount(ThTi2, cnldNum);
		}

		// Specified Displacements of Supports 표시
		POSITION  sdspPos;
		T_SDSP_K  sdspKey;
		T_SDSP_D  sdspData;
		int       sdspNum = 0;

		sdspPos = pDoc->m_pAttrCtrl->GetStartSdsp();
		while (sdspPos != NULL)
		{
			pDoc->m_pAttrCtrl->GetNextSdsp(sdspPos, sdspKey, sdspData);
			if (sdspData.LoadCaseKey == aStldKeyList[i]) sdspNum += 1;
		}
		if (sdspNum)
		{
			ThTi2 = InsertTreeItem(ThTi, WORK_SDSP_FLD, _LS(IDS_TMWK_NC_MSG21), _T("ico24_load_structureloadsmasses_specifieddispl."));
			SetItemDisplayCount(ThTi2, sdspNum);
		}

		// Beam Load 표시
		POSITION  bmldPos;
		T_BMLD_K  bmldKey;
		T_BMLD_D  bmldData;
		int       bmldElemNum = 0, bmldLineNum = 0, bmldTypcNum = 0, bmldPrstNum = 0, bmldFlorNum = 0;

		bmldPos = pDoc->m_pAttrCtrl->GetStartBmld();
		while (bmldPos != NULL)
		{
			pDoc->m_pAttrCtrl->GetNextBmld(bmldPos, bmldKey, bmldData);
			if (bmldData.LoadCaseKey == aStldKeyList[i])
			{
				if (bmldData.LoadCommandType == D_BMLDTYPE_BEAM) bmldElemNum += 1;
				if (bmldData.LoadCommandType == D_BMLDTYPE_LINE) bmldLineNum += 1;
				if (bmldData.LoadCommandType == D_BMLDTYPE_TYPICAL) bmldTypcNum += 1;
				if (bmldData.LoadCommandType == D_BMLDTYPE_PRESTRESS) bmldPrstNum += 1;
				if (bmldData.LoadCommandType == D_BMLDTYPE_FLOOR) bmldFlorNum += 1;
			}
		}
		if (bmldElemNum)
		{
			ThTi2 = InsertTreeItem(ThTi, WORK_BMLD_ELEM_FLD, _LS(IDS_TMWK_NC_MSG22), _T("ico24_load_beamload_element"));
			SetItemDisplayCount(ThTi2, bmldElemNum);
		}
		if (bmldLineNum)
		{
			ThTi2 = InsertTreeItem(ThTi, WORK_BMLD_LINE_FLD, _LS(IDS_TMWK_NC_MSG23), _T("ico24_load_beamload_line"));
			SetItemDisplayCount(ThTi2, bmldLineNum);
		}
		if (bmldTypcNum)
		{
			ThTi2 = InsertTreeItem(ThTi, WORK_BMLD_TYPC_FLD, _LS(IDS_TMWK_NC_MSG24), _T("ico24_load_beamload_typical"));
			SetItemDisplayCount(ThTi2, bmldTypcNum);
		}
		if (bmldFlorNum)
		{
			ThTi2 = InsertTreeItem(ThTi, WORK_BMLD_FLOR_FLD, _LS(IDS_TMWK_NC_MSG25), _T("ico24_load_initialforcesetc_definefloorloadtype"));
			SetItemDisplayCount(ThTi2, bmldFlorNum);
		}

		// Floor Load 표시
		POSITION  fblaPos;
		T_FBLA_K  fblaKey;
		T_FBLA_D  fblaData;
		T_FBLD_D  fbldData;
		int       fblaNum = 0;

		fblaPos = pDoc->m_pAttrCtrl->GetStartFbla();
		while (fblaPos != NULL)
		{
			pDoc->m_pAttrCtrl->GetNextFbla(fblaPos, fblaKey, fblaData);
			pDoc->m_pAttrCtrl->GetFbld(fblaData.LoadTypeKey, fbldData);

			BOOL bExistSameKey = FALSE;
			for (int m = 0; m < FBLD_NUM; m++)
			{
				if (fbldData.LoadCaseKey[m] == aStldKeyList[i])
				{
					bExistSameKey = TRUE;
					break;
				}
			}
			if (bExistSameKey) fblaNum += 1;
		}
		if (fblaNum)
		{
			ThTi2 = InsertTreeItem(ThTi, WORK_FBLA_FLD, _LS(IDS_TMWK_NC_MSG26), _T("ico24_load_initialforcesetc_assignfloorloads2"));
			SetItemDisplayCount(ThTi2, fblaNum);
		}

		// Plane Load 표시
		POSITION  pnlaPos;
		T_PNLA_K  pnlaKey;
		T_PNLA_D  pnlaData;
		int       pnlaNum = 0;

		pnlaPos = pDoc->m_pAttrCtrl->GetStartPnla();
		while (pnlaPos != NULL)
		{
			pDoc->m_pAttrCtrl->GetNextPnla(pnlaPos, pnlaKey, pnlaData);
			if (pnlaData.LoadCaseKey == aStldKeyList[i]) pnlaNum += 1;
		}
		if (pnlaNum)
		{
			ThTi2 = InsertTreeItem(ThTi, WORK_PNLA_FLD, _LS(IDS_TMWK_NC_MSG187), _T("ico24_load_pressureload_assignplaneloads2"));
			SetItemDisplayCount(ThTi2, pnlaNum);
		}

		// Finishing Material Load
		POSITION FmldPos;
		T_FMLD_K FmldKey;
		T_FMLD_D FmldData;
		int      FmldNum = 0;

		FmldPos = pDoc->m_pAttrCtrl->GetStartFmld();
		while (FmldPos != NULL)
		{
			pDoc->m_pAttrCtrl->GetNextFmld(FmldPos, FmldKey, FmldData);
			if (FmldData.LoadCaseKey == aStldKeyList[i]) FmldNum += 1;
		}
		if (FmldNum)
		{
			ThTi2 = InsertTreeItem(ThTi, WORK_FMLD_FLD, _LS(IDS_TM_NC_WORKTREE_Finishing_Material_Load____d), _T("ico24_load_initialforcesetc_finishingmaterialloads"));
			SetItemDisplayCount(ThTi2, FmldNum);
		}

		// Prestress Beam Loads 표시
		POSITION  prstPos;
		T_PRST_K  prstKey;
		T_PRST_D  prstData;
		int       prstNum = 0;

		prstPos = pDoc->m_pAttrCtrl->GetStartPrst();
		while (prstPos != NULL)
		{
			pDoc->m_pAttrCtrl->GetNextPrst(prstPos, prstKey, prstData);
			if (prstData.LoadCaseKey == aStldKeyList[i]) prstNum += 1;
		}
		if (prstNum)
		{
			ThTi2 = InsertTreeItem(ThTi, WORK_PRST_FLD, _LS(IDS_TMWK_NC_MSG27), _T("ico24_load_prestressloads_prestressbeamloads"));
			SetItemDisplayCount(ThTi2, prstNum);
		}

		// Pretension Loads 표시
		POSITION  ptnsPos;
		T_PTNS_K  ptnsKey;
		T_PTNS_D  ptnsData;
		int       ptnsNum = 0;

		ptnsPos = pDoc->m_pAttrCtrl->GetStartPtns();
		while (ptnsPos != NULL)
		{
			pDoc->m_pAttrCtrl->GetNextPtns(ptnsPos, ptnsKey, ptnsData);
			if (ptnsData.LoadCaseKey == aStldKeyList[i]) ptnsNum += 1;
		}
		if (ptnsNum)
		{
#if defined (_MGEN)
			CString strSVGName = _T("ico24_load_prestressloads_pretensionloadsgen");
#else
			CString strSVGName = _T("ico24_load_prestressloads_pretensionloads");
#endif
			ThTi2 = InsertTreeItem(ThTi, WORK_PTNS_FLD, _LS(IDS_TMWK_NC_MSG28), strSVGName);
			SetItemDisplayCount(ThTi2, ptnsNum);
		}

		// External Type Load Case for Pretension 표시
		if (pDoc->m_pAttrCtrl->ExistExld())
		{
			T_EXLD_D ExldD;
			pDoc->m_pAttrCtrl->GetExld(ExldD);
			for (int k = 0; k < ExldD.nNumExldCase; k++)
			{
				if (ExldD.ExldCase[k] == aStldKeyList[i])
				{
					InsertTreeItem(ThTi, WORK_EXLD_FLD, _LS(IDS_TM_EXTERNAL_TYPE_LOADCASE_FOR_PRETENSION), _T("ico24_load_prestressloads_externaltypeloadcase"));
					break;
				}
			}
		}

		// Tendon Prestress Loads 표시
		POSITION  tdplPos;
		T_TDPL_K  tdplKey;
		T_TDPL_D  tdplData;
		int       tdplNum = 0;

		tdplPos = pDoc->m_pAttrCtrl->GetStartTdpl();
		while (tdplPos != NULL)
		{
			pDoc->m_pAttrCtrl->GetNextTdpl(tdplPos, tdplKey, tdplData);
			if (tdplData.LoadCaseKey == aStldKeyList[i]) tdplNum += 1;
		}
		if (tdplNum)
		{
			ThTi2 = InsertTreeItem(ThTi, WORK_TDPL_FLD, _LS(IDS_TM_NC_WORKTREE_Tendon_Prestress_Loads____d), _T("ico24_load_prestressloads_tendonprestress"));
			SetItemDisplayCount(ThTi2, tdplNum);
		}

		// Pressure Loads 표시
		int presNum = mPresCount[aStldKeyList[i]];
		if (presNum)
		{
			ThTi2 = InsertTreeItem(ThTi, WORK_PRES_FLD, _LS(IDS_TMWK_NC_MSG29), _T("ico24_load_pressureload_pressureloads"));
			SetItemDisplayCount(ThTi2, presNum);
		}

		// Arprsure Loads 표시
		int arprNum = mArprCount[aStldKeyList[i]];
		if (arprNum)
		{
			ThTi2 = InsertTreeItem(ThTi, WORK_ARPR_FLD, _LS(IDS_WG_TREEMENU_Pressure_Loads_AREA), _T("ico24_load_pressureload_assignareapressureloads"));
			SetItemDisplayCount(ThTi2, arprNum);
		}

		// System Temperature 표시
		POSITION  stmpPos;
		T_STMP_K  stmpKey;
		T_STMP_D  stmpData;

		stmpPos = pDoc->m_pAttrCtrl->GetStartStmp();
		while (stmpPos != NULL)
		{
			pDoc->m_pAttrCtrl->GetNextStmp(stmpPos, stmpKey, stmpData);
			if (stmpData.LoadCaseKey == aStldKeyList[i])
			{
				ThTi2 = InsertTreeItem(ThTi, WORK_STMP_FLD, _LS(IDS_TMWK_NC_MSG30), _T("ico24_load_temperatureloads_systemtemp"));
				SetItemDisplayCount(ThTi2, stmpData.dblSysTemp);
			}
		}

		// Nodal Temperatures 표시
		POSITION  ntmpPos;
		T_NTMP_K  ntmpKey;
		T_NTMP_D  ntmpData;
		int       ntmpNum = 0;

		ntmpPos = pDoc->m_pAttrCtrl->GetStartNtmp();
		while (ntmpPos != NULL)
		{
			pDoc->m_pAttrCtrl->GetNextNtmp(ntmpPos, ntmpKey, ntmpData);
			if (ntmpData.LoadCaseKey == aStldKeyList[i]) ntmpNum += 1;
		}
		if (ntmpNum)
		{
			ThTi2 = InsertTreeItem(ThTi, WORK_NTMP_FLD, _LS(IDS_TMWK_NC_MSG31), _T("ico24_load_temperatureloads_nodaltemp"));
			SetItemDisplayCount(ThTi2, ntmpNum);
		}

		// Element Temperatures 표시
		POSITION  etmpPos;
		T_ETMP_K  etmpKey;
		T_ETMP_D  etmpData;
		int       etmpNum = 0;

		etmpPos = pDoc->m_pAttrCtrl->GetStartEtmp();
		while (etmpPos != NULL)
		{
			pDoc->m_pAttrCtrl->GetNextEtmp(etmpPos, etmpKey, etmpData);
			if (etmpData.LoadCaseKey == aStldKeyList[i]) etmpNum += 1;
		}
		if (etmpNum)
		{
			ThTi2 = InsertTreeItem(ThTi, WORK_ETMP_FLD, _LS(IDS_TM_NC_WORKTREE_Element_Temperatures____d), _T("ico24_load_temperatureloads_elementtemp"));
			SetItemDisplayCount(ThTi2, etmpNum);
		}

		// Temperature Gradient 표시
		POSITION  gtmpPos;
		T_GTMP_K  gtmpKey;
		T_GTMP_D  gtmpData;
		int       gtmpNum = 0;

		gtmpPos = pDoc->m_pAttrCtrl->GetStartGtmp();
		while (gtmpPos != NULL)
		{
			pDoc->m_pAttrCtrl->GetNextGtmp(gtmpPos, gtmpKey, gtmpData);
			if (gtmpData.LoadCaseKey == aStldKeyList[i]) gtmpNum += 1;
		}
		if (gtmpNum)
		{
			ThTi2 = InsertTreeItem(ThTi, WORK_GTMP_FLD, _LS(IDS_TMWK_NC_MSG32), _T("ico24_load_temperatureloads_tempgradient"));
			SetItemDisplayCount(ThTi2, gtmpNum);
		}

		// Beam Section Temperature
		POSITION  BtmpPos;
		T_BTMP_K  BtmpKey;
		T_BTMP_D  BtmpData;
		int       BtmpNum = 0;

		BtmpPos = pDoc->m_pAttrCtrl->GetStartBtmp();
		while (BtmpPos != NULL)
		{
			pDoc->m_pAttrCtrl->GetNextBtmp(BtmpPos, BtmpKey, BtmpData);
			if (BtmpData.LoadCaseKey == aStldKeyList[i]) BtmpNum += 1;
		}
		if (BtmpNum)
		{
			ThTi2 = InsertTreeItem(ThTi, WORK_BTMP_FLD, _LS(IDS_TM_NC_WORKTREE_Beam_Temperature_Load____d), _T("ico24_load_temperatureloads_beamsectiontemp"));
			SetItemDisplayCount(ThTi2, BtmpNum);
		}

		// Plate Thickness Temperature
		POSITION  PtmpPos;
		T_PTMP_K  PtmpKey;
		T_PTMP_D  PtmpData;
		int       PtmpNum = 0;

		PtmpPos = pDoc->m_pAttrCtrl->GetStartPtmp();
		while (PtmpPos != NULL)
		{
			pDoc->m_pAttrCtrl->GetNextPtmp(PtmpPos, PtmpKey, PtmpData);
			if (PtmpData.LoadCaseKey == aStldKeyList[i]) PtmpNum += 1;
		}
		if (PtmpNum)
		{
			tStr.Format(_LS(IDS_TM_WORKTREE_Plate_Thickness_Temperature_Load____d), PtmpNum);
			InsertTreeItem(ThTi, WORK_PTMP_FLD, tStr, _T("ico24_load_temperatureloads_elementtemp"));
		}

	
		// Wind Loads 표시
		POSITION  windPos;
		T_WIND_K  windKey;
		T_WIND_D  windData;
		CString   csCodeName;

		windPos = pDoc->m_pAttrCtrl->GetStartWind();
		while (windPos != NULL)
		{
			csCodeName.Empty();
			pDoc->m_pAttrCtrl->GetNextWind(windPos, windKey, windData);
			if (windKey == aStldKeyList[i] ||
				(windData.nCodeType == KBC_W_2016 && (windData.CodeParam.KBC2015.keyWA == aStldKeyList[i] || windData.CodeParam.KBC2015.keyWT == aStldKeyList[i])) ||
				(windData.nCodeType == KDS_W_2019 && (windData.CodeParam.KDS2019.keyWA == aStldKeyList[i] || windData.CodeParam.KDS2019.keyWT == aStldKeyList[i])) ||
				(windData.nCodeType == KDS_W_2022 && (windData.CodeParam.KDS2021.keyWA == aStldKeyList[i] || windData.CodeParam.KDS2021.keyWT == aStldKeyList[i])) ||
				(windData.nCodeType == DPT_W_2007 && (windData.CodeParam.DPT2007.keyWA == aStldKeyList[i] || windData.CodeParam.DPT2007.keyWT == aStldKeyList[i])))
			{
				tStr.Format(_LS(IDS_TMWK__MSG33));
				if (!CDBLib::GetWindCodeNameByType(windData.nCodeType, csCodeName)) ASSERT(0);
				tStr += csCodeName;
				tStr += _T("]");
				if (windKey == aStldKeyList[i])
					InsertTreeItem(ThTi, WORK_WIND_FLD, tStr, _T("ico24_load_lateral_windloads"));
				else
					InsertTreeItem(ThTi, WORK_WIND_WA_WT_FLD, tStr, _T("ico24_load_lateral_windloads"));
			}
		}

		// Static Seismic Loads 표시
		POSITION  seisPos;
		T_SEIS_K  seisKey;
		T_SEIS_D  seisData;

		seisPos = pDoc->m_pAttrCtrl->GetStartSeis();
		while (seisPos != NULL)
		{
			csCodeName.Empty();
			pDoc->m_pAttrCtrl->GetNextSeis(seisPos, seisKey, seisData);
			if (seisKey == aStldKeyList[i])
			{
				tStr.Format(_LS(IDS_TMWK__MSG39));
				if (!CDBLib::GetSeisCodeNameByType(seisData.nCodeType, csCodeName)) ASSERT(0);
				tStr += csCodeName;
				tStr += _T("]");
				InsertTreeItem(ThTi, WORK_SEIS_FLD, tStr, _T("ico24_load_lateral_seismicloads"));
			}
		}

		//Peusdo Force
		POSITION  psllPos;
		T_PSLL_K  psllKey;
		T_PSLL_D  psllData;

		psllPos = pDoc->m_pAttrCtrl->GetStartPsll();
		while (psllPos != NULL)
		{
			csCodeName.Empty();
			pDoc->m_pAttrCtrl->GetNextPsll(psllPos, psllKey, psllData);
			if (psllKey == aStldKeyList[i])
			{
				tStr.Format(_LS(IDS_TMWK__PSLL));
				csCodeName = CDBLib::GetSeisEvalCodeNameByMethod(psllData.nCodeType);

				tStr += csCodeName;
				tStr += _T("]");
				InsertTreeItem(ThTi, ID_MAIN_RIBBON_SEISEVAL_PSEUDO_FORCE, tStr, _T("ico24_rating_bridgeratingdesign_dropmenu1_ratingdesigncode"));
			}
		}

		// Superstructure Seismic Loads
		POSITION sseiPos;
		T_SSEI_K sseiKey;
		T_SSEI_D sseiData;

		sseiPos = pDoc->m_pAttrCtrl->GetStartSsei();
		while (sseiPos != NULL)
		{
			pDoc->m_pAttrCtrl->GetNextSsei(sseiPos, sseiKey, sseiData);
			if (sseiKey == aStldKeyList[i])
			{
				tStr.Format(_LS(IDS_TMWK_SUPER_SIES_LOAD),
					sseiData.dAngle, sseiData.dKh);
				InsertTreeItem(ThTi, WORK_SSEI_FLD, tStr, _T("ico24_boundary_springsupports_integralbridge"));
			}
		}

		// Wind Pressure.. 풍하중 자동계산...    
		POSITION wdprPos;
		T_WDPR_K wdprKey;
		T_WDPR_D wdprData;

		wdprPos = pDoc->m_pAttrCtrl2->GetStartWdpr();
		int nCntWdprA = 0; // Area
		int nCntWdprB = 0; // Beam
		int nCntWdprN = 0; // Nodal
		int nCntWdprF = 0; // Function
		BOOL bEnableWindP = CDBDoc::IsEnableWindPressure();
		while (wdprPos != NULL && bEnableWindP)
		{
			pDoc->m_pAttrCtrl2->GetNextWdpr(wdprPos, wdprKey, wdprData);
			if (wdprData.KeyStld == aStldKeyList[i])
			{
				switch (wdprData.nType)
				{
				case 1: nCntWdprA++; break; //Area
				case 2: nCntWdprB++; break; //Beam
				case 3: nCntWdprN++; break; //Nodal 
				case 4: nCntWdprF++; break; //Function
				}
			}
		}

		int nCntEpse = 0; // Static Earth Pressure
		int nCntEpst = 0; // Seismic Earth Pressure		
		POSITION epsePos = pDoc->m_pAttrCtrl2->GetStartEpse();
		T_EPSE_K epseKey;
		T_EPSE_D epseData;
		while (epsePos)
		{
			pDoc->m_pAttrCtrl2->GetNextEpse(epsePos, epseKey, epseData);
			if (epseData.KeyStld == aStldKeyList[i]) nCntEpse++;
		}
		POSITION epstPos = pDoc->m_pAttrCtrl2->GetStartEpst();
		T_EPST_K epstKey;
		T_EPST_D epstData;
		while (epstPos)
		{
			pDoc->m_pAttrCtrl2->GetNextEpst(epstPos, epstKey, epstData);
			if (epstData.KeyStld == aStldKeyList[i]) nCntEpst++;
		}

		if (nCntWdprA > 0)
		{
			ThTi2 = InsertTreeItem(ThTi, WORK_WDPR_AREA_FLD, _LS(IDS_TM_Wind_Pressure_Area), _T("ico24_load_lateral_windpressure_areawindpressure"));
			SetItemDisplayCount(ThTi2, nCntWdprA);
		}
		if (nCntWdprB > 0)
		{
			ThTi2 = InsertTreeItem(ThTi, WORK_WDPR_BEAM_FLD, _LS(IDS_TM_Wind_Pressure_Beam), _T("ico24_load_lateral_windpressure_beamwindpressure"));
			SetItemDisplayCount(ThTi2, nCntWdprB);
		}
		if (nCntWdprN > 0)
		{
			ThTi2 = InsertTreeItem(ThTi, WORK_WDPR_NODAL_FLD, _LS(IDS_TM_Wind_Pressure_Nodal), _T("ico24_load_lateral_windpressure_nodalwindpressure"));
			SetItemDisplayCount(ThTi2, nCntWdprN);
		}
		if (nCntWdprF > 0)
		{
			ThTi2 = InsertTreeItem(ThTi, WORK_WDPR_FUNC_FLD, _LS(IDS_TM_Wind_Pressure_Function), _T("ico24_load_lateral_windpressure_functionwindpressure"));
			SetItemDisplayCount(ThTi2, nCntWdprF);
		}
		if (nCntEpse > 0)
		{
			ThTi2 = InsertTreeItem(ThTi, WORK_EPSE_FLD, _LS(IDS_TB_EARTHP_SEIS), _T("ico24_load_pressureload_seismicearthpressure"));
			SetItemDisplayCount(ThTi2, nCntEpse);
		}
		if (nCntEpst > 0)
		{
			ThTi2 = InsertTreeItem(ThTi, WORK_EPST_FLD, _LS(IDS_TB_EARTHP_STATIC), _T("ico24_load_pressureload_seismicearthpressure"));
			SetItemDisplayCount(ThTi2, nCntEpst);
		}
	}

	if (nEtcLoadNum) // 현재는 ETC 하중에 포함된 하중이 Time Load 밖에 없으므로
	{
		// === ETC 하중 ====
		ThTi = InsertTreeItem(hTI, WORK_ETCLD_FLD, _LS(IDS_TM_WORKTREE_ETC_Loads), _T("ico24_load_misc_waveload"));

		// Time Loads 표시
		int tmlcNum = pDoc->m_pAttrCtrl->GetCountTmld();
		if (tmlcNum)
		{
			ThTi2 = InsertTreeItem(ThTi, WORK_TMLD_FLD, _LS(IDS_TM_NC_WORKTREE_Time_Loads____d_), _T("ico24_load_constructionstagedata_timeloadsforconstructionstage"));
			SetItemDisplayCount(ThTi2, tmlcNum);
		}

		// Creep Coefficient for Construction Stage 표시
		int crpcNum = pDoc->m_pAttrCtrl->GetCountCrpc();
		if (crpcNum)
		{
			ThTi2 = InsertTreeItem(ThTi, WORK_CRPC_FLD, _LS(IDS_TM_NC_WORKTREE_Creep_Coefficient_for_Construction_), _T("ico24_load_constructionstagedata_creepcoefficientforconstructionstage"));
			SetItemDisplayCount(ThTi2, crpcNum);
		}

		// Camber for Construction Stage
		int CmcsNum = pDoc->m_pAttrCtrl2->GetCountCmcs();
		if (CmcsNum)
		{
			ThTi2 = InsertTreeItem(ThTi, WORK_CMCS_FLD, _LS(IDS_TM_NC_WORKTREE_Camber_for_Construction_Stage_), _T("ico24_load_constructionstagedata_camberforcs"));
			SetItemDisplayCount(ThTi2, CmcsNum);
		}

		// Set-Back for Construction Stage
		int StbkNum = pDoc->m_pAttrCtrl->GetCountStbk();
		if (StbkNum)
		{
			ThTi2 = InsertTreeItem(ThTi, WORK_STBK_FLD, _LS(IDS_TM_NC_WORKTREE_Set_Back_for_Construction_Stage_), _T("ico24_load_constructionstagedata_setbackloadsfornonlinearconstructionstage"));
			SetItemDisplayCount(ThTi2, StbkNum);
		}

		// Unstrained Length of Cable for Nonlinear Construction Stage
		int UlcbNum = pDoc->m_pAttrCtrl->GetCountUlcb();
		if (UlcbNum)
		{
			ThTi2 = InsertTreeItem(ThTi, WORK_ULCB_FLD, _LS(IDS_TM_NC_WORKTREE_Unstrained_Length_of_Cable_for_Construction_Stage_), _T("ico24_results_tables_cable"));
			SetItemDisplayCount(ThTi2, UlcbNum);
		}
	}

	m_aWvepKey.RemoveAll();
	if (nWvep > 0)
	{
		tStr = _LS(IDS_TM_WINDP_VELOCITY);
		ThTi = InsertTreeItem(hTI, WORK_WVEP_FLD, tStr, _T("ico24_load_lateral_windpressure_velocitypressure"));
		POSITION posWvep = pDoc->m_pAttrCtrl2->GetStartWvep();
		T_WVEP_K WvepK;
		T_WVEP_D WvepD;
		CString strCodeName;
		while (posWvep)
		{
			pDoc->m_pAttrCtrl2->GetNextWvep(posWvep, WvepK, WvepD);
			m_aWvepKey.Add(WvepK);
			if (!CWindLoadGeneratorCtrl::GetWindCodeNameByCode(WvepD.nCodeType, strCodeName)) continue;
			tStr = WvepD.StrName + _T(" [") + strCodeName + _T("]");
			InsertTreeItem(ThTi, WORK_WVEP_LST, tStr, _T("ico24_load_lateral_windpressure_velocitypressure"));
		}
	}

	m_aWdfcKey.RemoveAll();
	if (nWdfc > 0)
	{
		tStr = _LS(IDS_TM_WINDP_FUNCTION);
		ThTi = InsertTreeItem(hTI, WORK_WDFC_FLD, tStr, _T("ico24_load_lateral_windpressure_windpressurefunction"));
		POSITION posWdfc = pDoc->m_pAttrCtrl2->GetStartWdfc();
		T_WDFC_K WdfcK;
		T_WDFC_D WdfcD;
		CString strCoord;
		while (posWdfc)
		{
			pDoc->m_pAttrCtrl2->GetNextWdfc(posWdfc, WdfcK, WdfcD);
			m_aWdfcKey.Add(WdfcK);
			if (WdfcD.nCoordType == 1)      strCoord = _LS(IDS_CMD_WINDP_FUNCTION_DEF_COORD_REC);
			else if (WdfcD.nCoordType == 2) strCoord = _LS(IDS_CMD_WINDP_FUNCTION_DEF_COORD_CYL);
			else continue;
			tStr = WdfcD.strName + _T(" [") + strCoord + _T("]");
			InsertTreeItem(ThTi, WORK_WDFC_LST, tStr, _T("ico24_load_lateral_windpressure_windpressurefunction"));
		}
	}

	//if (!m_bCivil)
	{
		m_aPoslKey.RemoveAll();
		if (nPosl > 0)
		{
			tStr = _LS(IDS_TM_PARAMETER_SEISMIC_LOAD);
			ThTi = InsertTreeItem(hTI, WORK_POSL_FLD, tStr, _T("ico24_load_timehistoryanalysisdata_timehistoryfunction"));

			CArray<T_POSL_K, T_POSL_K> aPoslK;
			pDoc->m_pAttrCtrl->GetPoslKeyList(aPoslK);

			T_POSL_D PoslD;
			CString strCoord;
			for (int i = 0; i < aPoslK.GetSize(); i++)
			{
				if (!pDoc->m_pAttrCtrl->GetPosl(aPoslK[i], PoslD)) { ASSERT(0); continue; }
				m_aPoslKey.Add(aPoslK[i]);
				strCoord = pDoc->m_pAttrCtrl->GetPoslCodeName(PoslD.nCodeType);
				tStr = PoslD.strName + _T(" [") + strCoord + _T("]");
				InsertTreeItem(ThTi, WORK_POSL_LST, tStr, _T("ico24_load_timehistoryanalysisdata_timehistoryfunction"));
			}
		}

		m_aPospKey.RemoveAll();
		if (nPosp > 0)
		{
			tStr = _LS(IDS_TM_PARAMTER_SOIL_PROPERTY);
			ThTi = InsertTreeItem(hTI, WORK_POSP_FLD, tStr, _T("ico24_load_pressureload_parametersofsoilproperties"));

			CArray<T_POSP_K, T_POSP_K> aPospK;
			pDoc->m_pAttrCtrl->GetPospKeyList(aPospK);

			T_POSP_D PospD;
			CString strCoord;
			for (int i = 0; i < aPospK.GetSize(); i++)
			{
				if (!pDoc->m_pAttrCtrl->GetPosp(aPospK[i], PospD)) { ASSERT(0); continue; }
				m_aPospKey.Add(aPospK[i]);
				tStr = PospD.strName;
				InsertTreeItem(ThTi, WORK_POSP_LST, tStr, _T("ico24_load_pressureload_parametersofsoilproperties"));
			}
		}
	}
	
	if (hTI != NULL)
	{
		if (bInit) Expand(hTI, TVE_EXPAND);// 최초에 보여줄 때는 한단계만...
		else ExpandCompletely(hTI, TRUE);
	}
	return hTI;
}

// Static Loads Type Item
HTREEITEM CTreeWorkCtrl::SetStaticLoadsTypeItemTree(CDBDoc* pDoc, BOOL bInit)
{
	InitializeTree init_tree(this);

	HTREEITEM hTI;
	int nItemCount = 1;//

	BOOL bHaveCnldType = FALSE;
	CArray<T_STLD_K, T_STLD_K> aStldKeyList;
	pDoc->m_pAttrCtrl->GetStldKeyList(aStldKeyList);
	int nStldCount = aStldKeyList.GetSize();
	for (int i = 0; i < nStldCount; i++)
	{
		T_STLD_K KeyStld = aStldKeyList[i];
		CArray<T_CNLD_D, T_CNLD_D&> aData;
		CArray<CArrayEx<T_CNLD_KEY, T_CNLD_KEY&>, CArrayEx<T_CNLD_KEY, T_CNLD_KEY&>&> aArrCnldK;
		pDoc->m_pAttrCtrl->GetCnldTypeList(KeyStld, aData, aArrCnldK);
		if (aArrCnldK.IsEmpty())
			continue;
		bHaveCnldType = TRUE;
		break;
	}


	if (!bHaveCnldType)
	{
		//Delete WORK_STLD_TYPE_FLD
		HTREEITEM   hNextItem, hChildItem;
		BOOL  bExist = FALSE;
		if (ItemHasChildren(m_hRootTi) == TRUE)
		{
			hChildItem = GetChildItem(m_hRootTi);
			while (hChildItem != NULL)
			{
				hNextItem = GetNextSiblingItemWithoutFilter(hChildItem);
				UINT Data = GetItemData(hChildItem);
				if (Data == WORK_STLD_TYPE_FLD) { bExist = TRUE; break; }
				hChildItem = hNextItem;
			}
		}
		if (bExist)
		{
			{ DeleteItem(hChildItem); return NULL; }
		}
		return NULL;
	}
	hTI = SetSub1TreeItem(WORK_STLD_TYPE_FLD, bInit, nItemCount, 26);

	SetStaticCnldTypeLoadsItemTree(hTI);

	if (hTI != NULL)
	{
		if (bInit) Expand(hTI, TVE_EXPAND);
		else ExpandCompletely(hTI, TRUE);
	}

	return hTI;
}

