	int nMvldCount = aMvldchKeyList.GetSize();

	int nMvcdCount = (nCode == D_MOVE_CODE_NONE) ? 0 : 1;

	// === Moving Load Analysis 표시 ===
	hTI = SetSub1TreeItem(WORK_MVLDANLch_FLD, bInit, nMvcdCount + nLlanCount + nSlanCount + nLlanopCount + nSlanopCount + nSinfCount + nMvhlCount + nMvhcCount + nMvldCount, 56);
	if (hTI == NULL) return NULL;

	// Moving Load Code  
	int nMvcd = m_aMvcdData.GetSize();
