	for (n = 0; n < nMvcd; n++)
		if (m_aMvcdData[n] == nCode) break;
	ASSERT(n != nMvcd);
	tStr.Format(_LS(IDS_TM_WORKTREE_Moving_Load_Code), m_aMvcdStr[n]);
	InsertTreeItem(hTI, WORK_MVCD_FLD, tStr, _T("ico24_load_movingloadanalysisdata_movingloadcases"));

