//Steel Fire Item
HTREEITEM CTreeWorkCtrl::SetFireSteelItemTree(CDBDoc* pDoc, BOOL bInit)
{
	InitializeTree init_tree(this);

	HTREEITEM hTI, ThTi;
	CString   tStr;
	CArray<T_FLUE_K, T_FLUE_K> aFlueKeyList;
	CArray<T_STTF_K, T_STTF_K> aSttfKeyList;
	CArray<T_FIPA_K, T_FIPA_K> aFipaKeyList;
	CArray<T_FSSF_K, T_FSSF_K> aFssfKeyList;

	pDoc->m_pAttrCtrl->GetFlueKeyList(aFlueKeyList);
	pDoc->m_pAttrCtrl->GetSttfKeyList(aSttfKeyList);
	pDoc->m_pAttrCtrl->GetFipaKeyList(aFipaKeyList);
	pDoc->m_pAttrCtrl->GetFssfKeyList(aFssfKeyList);

	int nFlueCount = aFlueKeyList.GetSize();
	int nSttfCount = aSttfKeyList.GetSize();
	int nFipaCount = aFipaKeyList.GetSize();
	int nFssfCount = aFssfKeyList.GetSize();
	qsort(aFlueKeyList.GetData(), aFlueKeyList.GetSize(), sizeof(T_FLUE_K), CCompFunc::UINTAsc);

	hTI = SetSub1TreeItem(WORK_FIRE_FLD, bInit, nFlueCount + nSttfCount + nFipaCount + nFssfCount, 58);
	// Flue
	if (nFlueCount)
	{
		ThTi = InsertTreeItem(hTI, WORK_FLUE_FLD, _LS(IDS_TM_WORKTREE_Fire_Flue____d_NC), _T("ico24_mods_design_dropmenu1_loadcombinationtype"));
		SetItemDisplayCount(ThTi, nFlueCount);
		T_FLUE_D FlueData;
		CString str[] = { _LS(IDS_TM_WORKTREE_Fire_Code),_LS(IDS_TM_WORKTREE_Fire_User) };
		for (int i = 0; i < nFlueCount; i++)
		{
			T_MATL_D  matlData;
			pDoc->m_pAttrCtrl->GetFlue(aFlueKeyList[i], FlueData);
			tStr.Format(_LS(IDS_TM_WORKTREE__s___Type__s), FlueData.strFlueName, str[FlueData.nType]);
			InsertTreeItem(ThTi, WORK_FLUE_LST, tStr, _T("ico24_mods_design_dropmenu1_loadcombinationtype"));
		}
	}
	if (nSttfCount)
	{
		ThTi = InsertTreeItem(hTI, WORK_STTF_FLD, _LS(IDS_TM_WORKTREE_Fire_Sttf____d_NC), _T("ico24_mods_design_dropmenu1_loadcombinationtype"));
		SetItemDisplayCount(ThTi, nSttfCount);
		T_STTF_D SttfData;
		for (int i = 0; i < nSttfCount; i++)
		{
			T_MATL_D  matlData;
			pDoc->m_pAttrCtrl->GetSttf(aSttfKeyList[i], SttfData);
			tStr.Format(_T("%s"), SttfData.strSttfName);
			InsertTreeItem(ThTi, WORK_STTF_LST, tStr, _T("ico24_mods_design_dropmenu1_loadcombinationtype"));
		}
	}
	if (nFipaCount)
	{
		ThTi = InsertTreeItem(hTI, WORK_FIPA_FLD, _LS(IDS_WG_TREEMENU_Fire_Parameter), _T("ico24_mods_design_dropmenu1_loadcombinationtype"));
		T_FIPA_D FipaData;
		int addFg = 1;
		for (int i = 0; i < 4; i++)
			m_aFipaItemKey[i].RemoveAll();
		for (int i = 0; i < nFipaCount; i++)
		{
			pDoc->m_pAttrCtrl->GetFipa(aFipaKeyList[i], FipaData);
			m_aFipaItemKey[FipaData.firetype].Add(aFipaKeyList[i]);
		}
		CString str[] = { _LS(IDS_TM_TREEMENU_FIPA_TYPE1),_LS(IDS_TM_TREEMENU_FIPA_TYPE2),_LS(IDS_TM_TREEMENU_FIPA_TYPE3),_LS(IDS_TM_TREEMENU_FIPA_TYPE4) };
		for (int i = 0; i < 4; i++)
		{
			if (!m_aFipaItemKey[i].IsEmpty())
			{
				HTREEITEM ThTi2 = InsertTreeItem(ThTi, WORK_FIPA_LST, str[i], _T("ico24_mods_design_dropmenu1_loadcombinationtype"));
				SetItemDisplayCount(ThTi2, m_aFipaItemKey[i].GetSize());
			}
		}
	}
	if (nFssfCount)
	{
		ThTi = InsertTreeItem(hTI, WORK_FSSF_FLD, _LS(IDS_WG_TREEMENU_Fire_Sect_Shape_Coe), _T("ico24_mods_design_dropmenu1_loadcombinationtype"));
		SetItemDisplayCount(ThTi, nFssfCount);
	}
	if (hTI != NULL)
	{
		if (bInit) Expand(hTI, TVE_EXPAND);// 최초에 보여줄 때는 한단계만...
		else ExpandCompletely(hTI, TRUE);
	}

	return hTI;
}

