		T_BNGR_D DataBngr;

		for (int i = 0; i < nCglpCount; i++)
		{
			pDoc->m_pAttrCtrl->GetCglp(aCglpKeyList[i], DataCglp);
			pDoc->m_pAttrCtrl->GetNlnk(DataCglp.GLinkK, DataNlnk);
			pDoc->m_pAttrCtrl->GetNllp(DataNlnk.PropKey, DataNllpOld);
			pDoc->m_pAttrCtrl->GetNllp(DataCglp.GLinkPropK, DataNllpNew);
			if (!pDoc->m_pAttrCtrl->GetBngr(DataCglp.GroupKey, DataBngr))
				DataBngr.GroupName = _LS(IDS_WG_TREEMENU_ADD3_Default);

			tStr.Format(_T("Link %d [ Node=%ld, %ld ; %s -> %s ; Group=%s ]"),
				DataCglp.GLinkK, DataNlnk.Node1, DataNlnk.Node2,
				DataNllpOld.PropName, DataNllpNew.PropName, DataBngr.GroupName);
			InsertTreeItem(ThTi, WORK_CGLP_LST, tStr, _T("ico24_boundary_link_changegenerallinkproperties"));
		}
