			ThTi2 = InsertTreeItem(ThTi, WORK_SDVI_FLD, _LS(IDS_TM_MENUCTRL_SDVI), _T("ico24_boundary_link_viscousdamperoildamper"));
			SetItemDisplayCount(ThTi2, nSdviCount);

			CString strDamper[] = { _LS(IDS_TM_MENUCTRL_SDVI_SINGLE), _LS(IDS_TM_MENUCTRL_SDVI_KELVIN), _LS(IDS_TM_MENUCTRL_SDVI_MAXWEL) };
			CString strDashpot[] = { _LS(IDS_TM_MENUCTRL_SDVI_DASHPOT_LINEAR), _LS(IDS_TM_MENUCTRL_SDVI_DASHPOT_BILINEAR), _LS(IDS_TM_MENUCTRL_SDVI_DASHPOT_EXFUNC) };
