void CTreeWorkCtrl::SetRebarRebwDataItemTree(CDBDoc* pDoc, int nRebwCount, CArray<T_REBW_K, T_REBW_K>& aRebwK, HTREEITEM& hTI)
{
	CString strData, strName, strSpace;

	T_UNIT_INDEX UnitIndex;
	pDoc->m_pUnitCtrl->GetUnitIndexCurrent(UnitIndex);
	int nTgtUnitL = D_UNITSYS_LENGTH_INDEX_MM;
	if (UnitIndex.nBase_Length == D_UNITSYS_LENGTH_INDEX_IN || UnitIndex.nBase_Length == D_UNITSYS_LENGTH_INDEX_FT)
		nTgtUnitL = D_UNITSYS_LENGTH_INDEX_IN;

	BOOL bInsertRebwTree = FALSE;
	HTREEITEM hTI2 = NULL;

	T_REBW_D RebwD;
	for (int i = 0; i < nRebwCount; i++)
	{
		T_REBW_K RebwK = aRebwK[i];

		if (RebwK.key.storid)
		{
			//         CArray<T_ELEM_K,T_ELEM_K> aElemK;
			//         int nElemSize = pDoc->m_pAttrCtrl->GetElemKeyListUseRebw(RebwK, aElemK);
			//         if(nElemSize < 1)   continue;
		}

		if (!bInsertRebwTree)
		{
			hTI2 = InsertTreeItem(hTI, WORK_REBW_FLD, _LS(IDS_WG_TREEMENU_Wall), _T("ico24_design_design_dropmenu2_modifywallrebardata"));
			bInsertRebwTree = TRUE;
		}

		int nWallID = RebwK.key.wallid;
		if (!pDoc->m_pAttrCtrl->GetRebw(RebwK, RebwD)) { ASSERT(0);		continue; }

		if (RebwK.key.storid)
		{
			T_STOR_D StorD;
			if (!pDoc->m_pAttrCtrl->GetStor(RebwK.key.storid, StorD)) { ASSERT(0);		continue; }
			strName.Format(_T("%d-%s"), nWallID, StorD.StoryName);
		}
		else strName.Format(_T("%d"), nWallID);

		double dSpaceV = pDoc->m_pUnitCtrl->ConvertCurUnitData2TgtUnit(0, nTgtUnitL, D_UNITSYS_BASE_LENGTH, RebwD.dVerticalRebarSpace);
		double dSpaceH = pDoc->m_pUnitCtrl->ConvertCurUnitData2TgtUnit(0, nTgtUnitL, D_UNITSYS_BASE_LENGTH, RebwD.dHorizonRebarSpace);
		double dSpaceE = pDoc->m_pUnitCtrl->ConvertCurUnitData2TgtUnit(0, nTgtUnitL, D_UNITSYS_BASE_LENGTH, RebwD.dEndRebarSpace);

		CString strSpaceV, strSpaceH, strSpaceE;
		strSpaceV.Format(_T("%.0f"), dSpaceV);
		strSpaceH.Format(_T("%.0f"), dSpaceH);
		strSpaceE.Format(_T("%.0f"), dSpaceE);

		strData.Format(_T("%s (%s@%s %s@%s %d-%s@%s)"), strName,
			RebwD.VerticalRebarName, strSpaceV, RebwD.HorizonRebarName, strSpaceH,
			RebwD.nNumEndRebar, RebwD.EndRebarName, strSpaceE);

		InsertTreeItem(hTI2, WORK_REBW_LST, strData, _T("ico24_design_design_dropmenu2_modifywallrebardata"));
	}
}

