	if (UnitIndex.nBase_Length == D_UNITSYS_LENGTH_INDEX_IN || UnitIndex.nBase_Length == D_UNITSYS_LENGTH_INDEX_FT)
		nTgtUnitL = D_UNITSYS_LENGTH_INDEX_IN;

	BOOL bInsertRipbTree = FALSE;
