HTREEITEM CTreeWorkCtrl::SetDomainDataItemTree(CDBDoc* pDoc, BOOL bInit/*=TRUE*/)
{
	InitializeTree init_tree(this);

	M_PROFILE('CTreeWorkCtrl::SetDomainDataItemTree');

	BOOL bTestCode = FALSE;
	if (CTestEnvMgr::IsTestEnvST(_T("TestCode"), _T("yes"))) bTestCode = TRUE;

	BOOL bApplyPPL = FALSE;
	if (CTestEnvMgr::IsTestEnvST(_T("ApplyPPL"), _T("yes"))) bApplyPPL = TRUE;
	if (bApplyPPL)
	{
		return SetDomainDataItemTree_Test(pDoc, bInit);
	}

	LARGE_INTEGER initStart, initEnd, mapStart, mapEnd, calcStart, calcEnd;
	if (bTestCode) QueryPerformanceCounter(&initStart);

	HTREEITEM hTI = NULL;
	CString   tStr;
	std::vector<T_MADO_K> aMadoK;
	std::vector<T_SBDO_K> aSbdoK;

	pDoc->m_pAttrCtrl->GetMadoKeyList(aMadoK);
	pDoc->m_pAttrCtrl->GetSbdoKeyList(aSbdoK);

	int nMadoCount = (int)aMadoK.size();
	int nSbdoCount = (int)aSbdoK.size();

	int nTotalcount = nMadoCount;

	if (bTestCode)
	{
		QueryPerformanceCounter(&mapStart);
		initEnd = mapStart;
	}

	hTI = SetSub1TreeItem(WORK_DOMN_FLD, bInit, nTotalcount, 0);
	if (hTI == NULL) return NULL;

	std::map<T_MADO_K, int> mapMado2Count;
	typedef pair<T_MADO_K, int> pairMado;
	std::map<T_MADO_K, int>::iterator itr;
	T_DOEL_K DoelK = 0;
	T_DOEL_D DoelD;
	POSITION pos = pDoc->m_pAttrCtrl->GetStartDoel();
	while (pos)
	{
		pDoc->m_pAttrCtrl->GetNextDoel(pos, DoelK, DoelD);
		if (DoelD.nDomainType != 0) continue;

		itr = mapMado2Count.find(DoelD.KeyDomain);

		int nCount = 0;
		if (itr == mapMado2Count.end()) nCount++;
		else
		{
			nCount = itr->second;
			nCount++;
		}

		mapMado2Count.insert(pairMado(DoelD.KeyDomain, nCount));
	}

	if (bTestCode)
	{
		QueryPerformanceCounter(&calcStart);
		mapEnd = calcStart;
	}

	if (nMadoCount)
	{
		HTREEITEM hTI2 = NULL;

		std::vector<T_SBDO_K> arSbdoKey; arSbdoKey.clear();
		std::vector<T_ELEM_K> arSbdoElemKey; arSbdoElemKey.clear();

		CArray<T_DOEL_K, T_DOEL_K> aDoelK;
		pDoc->m_pAttrCtrl->GetDoelKeyList(aDoelK);

		TCHAR strSbdoType[SBDO_TYPE_NUM][12] = { _T("None"), _T("Slab"), _T("Mat"), _T("Wall"), _T("Shell") };
		CString aSbdoTypeCvl[4] = { _LS(IDS_TM_DOMAIN_NONE), _LS(IDS_TM_DOMAIN_PLATE_BEAM_1D_TYPE), _LS(IDS_TM_DOMAIN_PLATE_COL_1D_TYPE), _LS(IDS_TM_Shell) };

		T_MADO_K MadoK = NULL;
		T_SBDO_K SbdoK = NULL;
		CString strTitle = _T("");
		CString strSbdoTitle = _T("");
		T_MADO_D MadoD; MadoD.Initialize();
		T_SBDO_D SbdoD; SbdoD.Initialize();
		for (int i = 0; i < nMadoCount; ++i)
		{
			MadoK = aMadoK[i];
			if (!pDoc->m_pAttrCtrl->GetMado(MadoK, MadoD)) continue;

			itr = mapMado2Count.find(MadoK);
			int nElemMadoKSize = 0;
			if (itr == mapMado2Count.end()) nElemMadoKSize = 0;
			else nElemMadoKSize = itr->second;

			strTitle.Format(_LS(IDS_TM_DOMAIN_s___Elem__d), MadoD.strName, nElemMadoKSize);
			hTI2 = InsertTreeItem(hTI, WORK_MADO_LST, strTitle, _T("ico24_nodeelement_mesh_definedomain"));

			int nSbdoSize = pDoc->m_pAttrCtrl->GetSbdoKeyList(MadoK, arSbdoKey, TRUE);
			for (int s = 0; s < nSbdoSize; ++s)
			{
				SbdoK = arSbdoKey[s];
				if (!pDoc->m_pAttrCtrl->GetSbdo(SbdoK, SbdoD)) continue;
				int nElemSbdoKSize = pDoc->m_pAttrCtrl->GetElemListSbdoK(SbdoK, arSbdoElemKey, aDoelK);

				if (SbdoD.nType < 1 && SbdoD.nType > 3) SbdoD.nType = 0;
#ifdef _CIVIL
				strSbdoTitle.Format(_LS(IDS_TM_DOMAIN_s___Elem__d__Type__S), SbdoD.strName, nElemSbdoKSize, aSbdoTypeCvl[SbdoD.nMembTypeCivil]);
#else
				strSbdoTitle.Format(_LS(IDS_TM_DOMAIN_s___Elem__d__Type__S), SbdoD.strName, nElemSbdoKSize, strSbdoType[SbdoD.nType]);
#endif // _CIVIL

				InsertTreeItem(hTI2, WORK_SBDO_LST, strSbdoTitle, _T("ico24_nodeelement_mesh_definedomain"));
			}
		}
	}

	if (bTestCode)
	{
		QueryPerformanceCounter(&calcEnd);

		LARGE_INTEGER freq;
		QueryPerformanceFrequency(&freq);

		CString strInitTime = _T(""), strMapTime = _T(""), StrCalcTime = _T("");
		strInitTime.Format(_T("   Initialize time:  %g (ms)"), ((double(initEnd.QuadPart) - double(initStart.QuadPart)) * 1000.0 / double(freq.QuadPart)));
		strMapTime.Format(_T("   Calc & map time:  %g (ms)"), ((double(mapEnd.QuadPart) - double(mapStart.QuadPart))  * 1000.0 / double(freq.QuadPart)));
		StrCalcTime.Format(_T("   Calc time:        %g (ms)"), ((double(calcEnd.QuadPart) - double(calcStart.QuadPart)) * 1000.0 / double(freq.QuadPart)));

		GSaveHistoryFormatNF(strInitTime);
		GSaveHistoryFormatNF(strMapTime);
		GSaveHistoryFormatNF(StrCalcTime);
	}

	if (hTI != NULL) ExpandCompletely(hTI, TRUE);
	return hTI;
}

#include <ppl.h>
#include <concurrent_unordered_map.h>
using namespace Concurrency;
HTREEITEM CTreeWorkCtrl::SetDomainDataItemTree_Test(CDBDoc* pDoc, BOOL bInit/*=TRUE*/)
{
	M_PROFILE('CTreeWorkCtrl::SetDomainDataItemTree_Test');

	LARGE_INTEGER initStart, initEnd, mapStart, mapEnd, calcStart, calcEnd;
	QueryPerformanceCounter(&initStart);

	HTREEITEM hTI = NULL;
	CString   tStr;
	std::vector<T_MADO_K> aMadoK;
	std::vector<T_SBDO_K> aSbdoK;

	pDoc->m_pAttrCtrl->GetMadoKeyList(aMadoK);
	pDoc->m_pAttrCtrl->GetSbdoKeyList(aSbdoK);

	int nMadoCount = (int)aMadoK.size();
	int nSbdoCount = (int)aSbdoK.size();

	int nTotalcount = nMadoCount;

	QueryPerformanceCounter(&mapStart);
	initEnd = mapStart;

	hTI = SetSub1TreeItem(WORK_DOMN_FLD, bInit, nTotalcount, 0);
	if (hTI == NULL) return NULL;

	std::map<T_MADO_K, int> mapMado2Count;
	typedef pair<T_MADO_K, int> pairMado;
	std::map<T_MADO_K, int>::iterator itr;
	T_DOEL_K DoelK = 0;
	T_DOEL_D DoelD;
	POSITION pos = pDoc->m_pAttrCtrl->GetStartDoel();
	while (pos)
	{
		pDoc->m_pAttrCtrl->GetNextDoel(pos, DoelK, DoelD);
		if (DoelD.nDomainType != 0) continue;

		itr = mapMado2Count.find(DoelD.KeyDomain);

		int nCount = 0;
		if (itr == mapMado2Count.end()) nCount++;
		else
		{
			nCount = itr->second;
			nCount++;
		}

		mapMado2Count.insert(pairMado(DoelD.KeyDomain, nCount));
	}

	QueryPerformanceCounter(&calcStart);
	mapEnd = calcStart;

	if (nMadoCount)
	{
		HTREEITEM hTI2 = NULL;

		std::vector<T_SBDO_K> arSbdoKey; arSbdoKey.clear();

		CArray<T_DOEL_K, T_DOEL_K> aDoelK;
		pDoc->m_pAttrCtrl->GetDoelKeyList(aDoelK);

		TCHAR strSbdoType[SBDO_TYPE_NUM][12] = { _T("None"), _T("Slab"), _T("Mat"), _T("Wall"), _T("Shell") };

		T_MADO_K MadoK = NULL;
		CString strTitle = _T("");
		T_MADO_D MadoD; MadoD.Initialize();

		for (int i = 0; i < nMadoCount; ++i)
		{
			MadoK = aMadoK[i];
			if (!pDoc->m_pAttrCtrl->GetMado(MadoK, MadoD)) continue;

			itr = mapMado2Count.find(MadoK);
			int nElemMadoKSize = 0;
			if (itr == mapMado2Count.end()) nElemMadoKSize = 0;
			else nElemMadoKSize = itr->second;

			strTitle.Format(_LS(IDS_TM_DOMAIN_s___Elem__d), MadoD.strName, nElemMadoKSize);
			hTI2 = InsertTreeItem(hTI, WORK_MADO_LST, strTitle, _T("ico24_Temp"));

			int nSbdoSize = pDoc->m_pAttrCtrl->GetSbdoKeyList(MadoK, arSbdoKey, TRUE);
			std::vector<CString> mapSbdoStr(nSbdoSize);

			parallel_for(0, nSbdoSize, [&](int s)
			{
				const T_SBDO_K& SbdoK = arSbdoKey[s];

				T_SBDO_D SbdoD; SbdoD.Initialize();
				if (pDoc->m_pAttrCtrl->GetSbdo(SbdoK, SbdoD))
				{
					std::vector<T_ELEM_K> arSbdoElemKey; arSbdoElemKey.clear();
					int nElemSbdoKSize = pDoc->m_pAttrCtrl->GetElemListSbdoK(SbdoK, arSbdoElemKey, aDoelK);

					if (SbdoD.nType < 1 && SbdoD.nType > 3) SbdoD.nType = 0;

					mapSbdoStr[s].Format(_LS(IDS_TM_DOMAIN_s___Elem__d__Type__S), SbdoD.strName, nElemSbdoKSize, strSbdoType[SbdoD.nType]);
				}
				else
				{
					ASSERT(0);
					mapSbdoStr[s].Empty();
				}
			});

			for (int s = 0; s < nSbdoSize; ++s)
			{
				const CString& strSbdoTitle = mapSbdoStr.at(s);
				if (strSbdoTitle.IsEmpty()) continue;
				InsertTreeItem(hTI2, WORK_SBDO_LST, strSbdoTitle, _T("ico24_Temp"));
			}
		}
	}

	QueryPerformanceCounter(&calcEnd);

	LARGE_INTEGER freq;
	QueryPerformanceFrequency(&freq);

	CString strInitTime = _T(""), strMapTime = _T(""), StrCalcTime = _T("");
	strInitTime.Format(_T("   Initialize time:  %g (ms)"), ((double(initEnd.QuadPart) - double(initStart.QuadPart)) * 1000.0 / double(freq.QuadPart)));
	strMapTime.Format(_T("   Calc & map time:  %g (ms)"), ((double(mapEnd.QuadPart) - double(mapStart.QuadPart))  * 1000.0 / double(freq.QuadPart)));
	StrCalcTime.Format(_T("   Calc time:        %g (ms)"), ((double(calcEnd.QuadPart) - double(calcStart.QuadPart)) * 1000.0 / double(freq.QuadPart)));

	GSaveHistoryFormatNF(strInitTime);
	GSaveHistoryFormatNF(strMapTime);
	GSaveHistoryFormatNF(StrCalcTime);

	if (hTI != NULL) ExpandCompletely(hTI, TRUE);
	return hTI;
}

