HTREEITEM CTreeWorkCtrl::SetColmCapitalDataItemTree(CDBDoc* pDoc, BOOL bInit/*=TRUE*/)
{
	InitializeTree init_tree(this);

	HTREEITEM hTI = NULL;
	CString   tStr;
	CArray<T_CCPT_K, T_CCPT_K> aCcptK;
	CArray<T_ELEM_K, T_ELEM_K> aElemK;
	int nCcptCnt = 0;

	pDoc->m_pAttrCtrl2->GetCcptKeyList(aCcptK);
	int nCcptCount = aCcptK.GetSize();

	hTI = SetSub1TreeItem(WORK_CCPT_FLD, bInit, nCcptCount, 0);
	if (hTI == NULL) return NULL;

	CString strData, strName;
	if (nCcptCount)
	{
		HTREEITEM hTI2 = NULL;

		T_CCPT_D CcptD;
		for (int i = 0; i < nCcptCount; ++i)
		{
			T_CCPT_K CcptK = aCcptK[i];
			CcptD.Initialize();
			if (!pDoc->m_pAttrCtrl2->GetCcpt(CcptK, CcptD)) continue;
			nCcptCnt = pDoc->m_pAttrCtrl2->GetElemKListByCcpt(CcptK, aElemK);
			CString strTitle;
			strTitle.Format(_T("%s [Element, %d]"), CcptD.strName, aElemK.GetSize());
			hTI2 = InsertTreeItem(hTI, WORK_CCPT_LST, strTitle, _T("ico24_seismicperform_evaluationtype_piereval"));
		}
	}

	if (hTI != NULL) ExpandCompletely(hTI, TRUE);
	return hTI;
}
