	GetSelectedItemKeyList(data, aNodeList, aElemList);

	I_GENModelBase* pIGM = I_GENModelBase::GetCurMySelfST();
	//  if (pIGM) pIGM->ManagementObject_ActOrInAct(aNodeList, aElemList, TRUE, 1);
