		VERIFY(pPopup != NULL);
		pPopup->DeleteMenu(11, MF_BYPOSITION);
		pPopup->DeleteMenu(ID_WORKTREE_TABLES, MF_BYCOMMAND);  // Table을 지움 
		TrackPopupMenu();
		break;
	case WORK_SPAN_LST:
	case WORK_SPAN_COMPOSTIE_LST:
	case WORK_SPAN_COMPOSTIE_VB_LST:
	case WORK_SPAN_STEELGIRDER_LST:
	case WORK_NPLN_LST:
	case WORK_HNGT_LST:
	case WORK_CRGR_LST:
	case WORK_CJFG_LST:
