		VERIFY(pPopup != NULL);
		pPopup->DeleteMenu(1, MF_BYPOSITION);
		pPopup->DeleteMenu(ID_WORKTREE_ASSIGN, MF_BYCOMMAND); // Assign을 지움
		TrackPopupMenu();
		break;
	case WORK_PROP_FLD:
