		pPopup->DeleteMenu(ID_WORKTREE_DELETE_UNUS_THIK, MF_BYCOMMAND);
		pPopup->DeleteMenu(ID_WORKTREE_TABLES, MF_BYCOMMAND);  // Table을 지움 
