		VERIFY(pPopup != NULL);
		TrackPopupMenu();
		break;
	case WORK_ROOT:
	case WORK_ANAL_FLD:
	case WORK_STRU_FLD:
	case WORK_NPLN_FLD:
	case WORK_BNDR_FLD:
	case WORK_MASS_FLD:
	case WORK_STLD_FLD:
