void CTreeWorkCtrl::OnWorktreeDeleteUnusMatl()
{
	CDBDoc* pDoc = CDBDoc::GetDocPoint();
	ASSERT(pDoc);

	CArray<T_MATL_K, T_MATL_K> arKeyList;
	pDoc->m_pAttrCtrl->GetMatlKeyList(arKeyList);
	int nSize = arKeyList.GetSize();

	CArray<T_MATL_K, T_MATL_K> arUnusedKeyList;
	for (int i = 0; i < nSize; i++)
	{
		if (!pDoc->m_pAttrCtrl->IsUsedMatl(arKeyList[i]))
			arUnusedKeyList.Add(arKeyList[i]);
	}
	pDoc->m_pDataCtrl->DelMatl(arUnusedKeyList);
}

