void CTreeWorkCtrl::OnWorktreeAssign()
{
	CArray<HTREEITEM, HTREEITEM> aItem;
	int selItemNum = GetSelectedItemList(aItem);
	if (selItemNum > 1)
	{
		AfxMessageBox(_LS(IDS_TMWK__MSG171));
		return;
	}

	// [2009-09-28] Kim, Geun Young (Tel: 2042, gykim@midasit.com)
	// Main Domain의 경우 자식 Item이 있어도 동작하게끔 하기 위함.
	UINT Data = GetItemData(aItem[0]);
	if (FALSE == ItemHasChildren(aItem[0]) || Data == WORK_MADO_LST)
	{
		// 선택된 Entity 정보 가져오기

		I_GENModelBase * pIGM = CTreeMenuBarBase::GetI_GENModelST();

		CArray<T_NODE_K, T_NODE_K> aNodeKeyList;
		CArray<T_ELEM_K, T_ELEM_K> aElemKeyList;
		pIGM->GetSelectedNodeKeyList(aNodeKeyList);
		pIGM->GetSelectedElemKeyList(aElemKeyList);
		if (aNodeKeyList.GetSize() == 0 && aElemKeyList.GetSize() == 0) return;

		AssignAttribute(aItem[0], aNodeKeyList, aElemKeyList);
	}
}

void CTreeWorkCtrl::OnWorktreeProperties()
{
	WPARAM wParam = 0;
	LPARAM lParam = MAKELPARAM(1, 1);
	SendMessage(WM_MOUSEMOVE, wParam, lParam);

	CArray<HTREEITEM, HTREEITEM> aItem;
	int selItemNum = GetSelectedItemList(aItem);
	if (selItemNum > 1)
	{
		AfxMessageBox(_LS(IDS_TMWK__MSG170));
		return;
	}

	EditProperty(aItem[0]);
}

