		int indx = 1;

		T_MENU_STATE MenuState;
		pDoc->GetMenuState(ID_STRUCT_BNDR_RIGIDLINK, MenuState);
		if (!MenuState.bIncludeEnable || (MenuState.bIncludeEnable && MenuState.bEnable)) // enable
		{
			while (posRd != NULL)
			{
				pDoc->m_pAttrCtrl->GetNextRigd(posRd, KeyRigd, DataRigd);
				if (indx == pos)
				{
					CBarTreeMenu* pTree = (CBarTreeMenu*)CTreeMenuBarBase::GetMySelfST();
					pTree->ShowDlgWithInit(__TMMODE_STRUCT_BNDR_RIGD__, KeyRigd.keymap);
					break;
				}
				indx += 1;
			}
		}
