void CTreeWorkCtrl::EditProperty_ResponseSpectrum(CDBDoc* pDoc, HTREEITEM ht, UINT data, int pos)
{
	if (data == WORK_SPFC_LST)
	{
		CSpfcItemDlg spfcDlg;
		T_SPFC_D    spfcData;
		CArray<T_SPFC_K, T_SPFC_K> aSpfcKeyList;
		pDoc->m_pAttrCtrl->GetSpfcKeyList(aSpfcKeyList);
		pDoc->m_pAttrCtrl->GetSpfc(aSpfcKeyList[pos - 1], spfcData);

		spfcDlg.SetParamData(spfcData);
		spfcDlg.DoModal();
	}
	else if (data == WORK_SPLC_LST)
	{
		T_MENU_STATE MenuState;
		pDoc->GetMenuState(ID_STRUCT_SPEC_DEFINE, MenuState);
		if (!MenuState.bIncludeEnable || (MenuState.bIncludeEnable && MenuState.bEnable)) // enable
		{
			CArray<T_SPLC_K, T_SPLC_K> aKeyList;
			pDoc->m_pAttrCtrl->GetSplcKeyList(aKeyList);

			CBarTreeMenu* pTree = (CBarTreeMenu*)CTreeMenuBarBase::GetMySelfST();
			pTree->ShowDlgWithInit(__TMMODE_CMD_SPEC__, aKeyList[pos - 1]);
		}
	}
	else if (data == WORK_SPFC_ND_LST)
	{
		HTREEITEM parentItem = GetParentItem(ht);
		UINT parentData = GetItemData(parentItem);
		int nParentPos = 0;
		for (HTREEITEM prvHt = parentItem; prvHt != NULL; parentItem = prvHt, nParentPos++) prvHt = GetPrevSiblingItemWithoutFilter(parentItem);

		CArray<T_SPFC_K, T_SPFC_K> aSpfcKeyList;
		pDoc->m_pAttrCtrl->GetSpfcKeyList(aSpfcKeyList);
		T_SPFC_K SpfcK = aSpfcKeyList[nParentPos - 1];

		CArray<double, double> aNonDissipative;
		if (GetNonDissipativeListBySpfc(pDoc, SpfcK, aNonDissipative) > 0)
		{
			if (aNonDissipative.GetSize() < pos) { ASSERT(0); return; }
			double dNonDissipative = aNonDissipative[pos - 1];

			T_SPFC_D SpfcD;
			if (!pDoc->m_pAttrCtrl->GetSpfc(SpfcK, SpfcD)) { ASSERT(0); return; }

			T_SPFC_D DataSpfcND(SpfcD);
			if (!pDoc->m_pAttrCtrl->GetSpectralData4NonDissipative(SpfcD, dNonDissipative, DataSpfcND)) return;

			DataSpfcND.SpecFuncName = SpfcD.SpecFuncName;

			CSpfcItemDlg spfcDlg;
			spfcDlg.SetParamData(DataSpfcND);
			spfcDlg.SetShowType(TRUE);
			spfcDlg.DoModal();
		}
	}
}

void CTreeWorkCtrl::EditProperty_Tendon(CDBDoc* pDoc, HTREEITEM ht, UINT data, int pos)
{
	if (data == WORK_TDNT_LST) // Tendon Property(Type)
	{
		CArray<T_TDNT_K, T_TDNT_K> aKeyList;
		pDoc->m_pAttrCtrl->GetTdntKeyList(aKeyList);
		T_TDNT_K    tdntKey = aKeyList[pos - 1];
		CMD_DoModal(D_CMD_TENDON_TYPE_ADD, &tdntKey);
	}
	else if (data == WORK_TDNA_LST)   // Tendon Profile
	{
		CArray<T_TDNA_K, T_TDNA_K> aTdnaKeyList;
		pDoc->m_pAttrCtrl->GetTdnaKeyList(aTdnaKeyList);

		void* TdnaKey = NULL;
		TdnaKey = (void *)(&aTdnaKeyList[pos - 1]);
		CreateOrActivateDlg(pDoc, CCMTendonProfileDlg::IDD, NULL, TdnaKey);
	}
	else if (data == WORK_TDBM_LST)   // Tendon Profile - Beam
	{
		CArray<T_TDBM_K, T_TDBM_K> aTdbmKeyList;
		pDoc->m_pAttrCtrl2->GetTdbmKeyList(aTdbmKeyList);

		T_TDBM_K    TdbmKey = aTdbmKeyList[pos - 1];
		CMD_DoModal1(D_CMD_PT_SET_TENDON_PROFILE_DLG, &TdbmKey);	
	}
	else if (data == WORK_PTTN_LST)   // Tendon Profile - Slab
	{
		CArray<T_PTTN_K, T_PTTN_K> aPttnKeyList;
		pDoc->m_pAttrCtrl2->GetPttnKeyList(aPttnKeyList);

		T_PTTN_K    PttnKey = aPttnKeyList[pos - 1];
		CMD_DoModal1(D_CMD_PT_SET_TENDON_PROFILE_MATCH_DLG, &PttnKey);
	}
	else if (data == WORK_TDCS_LST) // Tendon Location for Composite Section
	{
		CMD2_DoModal(D_CMD2_TENDON_COMPO_DLG);
	}
}

