void CTreeWorkCtrl::EditProperty_TimeHistoryLoad(CDBDoc* pDoc, HTREEITEM ht, UINT data, int pos)
{
	const double zero = pDoc->m_pInitCtrl->GetPreferenceRegardZero();

	if (data == WORK_THIS_LST)
	{
		CArray<T_THIS_K, T_THIS_K> aThisKeyList;
		pDoc->m_pAttrCtrl->GetThisKeyList(aThisKeyList, FALSE);

		if(aThisKeyList.GetSize() < pos) { ASSERT(false); return; }

#if defined (_MEC)
		CreateOrActivateDlg(pDoc, CThisItemDlg_MEC::IDD, this, &aThisKeyList[pos - 1]);
#else
		CreateOrActivateDlg(pDoc, CThisItemDlg::IDD, this, &aThisKeyList[pos - 1]);
#endif
	}
	else if (data == WORK_THFC_LST)
	{
		CThfcItemDlg thfcDlg;
		T_THFC_D    thfcData;
		CArray<T_THFC_K, T_THFC_K> aThfcKeyList;
		pDoc->m_pAttrCtrl->GetThfcKeyList(aThfcKeyList);
		pDoc->m_pAttrCtrl->GetThfc(aThfcKeyList[pos - 1], thfcData);
		thfcDlg.SetParamData(thfcData);
		thfcDlg.DoModal();
	}
	else if (data == WORK_THGA_LST)
	{
		T_MENU_STATE MenuState;
		pDoc->GetMenuState(ID_STRUCT_TIME_GROUND, MenuState);
		if (!MenuState.bIncludeEnable || (MenuState.bIncludeEnable && MenuState.bEnable)) // enable
		{
			T_THGA_K  thgaKey;
			T_THGA_D  thgaData;
			POSITION  thgaPos = pDoc->m_pAttrCtrl->GetStartThga();
			int indx = 1;

			while (thgaPos != NULL)
			{
				pDoc->m_pAttrCtrl->GetNextThga(thgaPos, thgaKey, thgaData);
				if (indx == pos)
				{
					CBarTreeMenu* pTree = (CBarTreeMenu*)CTreeMenuBarBase::GetMySelfST();
					pTree->ShowDlgWithInit(__TMMODE_CMD_THGA__, thgaKey);
					break;
				}
				indx += 1;
			}
		}
	}
	else if (data == WORK_THNL_LST)
	{
		T_MENU_STATE MenuState;
		pDoc->GetMenuState(ID_STRUCT_TIME_NODAL, MenuState);
		if (!MenuState.bIncludeEnable || (MenuState.bIncludeEnable && MenuState.bEnable)) // enable
		{
			SelectEntity(data, TRUE);

			POSITION  thnlPos;
			T_THNL_K  thnlKey;
			T_THNL_D  thnlData;

			thnlPos = pDoc->m_pAttrCtrl->GetStartThnl();
			while (thnlPos != NULL)
			{
				pDoc->m_pAttrCtrl->GetNextThnl(thnlPos, thnlKey, thnlData);
				if (thnlData.LoadCaseKey == m_aThnlInfo[pos - 1].LoadCaseKey && thnlData.nLoadType == m_aThnlInfo[pos - 1].nLoadType &&
					thnlData.nThisFuncKey == m_aThnlInfo[pos - 1].nThisFuncKey && thnlData.nDirection == m_aThnlInfo[pos - 1].nDirection &&
					fabs(thnlData.dArrivalTime - m_aThnlInfo[pos - 1].dArrivalTime) <= zero && fabs(thnlData.dFactor - m_aThnlInfo[pos - 1].dFactor) <= zero)
				{
					CBarTreeMenu* pTree = (CBarTreeMenu*)CTreeMenuBarBase::GetMySelfST();
					pTree->ShowDlgWithInit(__TMMODE_CMD_THNL__, thnlKey.keymap);
					break;
				}
			}
		}
	}
	else if (data == WORK_THSL_LST)    // Dynamic Spatial Load
	{
		T_MENU_STATE MenuState;
		pDoc->GetMenuState(ID_STRUCT_TIME_DYNSPA_LOAD, MenuState);
		if (!MenuState.bIncludeEnable || (MenuState.bIncludeEnable && MenuState.bEnable)) // enable
		{
			SelectEntity(data, TRUE);

			POSITION  thslPos;
			T_THSL_K  thslKey;
			T_THSL_D  thslData;

			thslPos = pDoc->m_pAttrCtrl->GetStartThsl();
			while (thslPos != NULL)
			{
				pDoc->m_pAttrCtrl->GetNextThsl(thslPos, thslKey, thslData);
				if (thslData.nThisKey == m_aThslInfo[pos - 1].nThisKey &&
					thslData.nStldKey == m_aThslInfo[pos - 1].nStldKey &&
					thslData.nThisFuncKey == m_aThslInfo[pos - 1].nThisFuncKey &&
					thslData.dArrivalTime == m_aThslInfo[pos - 1].dArrivalTime &&
					thslData.dFactor == m_aThslInfo[pos - 1].dFactor)
				{
					CBarTreeMenu* pTree = (CBarTreeMenu*)CTreeMenuBarBase::GetMySelfST();
					pTree->ShowDlgWithInit(__TMMODE_CMD_THSP__, thslKey);
					break;
				}
			}
		}
	}
	else if (data == WORK_THMS_LST)
	{
		T_MENU_STATE MenuState;
		pDoc->GetMenuState(ID_STRUCT_TIME_MULTI, MenuState);
		if (!MenuState.bIncludeEnable || (MenuState.bIncludeEnable && MenuState.bEnable)) // enable
		{
			T_THMS_K  ThmsK;
			T_THMS_D  ThmsD;
			POSITION  thmsPos = pDoc->m_pAttrCtrl->GetStartThms();

			while (thmsPos != NULL)
			{
				pDoc->m_pAttrCtrl->GetNextThms(thmsPos, ThmsK, ThmsD);

				if (ThmsD.ThisKey == m_aThmsInfo[pos - 1].ThisKey &&
					((ThmsD.nThisFuncKey[0] == m_aThmsInfo[pos - 1].nThisFuncKey[0] && fabs(ThmsD.dArrivalTime[0] - m_aThmsInfo[pos - 1].dArrivalTime[0]) <= zero && fabs(ThmsD.dFactor[0] - m_aThmsInfo[pos - 1].dFactor[0]) <= zero)) &&
					((ThmsD.nThisFuncKey[1] == m_aThmsInfo[pos - 1].nThisFuncKey[1] && fabs(ThmsD.dArrivalTime[1] - m_aThmsInfo[pos - 1].dArrivalTime[1]) <= zero && fabs(ThmsD.dFactor[1] - m_aThmsInfo[pos - 1].dFactor[1]) <= zero)) &&
					((ThmsD.nThisFuncKey[2] == m_aThmsInfo[pos - 1].nThisFuncKey[2] && fabs(ThmsD.dArrivalTime[2] - m_aThmsInfo[pos - 1].dArrivalTime[2]) <= zero && fabs(ThmsD.dFactor[2] - m_aThmsInfo[pos - 1].dFactor[2]) <= zero)) &&
					fabs(ThmsD.dAngleHGA - m_aThmsInfo[pos - 1].dAngleHGA) <= zero)
				{
					CBarTreeMenu* pTree = (CBarTreeMenu*)CTreeMenuBarBase::GetMySelfST();
					pTree->ShowDlgWithInit(__TMMODE_CMD_THMS__, ThmsK.keymap);
					break;
				}
			}
		}
	}
	else if (data == WORK_THRD_LST)
	{
		T_MENU_STATE MenuState;
		pDoc->GetMenuState(ID_STRUCT_LOAD_TIME_HISTORY_RESULT, MenuState);
		if (!MenuState.bIncludeEnable || (MenuState.bIncludeEnable && MenuState.bEnable)) // enable
		{
			CArray<T_THRD_K, T_THRD_K> aThrdKey;
			GetSelectedThrdKeyListWithMultiTreeItemSelect(aThrdKey);
			CBarTreeMenu* pTree = (CBarTreeMenu*)CTreeMenuBarBase::GetMySelfST();
			pTree->ShowDlgWithInit(__TMMODE_CMD_THRD__, aThrdKey[0]);
		}
	}
	else if (data == WORK_THCR_LST)
	{
		T_MENU_STATE MenuState;
		pDoc->GetMenuState(ID_STRUCT_LOAD_TIME_HISTORY_CONCUR_RESULT, MenuState);
		if (!MenuState.bIncludeEnable || (MenuState.bIncludeEnable && MenuState.bEnable)) // enable
		{
			CArray<T_THCR_K, T_THCR_K> aThcrKey;
			GetSelectedThcrKeyListWithMultiTreeItemSelect(aThcrKey);
			CBarTreeMenu* pTree = (CBarTreeMenu*)CTreeMenuBarBase::GetMySelfST();
			pTree->ShowDlgWithInit(__TMMODE_CMD_THCR__, aThcrKey[0]);
		}
	}
	else if (data == WORK_THAT_LST)
	{
		T_MENU_STATE MenuState;
		pDoc->GetMenuState(ID_STRUCT_LOAD_DEFINE_ANIMATION_TIME, MenuState);
		if (!MenuState.bIncludeEnable || (MenuState.bIncludeEnable && MenuState.bEnable)) // enable
		{
			CArray<T_THAT_K, T_THAT_K> aThatKey;
			GetSelectedThatKeyListWithMultiTreeItemSelect(aThatKey);
			CBarTreeMenu* pTree = (CBarTreeMenu*)CTreeMenuBarBase::GetMySelfST();
			pTree->ShowDlgWithInit(__TMMODE_CMD_THAT__, aThatKey[0]);
		}
	}
	else if (data == WORK_THRG_LST)
	{
		T_MENU_STATE MenuState;
		pDoc->GetMenuState(ID_RESULT_TIMEHISTORY_GRAPH_GLRES, MenuState);
		if (!MenuState.bIncludeEnable || (MenuState.bIncludeEnable && MenuState.bEnable)) // enable
		{
			CArray<T_THRG_K, T_THRG_K> aThrgKey;
			GetSelectedThrgKeyListWithMultiTreeItemSelect(aThrgKey);

			if (!aThrgKey.IsEmpty())
			{
				T_EXPFUNC_THISRES_CALL_D callData;
				callData.nType = 0;
				callData.key = aThrgKey[0];
				GPSCreateOrActivateDlg(pDoc, IDD_GPS_TH_RES_GRAPH_DLG, NULL, (void*)(&callData));
			}
		}
	}
	else if (data == WORK_THRI_LST)
	{
		T_MENU_STATE MenuState;
		pDoc->GetMenuState(ID_RESULT_TIMEHISTORY_GRAPH_GLRES, MenuState);
		if (!MenuState.bIncludeEnable || (MenuState.bIncludeEnable && MenuState.bEnable)) // enable
		{
			CArray<T_THRI_K, T_THRI_K> aThriKey;
			GetSelectedThriKeyListWithMultiTreeItemSelect(aThriKey);

			if (!aThriKey.IsEmpty())
			{
				T_EXPFUNC_THISRES_CALL_D callData;
				callData.nType = 1;
				callData.key = aThriKey[0];
				GPSCreateOrActivateDlg(pDoc, IDD_GPS_TH_RES_GRAPH_DLG, NULL, (void*)(&callData));
			}
		}
	}
	else if (data == WORK_THRS_LST)
	{
		T_MENU_STATE MenuState;
		pDoc->GetMenuState(ID_RESULT_TIMEHISTORY_GRAPH_GLRES, MenuState);
		if (!MenuState.bIncludeEnable || (MenuState.bIncludeEnable && MenuState.bEnable)) // enable
		{
			CArray<T_THRS_K, T_THRS_K> aThrsKey;
			GetSelectedThrsKeyListWithMultiTreeItemSelect(aThrsKey);

			if (!aThrsKey.IsEmpty())
			{
				T_EXPFUNC_THISRES_CALL_D callData;
				callData.nType = 2;
				callData.key = aThrsKey[0];
				GPSCreateOrActivateDlg(pDoc, IDD_GPS_TH_RES_GRAPH_DLG, NULL, (void*)(&callData));
			}
		}
	}
	else if (data == WORK_THEF_LST)
	{
		CArray<T_THEF_K, T_THEF_K> aThefKey;
		GetSelectedThefKeyListWithMultiTreeItemSelect(aThefKey);

		if (!aThefKey.IsEmpty())
		{
			T_EXPFUNC_THISRES_CALL_D callData;
			callData.nType = 3;
			callData.key = aThefKey[0];
			GPSCreateOrActivateDlg(pDoc, IDD_GPS_TH_RES_GRAPH_DLG, NULL, (void*)(&callData));
		}
	}
	else if (data == WORK_THSF_LST)
	{
		CArray<T_THSF_K, T_THSF_K> aThsfKey;
		GetSelectedThsfKeyListWithMultiTreeItemSelect(aThsfKey);

		if (!aThsfKey.IsEmpty())
		{
			T_EXPFUNC_THISRES_CALL_D callData;
			callData.nType = 8; //GPS_TH_SFR
			callData.key = aThsfKey[0];
			GPSCreateOrActivateDlg(pDoc, IDD_GPS_TH_RES_GRAPH_DLG, NULL, (void*)(&callData));
		}
	}
	else if (data == WORK_THGC_FLD)
	{
#if defined (_MEC)
		CCMThgcDlg_MEC dlg;
#else
		CCMThgcDlg dlg;
#endif
		dlg.DoModal();
	}
}

