void CTreeWorkCtrl::EditProperty_MovingLoad_Vehicle(CDBDoc* pDoc, HTREEITEM ht, UINT data, int pos)
{
	if (data == WORK_MVHL_LST)
	{
		T_MVHL_D    mvhlData;
		CArray<T_MVHL_K, T_MVHL_K> aMvhlKeyList;  // Vehicles
		pDoc->m_pAttrCtrl->GetMvhlKeyList(aMvhlKeyList);
		pDoc->m_pAttrCtrl->GetMvhl(aMvhlKeyList[pos - 1], mvhlData);

		T_MVCD_D MvcdD;
		if (!pDoc->m_pAttrCtrl->GetMvcd(MvcdD)) MvcdD.Initialize();
		if (mvhlData.bStandard)
		{
			switch (MvcdD.nCodeType)
			{
			case D_MOVE_CODE_EURO_BS:
				DoModalStdEuroBSnew(mvhlData);
				break;
			case D_MOVE_CODE_RUSSIA:
				DoModalStdRus(mvhlData);
				break;
			case D_MOVE_CODE_KOREA_LRFD_2011:
				DoModalStdKRLRFD11(mvhlData);
				break;
			case D_MOVE_CODE_AUSTRALIA:
				DoModalStdAustralia(mvhlData);
				break;
			case D_MOVE_CODE_POLAND:
				DoModalStdPoland(mvhlData);
				break;
			case D_MOVE_CODE_SOUTH_AFRICA:
				DoModalStdSouthAfrica(mvhlData);
				break;
			case D_MOVE_CODE_INDIA:
				DoModalStdIndia(mvhlData);
				break;
			case D_MOVE_CODE_BS:
				DoModalStdBS(mvhlData);
				break;
			case D_MOVE_CODE_FRANCE:
				DoModalStdFR(mvhlData);
				break;
			case D_MOVE_CODE_JAPAN_RAIL:
				DoModalStdJpRail(mvhlData);
				break;
			case D_MOVE_CODE_NEWZEALAND:
				DoModalStdNewZealand(mvhlData);
				break;
			case D_MOVE_CODE_BRAZIL:
				DoModalStdBrazil(mvhlData);
				break;
			default:
				DoModalStd(mvhlData);
				break;
			}
		}
		else
		{
			switch (MvcdD.nCodeType)
			{
			case D_MOVE_CODE_EURO_BS:
				DoModalUserEuroBSNew(mvhlData);
				break;
			case D_MOVE_CODE_RUSSIA:
				DoModalUsrRus(mvhlData);
				break;
			case D_MOVE_CODE_KOREA_LRFD_2011:
				DoModalUsrKRLRFD11(mvhlData);
				break;
			case D_MOVE_CODE_AUSTRALIA:
				DoModalUsrAustralia(mvhlData);
				break;
			case D_MOVE_CODE_POLAND:
				DoModalUsrPoland(mvhlData);
				break;
			case D_MOVE_CODE_SOUTH_AFRICA:
				DoModalUsrSouthAfrica(mvhlData);
				break;
			case D_MOVE_CODE_INDIA:
				DoModalUsrIndia(mvhlData);
				break;
			case D_MOVE_CODE_FRANCE:
				ASSERT(0);
				break;
			case D_MOVE_CODE_JAPAN_RAIL:
				DoModalUsrJpRail(mvhlData);
				break;
			case D_MOVE_CODE_NEWZEALAND:
				DoModalUsrNewZealand(mvhlData);
				break;
			case D_MOVE_CODE_BRAZIL:
				DoModalUsrBrazil(mvhlData);
				break;
			default:
				DoModalUsr(mvhlData);
				break;
			}
		}
	}
	else if (data == WORK_MVHC_LST)
	{
		CCMMvhcItemDlg mvhcDlg;
		T_MVHC_D    mvhcData;
		CArray<T_MVHC_K, T_MVHC_K> aMvhcKeyList;
		pDoc->m_pAttrCtrl->GetMvhcKeyList(aMvhcKeyList);
		pDoc->m_pAttrCtrl->GetMvhc(aMvhcKeyList[pos - 1], mvhcData);
		mvhcDlg.SetParamData(mvhcData);
		mvhcDlg.DoModal();
	}
}

