void CTreeWorkCtrl::OnBegindrag(NMHDR* pNMHDR, LRESULT* pResult)
{
	NM_TREEVIEW* pNMTreeView = (NM_TREEVIEW*)pNMHDR;

	CArray<HTREEITEM, HTREEITEM> aItem;
	int selItemNum = GetSelectedItemList(aItem);
	if (aItem.GetSize() == 0)  return;
	UINT Data = GetItemData(aItem[0]);
	if (selItemNum > 1) { Data = 0; } // 두 개 이상의 아이템이 선택되어 있으면 Assign 불가!!

	switch (Data)
	{
	case WORK_GRUP_LST:
	case WORK_MATL_LST:
	case WORK_SECT_LST:
	case WORK_CSCS_LST:
	case WORK_THIK_LST:
	case WORK_CONS_LST:
	case WORK_NSPR_LIN_LST:
	case WORK_NSPR_NON_LST:
	case WORK_NSPR_MLT_LST:
	case WORK_GSTP_LST:
	case WORK_SSPS_LIN_LST:
	case WORK_SSPS_NON_LST:
	case WORK_FRLS_LST:
	case WORK_OFFS_LST:
	case WORK_PRLS_LST:
	case WORK_RIGD_LST:
	case WORK_MCON_LST:  // MNET:2790-JHLEE-20070911  
	case WORK_DRLS_FLD:
	case WORK_SKEW_LST:
	case WORK_NMAS_LST:
	case WORK_GMAS_LST:
		//  	case WORK_MLSP_FLD:  
	case WORK_SINF_FLD:
	case WORK_SINFch_FLD:
	case WORK_THNL_LST:
	case WORK_SMPT_LST:
	case WORK_HECB_LST:
	case WORK_HSPT_LST:
	case WORK_HSFC_LST:
	case WORK_IEHP_LST:
	case WORK_ESSF_LST:
	case WORK_WSSF_LST:
	case WORK_PSSF_LST:
	case WORK_GIMP_LST:
	case WORK_JIMP_LST:
	case WORK_P1LA_LST:
	case WORK_GSTY_LST:
	case WORK_HNGT_LST:
	case WORK_REBB_LST:
	case WORK_REBC_LST:
	case WORK_REBR_LST:
		//    case WORK_REBW_LST:
	case WORK_RBMS_LST:
	case WORK_RBSL_LST:
	case WORK_RBMW_LST:
	case WORK_RBST_LST:
	case WORK_SBDO_LST:
	case WORK_MADO_LST:
	case WORK_PREB_LST:
	case WORK_PRCS_LST:
	case WORK_DPAN_LST:
	case WORK_CCPT_LST:
	case WORK_MSIS_LST:
	case WORK_RFST_LST:
		// 마우스 커서를 드래깅 모드로
		::SetClassLongPtr(this->m_hWnd, GCLP_HCURSOR, (LONG_PTR)AfxGetApp()->LoadCursor(IDC_CURSOR_ASSIGN));
		//::SetClassLongPtr(this->m_hWnd, GCLP_HCURSOR, (long)AfxGetApp()->LoadCursor(IDC_CURSOR_ASSIGN));
		::SetCursor(AfxGetApp()->LoadCursor(IDC_CURSOR_ASSIGN));
		m_bDragPoss = TRUE;
		break;
	default:
		// 마우스 커서를 드래깅 불가능 모드로
		::SetClassLongPtr(this->m_hWnd, GCLP_HCURSOR, (LONG_PTR)AfxGetApp()->LoadCursor(IDC_CURSOR_NOASSIGN));
		::SetCursor(AfxGetApp()->LoadCursor(IDC_CURSOR_NOASSIGN));
		m_bDragPoss = FALSE;
		break;
	}
	m_bDrag = TRUE;
	m_hDragItem = GetSelectedItem();

	CWnd* pWnd = GetCapture();
	if (pWnd == NULL)
	{
		BOOL bCheck = ReleaseCapture();
		if (bCheck == FALSE)
		{
			AfxMessageBox(_T("Error"));
		}
		else
		{
			SetCapture();
		}
	}
	else
		SetCapture();

	*pResult = 0;
}

void CTreeWorkCtrl::OnCaptureChanged(CWnd* pWnd)
{
	if (m_bDrag && pWnd == 0)
		::SetCapture(this->GetSafeHwnd());
}

LRESULT CTreeWorkCtrl::OnNcHitTest(CPoint point)
{
	BOOL bRet = MBaseTreeCtrl::OnNcHitTest(point);
	return bRet;
}

void CTreeWorkCtrl::OnLButtonUp(UINT nFlags, CPoint point)
{
	if (m_bDrag) // 드래깅 모드이면 
	{
		SetClassLongPtr(this->m_hWnd, GCLP_HCURSOR, (LONG_PTR)LoadCursor(NULL, IDC_ARROW));
		::SetCursor(LoadCursor(NULL, IDC_ARROW));
		m_bDrag = FALSE;
		ReleaseCapture();
		if (m_bDragPoss == TRUE) EndDrag(point);
		m_bDragPoss = FALSE;
	}
	MBaseTreeCtrl::OnLButtonUp(nFlags, point);
}


void CTreeWorkCtrl::EndDrag(CPoint point)
{
	ClientToScreen(&point);
	CWnd* pWnd = CWnd::WindowFromPoint(point);
	CString temp;
	pWnd->GetWindowText(temp);	if (pWnd == NULL) return;
	if (!pWnd->IsKindOf(RUNTIME_CLASS(CViewBase))) return;

	I_GENModelBase * pGENModelbase = ((CViewBase *)pWnd)->GetIGM();
	if (pGENModelbase == NULL) return;

	CArray<T_NODE_K, T_NODE_K> aNodeList;
	CArray<T_ELEM_K, T_ELEM_K> aElemList;
	pGENModelbase->GetSelectedNodeKeyList(aNodeList);
	pGENModelbase->GetSelectedElemKeyList(aElemList);
	if (aNodeList.GetSize() + aElemList.GetSize() == 0) return;
	AssignAttribute(m_hDragItem, aNodeList, aElemList);
}


