void CTreeWorkCtrl::OnWorktreeDisplay() 
{
	CArray<HTREEITEM, HTREEITEM> aItem;
	int selItemNum = GetSelectedItemList(aItem);
	if(selItemNum==0) return;
	
	// Display 함수 호출하기 전에 중복 제거를 수행한다. 
	// aItem : leaf Item , 가장 최근것 하나만 처리하고 있으므로 
	// 가장 최근것 결과만 저장 
	UINT CurData = 0;
	UINT CurParentData = 0;
	HTREEITEM Cur_aItem = 0;
	HTREEITEM Cur_parentItem = 0;
	
	for (int i = 0; i < selItemNum; i++)
	{
		Cur_aItem = aItem[i];
		CurData = GetItemData(aItem[i]);
		Cur_parentItem = GetParentItem(aItem[i]);
		CurParentData = GetItemData(Cur_parentItem);
		if(CurParentData == WORK_IEHG_FLD){	}
		else if (CurParentData >= WORK_BNDR_FLD && CurParentData <= WORK_SKEW_LST || CurParentData == WORK_NLNK_FLD || CurParentData == WORK_MCON_FLD || CurParentData == WORK_SSPS_FLD)
		{
		}
		else if (CurParentData == WORK_SSPS_LIN_FLD || CurParentData == WORK_SSPS_NON_FLD){	}
		else if (CurParentData == WORK_STLD_FLD){}
		else if (CurParentData == WORK_STLD_LST){}
		else if (CurParentData == WORK_CNLD_TYPE_LST){}
		else if (CurParentData == WORK_ETCLD_FLD){}
		else if (CurParentData == WORK_RPSC_FLD){}
		else if (CurParentData == WORK_FIPA_FLD){}
		else if (CurParentData == WORK_FIRE_FLD)//FSSF
		{
		}
		else if (CurParentData == WORK_NMAS_FLD || CurParentData == WORK_LTOM_FLD || CurParentData == WORK_MASS_FLD)
		{
		}
		else if (CurParentData == WORK_THNL_FLD || CurParentData == WORK_THMS_FLD){}
		else if (CurParentData == WORK_LLANop_FLD || CurParentData == WORK_SLANop_FLD || 
			     CurData == WORK_LLANop_FLD || CurData == WORK_SLANop_FLD)
		{
		}
		else if (CurParentData == WORK_LLAN_FLD || CurParentData == WORK_SLAN_FLD || CurParentData == WORK_MVLDANL_FLD)
		{
		}
		else if (CurParentData == WORK_LLANjp_FLD || CurParentData == WORK_MVLDANLjp_FLD){}
		else if (CurParentData == WORK_LLANch_FLD || CurParentData == WORK_SLANch_FLD || CurParentData == WORK_MVLDANLch_FLD)
		{
		}
		else if (CurParentData == WORK_LLANid_FLD || CurParentData == WORK_MVLDANLid_FLD) {}
		else if (CurParentData == WORK_LLANfr_FLD || CurParentData == WORK_SLANfr_FLD || CurParentData == WORK_MVLDANLfr_FLD) {}
		else if (CurParentData == WORK_LLANtr_FLD || CurParentData == WORK_MVLDANLtr_FLD){}
		else if (CurParentData == WORK_SMPT_FLD){}
		else if (CurParentData == WORK_HECB_FLD || CurParentData == WORK_HSFC_FLD ||
			CurParentData == WORK_HSPT_FLD || CurParentData == WORK_HPCE_FLD)
		{
		}
		else if (CurParentData == WORK_PSTD_FLD || CurParentData == WORK_TDNA_FLD || 
				 CurParentData == WORK_TDBM_FLD || CurParentData == WORK_PTTN_FLD){ }
		else if (CurParentData >= WORK_GRID_FLD && CurParentData <= WORK_GACD_LST){ }
		else if (CurParentData >= WORK_PUSH_FLD && CurParentData <= WORK_PUSH_FLD_END){ }
		else if (CurParentData == WORK_BCCT_FLD) // MNET1199, KJH20050217
		{
		}
		else if (CurParentData == WORK_CRAN_LST || CurParentData == WORK_CRAN_FLD) // MNET:2682 20070515 mylee
		{
		}
		else if (CurParentData == WORK_DIMM_FLD){}
		else if (CurData == WORK_STOR_FLD){	}
		else if (CurParentData == WORK_PRCS_FLD){}
		else if (CurParentData == WORK_DPAN_FLD){}
		else if (CurParentData == WORK_CCPT_FLD){}
		else if (CurParentData == WORK_MSIS_FLD){}
		else if (CurParentData == ID_MAIN_RIBBON_SEISEVAL_PSEUDO_FORCE){}
	}

	{
		UINT Data = CurData;
		HTREEITEM parentItem = Cur_parentItem;
		UINT parentData = CurParentData;

		if (parentData == WORK_IEHG_FLD)
			DisplayBoundaries(Cur_aItem);
		else if (parentData >= WORK_BNDR_FLD && parentData <= WORK_SKEW_LST || parentData == WORK_NLNK_FLD || parentData == WORK_MCON_FLD || parentData == WORK_SSPS_FLD) 
			DisplayBoundaries(Cur_aItem);
		else if (parentData ==  WORK_SSPS_LIN_FLD || parentData == WORK_SSPS_NON_FLD)
			DisplayBoundaries(Cur_aItem);
		else if (parentData == WORK_STLD_FLD) 
			DisplayStaticLoad(Cur_aItem, 0);
		else if (parentData == WORK_STLD_LST) 
			DisplayStaticLoad(Cur_aItem);
		else if (parentData == WORK_CNLD_TYPE_LST) 
			DisplayCnldType(Cur_aItem);
		else if (parentData == WORK_ETCLD_FLD)
			DisplayEtcLoad(Cur_aItem);
		else if (parentData == WORK_RPSC_FLD)
			DisplayStaticLoad(Cur_aItem);
		else if (parentData == WORK_FIPA_FLD)
			DisplayFireLoad(Cur_aItem);
		else if (parentData == WORK_FIRE_FLD)//FSSF
			DisplayFireLoad(Cur_aItem);
		else if (parentData == WORK_NMAS_FLD || parentData == WORK_LTOM_FLD || parentData == WORK_MASS_FLD) 
			DisplayMasses(Cur_aItem);
		else if (parentData == WORK_THNL_FLD || parentData == WORK_THMS_FLD) 
			DisplayDynamicLoad(Cur_aItem);
		else if (parentData == WORK_LLANop_FLD || parentData == WORK_SLANop_FLD || Data == WORK_LLANop_FLD || Data == WORK_SLANop_FLD)  
			DisplayMovingLoadOp(Cur_aItem);
		else if (parentData == WORK_LLAN_FLD || parentData == WORK_SLAN_FLD || parentData == WORK_MVLDANL_FLD) 
			DisplayMovingLoad(Cur_aItem);
		else if (parentData == WORK_LLANjp_FLD || parentData == WORK_MVLDANLjp_FLD)                            
			DisplayMovingLoadjp(Cur_aItem);
		else if (parentData == WORK_LLANch_FLD || parentData == WORK_SLANch_FLD || parentData == WORK_MVLDANLch_FLD) 
			DisplayMovingLoadch(Cur_aItem);
		else if (parentData == WORK_LLANid_FLD || parentData == WORK_MVLDANLid_FLD) 
			DisplayMovingLoadid(Cur_aItem);
		else if (parentData == WORK_LLANfr_FLD || parentData == WORK_SLANfr_FLD || parentData == WORK_MVLDANLfr_FLD)
			DisplayMovingLoadfr(Cur_aItem);
		else if (parentData == WORK_LLANtr_FLD || parentData == WORK_MVLDANLtr_FLD) 
			DisplayMovingLoadtr(Cur_aItem);    
		else if (parentData == WORK_SMPT_FLD)                                                                  
			DisplaySettlement(Cur_aItem);
		else if (parentData == WORK_HECB_FLD || parentData == WORK_HSFC_FLD || 
				 parentData == WORK_HSPT_FLD || parentData == WORK_HPCE_FLD)                                   
			DisplayHydration(Cur_aItem);
		else if (parentData == WORK_PSTD_FLD || parentData == WORK_TDNA_FLD)                                                                  
			DisplayTendonProfile(Cur_aItem);
		else if (parentData == WORK_TDBM_FLD)
			DisplayPTBTendonProfile(Cur_aItem);
		else if (parentData == WORK_PTTN_FLD)
			DisplayPTSTendonProfile(Cur_aItem);
		else if (parentData >= WORK_GRID_FLD && parentData <= WORK_GACD_LST)
			DisplayGridAnalModel(Cur_aItem);
		else if (parentData >= WORK_PUSH_FLD && parentData <= WORK_PUSH_FLD_END)
			DisplayPushover(Cur_aItem);
		else if (parentData == WORK_BCCT_FLD) // MNET1199, KJH20050217
			DisplayBoundaries(Cur_aItem);
		else if (parentData == WORK_CRAN_LST || parentData == WORK_CRAN_FLD) // MNET:2682 20070515 mylee
			DisplayBoundaries(Cur_aItem);
		else if (parentData == WORK_DIMM_FLD)
			DisplayDimension(Cur_aItem);   
		else if (Data == WORK_STOR_LST)
			DisplayStoryTracingAndLineGrid(Cur_aItem);
		else if (Data == WORK_STOR_FLD)
			DisplayStor(Cur_aItem);    
		else if (parentData == WORK_PRCS_FLD)
			DisplayPrcs(Cur_aItem);    
		else if (parentData == WORK_DPAN_FLD)
			DisplayDpan(Cur_aItem);    
		else if (parentData == WORK_CCPT_FLD)
			DisplayCcpt(Cur_aItem);
		else if (parentData == WORK_MSIS_FLD)
			DisplayMsis(Cur_aItem);
		else if (parentData == ID_MAIN_RIBBON_SEISEVAL_PSEUDO_FORCE)
			DIsplayPsll(Cur_aItem);
	}
}
