void CTreeWorkCtrl::DisplayMovingLoadjp(HTREEITEM ht)
{
	I_GENModelBase::UTIL_DeleteAllDisplayObjST();
	CDBDoc* pDoc = CDBDoc::GetDocPoint();
	// *^^*
	// Nothing
	UINT data = GetItemData(ht);
	// Display Option Setting
	GDisplaySetting dspOpt;
	//GDisplaySetting *dspOpt = ExportDisplaySetting::GET();
	ExportDisplaySetting::GET(&dspOpt);
	dspOpt.m_Bndr.bLineLane = FALSE;
	dspOpt.m_Bndr.bSurfaceLane = FALSE;
	dspOpt.m_Bndr.bInfluenceSurf = FALSE;
	dspOpt.m_Bndr.bLaneSupport = FALSE;

	if (data == WORK_LLANjp_FLD)
		dspOpt.m_Bndr.bLineLane = TRUE;
	else if (data == WORK_LLANjp_LST)
	{
		T_LLANjp_K LlanK;
		CArray<CString, CString&> aName;
		int nNum = GetSelectedLlanjpKeyListWithMultiTreeItemSelect(aName);
		for (int i = 0; i < nNum; i++)
		{
			LlanK = pDoc->m_pAttrCtrl->GetLlanjpKey(aName[i]);
			I_GENModelBase::GetCurMySelfST()->UTIL_SetDisplayObj(UR_LLANjp_ADD, &LlanK);
		}
		I_GENModelBase::GetCurMySelfST()->GetOwnerWnd()->Invalidate(FALSE);
	}

	ExportDisplaySetting::SET(&dspOpt);
}

