void CTreeWorkCtrl::DisplayGridAnalModel(HTREEITEM ht)
{
	UINT data = GetItemData(ht);
	// Display Option Setting
	GDisplaySetting dspOpt;

	ExportDisplaySetting::GET(&dspOpt);
	dspOpt.m_Load.bMGDR = FALSE;
	dspOpt.m_Load.bCBEM = FALSE;
	dspOpt.m_Load.bLDLN = FALSE;
	dspOpt.m_Load.bBSPN = FALSE;
	dspOpt.m_Load.bGIMP = FALSE;
	dspOpt.m_Load.bGSTY = FALSE;
	dspOpt.m_Load.bGILD = FALSE;
	dspOpt.m_Load.bP1LA = FALSE;
	dspOpt.m_Load.bLNKF_ELNK = FALSE;
	dspOpt.m_Load.bLNKF_NLNK = FALSE;
	dspOpt.m_Load.bGMAS = FALSE;

	switch (data)
	{
	case WORK_MGDR_LST: dspOpt.m_Load.bMGDR = TRUE; break;
	case WORK_CBEM_LST: dspOpt.m_Load.bCBEM = TRUE; break;
	case WORK_LDLN_LST: dspOpt.m_Load.bLDLN = TRUE; break;
	case WORK_GILC_LST: // loadcase 별 display
	{
		HTREEITEM prvHt, curHt = ht;
		int pos = 0;
		for (prvHt = curHt; prvHt != NULL; curHt = prvHt, pos++) prvHt = GetPrevSiblingItemWithoutFilter(curHt);
		CDBDoc* pDoc = (CDBDoc*)CTreeMenuBarBase::GetDocST();
		CArray<T_GILC_K, T_GILC_K> aGilcK;
		pDoc->m_pAttrCtrl->GetGilcKeyList(aGilcK);

		dspOpt.m_Load.SetDefault();
		dspOpt.m_Load.nOption = 1;
		dspOpt.m_Load.bAllGroup = TRUE;
		dspOpt.m_Load.nLoadCaseType = D_LOADCASE_GRIDMODEL;
		dspOpt.m_Load.nLoadCase = aGilcK[pos - 1];
		dspOpt.m_Load.nLoadCaseIndex = pos;
		dspOpt.m_Load.bTxtAll = TRUE;
		dspOpt.m_Load.bGILD = TRUE;

		// 후처리 레이블
		I_GENModelBase * pIGM = I_GENModelBase::GetCurMySelfST();
		pIGM->SetLoadCaseInfoToPostDisplay(D_LOADCASE_GRIDMODEL, aGilcK[pos - 1]);
	}
	break;
	case WORK_BSPN_LST: dspOpt.m_Load.bBSPN = TRUE; break;
	case WORK_GIMP_LST: dspOpt.m_Load.bGIMP = TRUE; break;
	case WORK_GSTY_LST: dspOpt.m_Load.bGSTY = TRUE; break;
	case WORK_P1LA_LST: dspOpt.m_Load.bP1LA = TRUE; break;
	case WORK_LNKF_LST:
	{
		dspOpt.m_Load.bLNKF_ELNK = TRUE;
		dspOpt.m_Load.bLNKF_NLNK = TRUE;
	}
	break;
	case WORK_GMAS_LST: dspOpt.m_Load.bGMAS = TRUE; break;
	}

	ExportDisplaySetting::SET(&dspOpt);
}

