void CTreeWorkCtrl::DisplayBoundaries(HTREEITEM ht)
{
	UINT data = GetItemData(ht);
	GDisplaySetting dspOpt;
	ExportDisplaySetting::GET(&dspOpt);

	dspOpt.m_Bndr.SetDefault();
	dspOpt.m_Node.bSkew = FALSE;

	if (data == WORK_CONS_LST) dspOpt.m_Bndr.bCons = TRUE;
	else if (data == WORK_NSPR_LIN_LST) dspOpt.m_Bndr.bNspr = TRUE;
	else if (data == WORK_NSPR_NON_LST) dspOpt.m_Bndr.bNsprNon = TRUE;
	else if (data == WORK_NSPR_MLT_LST) dspOpt.m_Bndr.bNsprMulti = TRUE;
	else if (data == WORK_GSTP_LST) dspOpt.m_Bndr.bGspr = TRUE;
	else if (data == WORK_SSPS_LIN_LST) dspOpt.m_Bndr.bSspsLin = TRUE;
	else if (data == WORK_SSPS_NON_LST) dspOpt.m_Bndr.bSspsNon = TRUE;
	else if (data == WORK_DRLS_FLD) dspOpt.m_Bndr.bDiaDiscon = TRUE;
	else if (data == WORK_FRLS_LST) { dspOpt.m_Bndr.bFrls = TRUE; dspOpt.m_Bndr.bFrlsSym = TRUE; }
	else if (data == WORK_OFFS_LST) dspOpt.m_Bndr.bOffs = TRUE;
	else if (data == WORK_PRLS_LST) dspOpt.m_Bndr.bPlateEndR = TRUE;
	else if (data == WORK_RIGD_LST) dspOpt.m_Bndr.bRigd = TRUE;
	else if (data == WORK_MCON_LST) dspOpt.m_Bndr.bMcon = TRUE;   // MNET:2790-JHLEE-20070911
	else if (data == WORK_ELNK_FLD) { dspOpt.m_Bndr.bElasticLink = TRUE; dspOpt.m_Bndr.bElasticLinkAxis = TRUE; }
	else if (data == WORK_SKEW_LST) dspOpt.m_Node.bSkew = TRUE;
	else if (data == WORK_NLNK_LST)
	{
		dspOpt.m_Bndr.bNonlinearLink = TRUE;
		dspOpt.m_Bndr.bNonlinearLinkNo = TRUE;
	}
	else if (data == WORK_IEHG_LST) { dspOpt.m_Bndr.bInelasticHingeSymbol = TRUE; dspOpt.m_Bndr.bInelasticHingeName = TRUE; }
	else if (data == WORK_BCCT_LST) // MNET1199, KJH20050217
	{
		CArray<T_BNGR_K, T_BNGR_K> aBngrK;
		CString strSel(_T(""));
		GetSelectedBcctBngrKeyListWithMultiTreeItemSelect(aBngrK, strSel);

		dspOpt.m_Bndr.bAllGroup = FALSE;
		dspOpt.m_Bndr.m_GroupKeys.Copy(aBngrK);
		if (strSel[0] == '1') dspOpt.m_Bndr.bCons = TRUE; // Support
		if (strSel[1] == '1')
		{

			CDBDoc* pDoc = (CDBDoc*)CTreeMenuBarBase::GetDocST();

			CArray<T_NSPR_K, T_NSPR_K> aNsprKeyList;        // Point spring supports
			CArray<T_NSPR_K, T_NSPR_K> aNsprLinearKeyList;  // Point spring supports(Linear)
			CArray<T_NSPR_K, T_NSPR_K> aNsprCompTensKeyList;// Point spring supports(Comp/Tens)
			CArray<T_NSPR_K, T_NSPR_K> aNsprMultiKeyList;   // Point spring supports(Multi-Linear)

			pDoc->m_pAttrCtrl->GetNsprKeyList(aNsprKeyList);

			aNsprCompTensKeyList.RemoveAll();
			aNsprMultiKeyList.RemoveAll();
			for (int i = 0; i < aNsprKeyList.GetSize(); i++)
			{
				T_NSPR_D NsprData;
				if (!pDoc->m_pAttrCtrl->GetNspr(aNsprKeyList[i], NsprData)) ASSERT(0);

				BOOL bCheck = FALSE;
				for (int j = 0; j < aBngrK.GetSize(); j++)
				{
					if (NsprData.GroupKey == aBngrK[j])
					{
						bCheck = TRUE;
						break;
					}
				}

				if (!bCheck) continue;

				if (NsprData.nGenCompTen == 0) aNsprLinearKeyList.Add(aNsprKeyList[i]);
				else if (NsprData.nGenCompTen == 3) aNsprMultiKeyList.Add(aNsprKeyList[i]);
				else                                aNsprCompTensKeyList.Add(aNsprKeyList[i]);
			}

			if (aNsprLinearKeyList.GetSize() > 0)   dspOpt.m_Bndr.bNspr = TRUE;
			if (aNsprCompTensKeyList.GetSize() > 0) dspOpt.m_Bndr.bNsprNon = TRUE;
			if (aNsprMultiKeyList.GetSize() > 0)    dspOpt.m_Bndr.bNsprMulti = TRUE;

		}
		if (strSel[2] == '1') dspOpt.m_Bndr.bGspr = TRUE; // General Spring
		if (strSel[3] == '1') // Change General Link Property, MNET1199, KJH20050310, 신규추가
		{
			dspOpt.m_Bndr.bCGLP = TRUE;
		}
		if (strSel[6] == '1') //Beam End Release // MNET:XXXX-JUAE-20070727
		{
			dspOpt.m_Bndr.bFrls = TRUE;
		}

		// END KJH20050310
	}
	else if (data == WORK_CRAN_LST || data == WORK_CRAN_FLD)
	{
		dspOpt.m_Bndr.bCraneLane = TRUE;
		dspOpt.m_Bndr.bCraneName = TRUE;
	}

	ExportDisplaySetting::SET(&dspOpt);
}


void CTreeWorkCtrl::DisplayDynamicLoad(HTREEITEM ht)
{
	UINT data = GetItemData(ht);

	HTREEITEM prvHt, curHt = ht;
	int pos = 0;
	BOOL bSuccess = FALSE;
	for (prvHt = curHt; prvHt != NULL; curHt = prvHt, pos++) prvHt = GetPrevSiblingItemWithoutFilter(curHt);

	GDisplaySetting dspOpt;
	ExportDisplaySetting::GET(&dspOpt);

	dspOpt.m_Load.SetDefault();
	dspOpt.m_Load.nOption = 1;
	dspOpt.m_Load.bAllGroup = TRUE;
	dspOpt.m_Load.nLoadCaseType = D_LOADCASE_HISTORY;
	dspOpt.m_Load.nLoadCaseIndex = pos;
	dspOpt.m_Load.bTxtAll = TRUE;

	// 후처리 레이블
	I_GENModelBase * pIGM = I_GENModelBase::GetCurMySelfST();

	if (data == WORK_THNL_LST)
	{
		dspOpt.m_Load.nLoadCase = m_aThnlInfo[pos - 1].LoadCaseKey;
		dspOpt.m_Load.bDynNodalLoad = TRUE;
		pIGM->SetLoadCaseInfoToPostDisplay(D_LOADCASE_HISTORY, m_aThnlInfo[pos - 1].LoadCaseKey);
	}
	else if (data == WORK_THMS_LST)
	{
		dspOpt.m_Load.nLoadCase = m_aThmsInfo[pos - 1].ThisKey;
		dspOpt.m_Load.bTHMS = TRUE;
		pIGM->SetLoadCaseInfoToPostDisplay(D_LOADCASE_HISTORY, m_aThmsInfo[pos - 1].ThisKey);
	}

	ExportDisplaySetting::SET(&dspOpt);
}

void CTreeWorkCtrl::DisplayStaticLoad(HTREEITEM ht, BOOL fg)
{
	CDBDoc* pDoc = (CDBDoc*)CTreeMenuBarBase::GetDocST();
	if (!pDoc)
	{
		TRACE(_LS(IDS_TMWK__MSG1));
		return;
	}

	I_GENModelBase * pIGM = I_GENModelBase::GetCurMySelfST();

	if (fg) // 아이템이 하중 종류인 경우
	{
		// 선택한 아이템을 포함하는 하중 조건 찾기
		UINT data = GetItemData(ht);
		if (data == WORK_RPSC_LST) // 특별처리-이게 왜 여기 있을까?
		{
			GDisplaySetting dspOpt;
			ExportDisplaySetting::GET(&dspOpt);
			dspOpt.m_Load.SetDefault();
			dspOpt.m_Load.bRPSC = TRUE;
			ExportDisplaySetting::SET(&dspOpt);
			return;
		}

		HTREEITEM parentItem = GetParentItem(ht);
		HTREEITEM prvHt;
		int pos = 0;
		BOOL bSuccess = FALSE;
		for (prvHt = parentItem; prvHt != NULL; parentItem = prvHt, pos++) prvHt = GetPrevSiblingItemWithoutFilter(parentItem);
		CArray<T_STLD_K, T_STLD_K> aStldKeyList;
		pDoc->m_pAttrCtrl->GetStldKeyList(aStldKeyList);

		// Display Option Setting
		//GDisplaySetting *dspOpt = ExportDisplaySetting::GET();
		GDisplaySetting dspOpt;
		ExportDisplaySetting::GET(&dspOpt);

		dspOpt.m_Load.SetDefault();
		dspOpt.m_Load.nOption = 1;
		dspOpt.m_Load.bAllGroup = TRUE;
		dspOpt.m_Load.nLoadCaseType = D_LOADCASE_STATIC;
		dspOpt.m_Load.nLoadCase = aStldKeyList[pos - 1];
		dspOpt.m_Load.nLoadCaseIndex = pos;
		dspOpt.m_Load.bTxtAll = TRUE;

		// 후처리 레이블

		pIGM->SetLoadCaseInfoToPostDisplay(D_LOADCASE_STATIC, aStldKeyList[pos - 1]);

		if (data == WORK_CNLD_FLD)  dspOpt.m_Load.bCnld = TRUE;
		else if (data == WORK_SDSP_FLD) dspOpt.m_Load.bDisplacement = TRUE;
		else if (data == WORK_BMLD_ELEM_FLD || data == WORK_BMLD_LINE_FLD || data == WORK_BMLD_TYPC_FLD || data == WORK_BMLD_FLOR_FLD) dspOpt.m_Load.bBmld = TRUE;
		else if (data == WORK_PRST_FLD) dspOpt.m_Load.bPrestress = TRUE;
		else if (data == WORK_PTNS_FLD) dspOpt.m_Load.bPretention = TRUE;
		else if (data == WORK_FBLA_FLD) dspOpt.m_Load.bFbld = TRUE;
		else if (data == WORK_PNLA_FLD) dspOpt.m_Load.bPlaneLoad = TRUE;
		else if (data == WORK_PRES_FLD) dspOpt.m_Load.bPres = TRUE;
		else if (data == WORK_ARPR_FLD) dspOpt.m_Load.bArpr = TRUE;
		else if (data == WORK_NTMP_FLD) dspOpt.m_Load.bNodalTemp = TRUE;
		else if (data == WORK_ETMP_FLD) dspOpt.m_Load.bElemTemp = TRUE;
		else if (data == WORK_GTMP_FLD) dspOpt.m_Load.bTempGradiant = TRUE;
		else if (data == WORK_WIND_FLD) dspOpt.m_Load.bWind = TRUE;
		else if (data == WORK_WIND_WA_WT_FLD) dspOpt.m_Load.bWind = TRUE;
		else if (data == WORK_SEIS_FLD) dspOpt.m_Load.bSeismic = TRUE;
		else if (data == WORK_SSEI_FLD) dspOpt.m_Load.bSSEI = TRUE;
		else if (data == WORK_TDPL_FLD) dspOpt.m_Load.bTendonPrestress = TRUE;
		else if (data == WORK_FMLD_FLD) dspOpt.m_Load.bFMLD = TRUE;
		else if (data == WORK_BTMP_FLD) dspOpt.m_Load.bBTMP = TRUE;
		else if (data == WORK_PTMP_FLD) dspOpt.m_Load.bPTMP = TRUE;
		else if (data == WORK_WDPR_AREA_FLD)  dspOpt.m_Load.bWindPArea = TRUE;
		else if (data == WORK_WDPR_BEAM_FLD)  dspOpt.m_Load.bWindPBeam = TRUE;
		else if (data == WORK_WDPR_NODAL_FLD) dspOpt.m_Load.bWindPNodal = TRUE;
		else if (data == WORK_WDPR_FUNC_FLD)  dspOpt.m_Load.bWindPFunc = TRUE;
		else if (data == WORK_EPST_FLD)  dspOpt.m_Load.bEpst = TRUE;
		else if (data == WORK_EPSE_FLD)  dspOpt.m_Load.bEpse = TRUE;
		else if (data == ID_MAIN_RIBBON_SEISEVAL_PSEUDO_FORCE) dspOpt.m_Load.bPseudoSeismic = TRUE;

		ExportDisplaySetting::SET(&dspOpt);
	}
	else  // 아이템의 하중 조건인 경우

	{
		// 선택한 아이템이 나타내는 하중 조건 찾기

		HTREEITEM parentItem = ht, prvHt;
		int pos = 0;
		for (prvHt = parentItem; prvHt != NULL; parentItem = prvHt, pos++) prvHt = GetPrevSiblingItemWithoutFilter(parentItem);
		CArray<T_STLD_K, T_STLD_K> aStldKeyList;
		pDoc->m_pAttrCtrl->GetStldKeyList(aStldKeyList);

		// Display Option Setting
		//GDisplaySetting *dspOpt = ExportDisplaySetting::GET();
		GDisplaySetting dspOpt;
		ExportDisplaySetting::GET(&dspOpt);
		dspOpt.m_Load.SetDefault();
		dspOpt.m_Load.nOption = 1;
		dspOpt.m_Load.bAllGroup = TRUE;
		dspOpt.m_Load.nLoadCaseType = D_LOADCASE_STATIC;
		dspOpt.m_Load.nLoadCase = aStldKeyList[pos - 1];
		dspOpt.m_Load.nLoadCaseIndex = pos;
		dspOpt.m_Load.bTxtAll = TRUE;
		dspOpt.m_Load.bCnld = TRUE;
		dspOpt.m_Load.bDisplacement = TRUE;
		dspOpt.m_Load.bBmld = TRUE;
		dspOpt.m_Load.bPrestress = TRUE;
		dspOpt.m_Load.bPretention = TRUE;
		dspOpt.m_Load.bFbld = TRUE;
		dspOpt.m_Load.bPlaneLoad = TRUE;
		dspOpt.m_Load.bPres = TRUE;
		dspOpt.m_Load.bArpr = TRUE;
		dspOpt.m_Load.bNodalTemp = TRUE;
		dspOpt.m_Load.bElemTemp = TRUE;
		dspOpt.m_Load.bTempGradiant = TRUE;
		dspOpt.m_Load.bWind = TRUE;
		dspOpt.m_Load.bSeismic = TRUE;
		dspOpt.m_Load.bTendonPrestress = TRUE;
		dspOpt.m_Load.bFMLD = TRUE;
		dspOpt.m_Load.bBTMP = TRUE;
		dspOpt.m_Load.bPTMP = TRUE;
		dspOpt.m_Load.bWindPArea = TRUE;
		dspOpt.m_Load.bWindPBeam = TRUE;
		dspOpt.m_Load.bWindPNodal = TRUE;
		dspOpt.m_Load.bWindPFunc = TRUE;
		ExportDisplaySetting::SET(&dspOpt);

		// 후처리 레이블

		pIGM->SetLoadCaseInfoToPostDisplay(D_LOADCASE_STATIC, aStldKeyList[pos - 1]);
	}
}

void CTreeWorkCtrl::DisplayFireLoad(HTREEITEM ht)
{
	CDBDoc* pDoc = (CDBDoc*)CTreeMenuBarBase::GetDocST();
	if (!pDoc)
	{
		TRACE(_LS(IDS_TMWK__MSG1));
		return;
	}

	I_GENModelBase * pIGM = I_GENModelBase::GetCurMySelfST();

	UINT data = GetItemData(ht);

	GDisplaySetting dspOpt;
	ExportDisplaySetting::GET(&dspOpt);

	dspOpt.m_Load.SetDefault();
	dspOpt.m_Load.nOption = 1;
	dspOpt.m_Load.bAllGroup = TRUE;
	dspOpt.m_Load.bTxtAll = TRUE;
	dspOpt.m_Load.nLoadCaseType = D_LOADCASE_STATIC;
	dspOpt.m_Load.nLoadCase = pDoc->m_pAttrCtrl->GetStldKey(FIRE_LOAD_CASE_NAME);

	if (data == WORK_FIPA_LST) dspOpt.m_Load.bFireFipa = TRUE;
	else if (data == WORK_FSSF_FLD) dspOpt.m_Load.bFireFssf = TRUE;

	ExportDisplaySetting::SET(&dspOpt);
}

void CTreeWorkCtrl::DisplayCnldType(HTREEITEM ht)
{
	HTREEITEM prvHt, curHt = ht;
	int pos = 0;
	BOOL bSuccess = FALSE;
	for (prvHt = curHt; prvHt != NULL; curHt = prvHt, pos++) prvHt = GetPrevSiblingItemWithoutFilter(curHt);
	//
	CArray<T_CNLD_KEY, T_CNLD_KEY&>	aCnldKey;
	T_CNLD_K key;
	T_CNLD_D cnld;
	T_STLD_K stldK = FindCnldType(ht); ASSERT(stldK);
	GetSelectedCnldType_Elements(stldK, pos, aCnldKey, cnld);
	//
	ILabelMgr_CH::instance()->m_DrawCnldTypeKey.RemoveAll();
	for (int i = 0; i < aCnldKey.GetSize(); i++)
	{
		key.keymap = aCnldKey[i];
		ILabelMgr_CH::instance()->m_DrawCnldTypeKey.Add(key);
	}
	ILabelMgr_CH::instance()->m_bDrawCnldType = true;
	ILabelMgr_CH::instance()->SetDrawPresQueryColorStatus();
}

