void CTreeWorkCtrl::DisplayDimension(HTREEITEM ht)
{
	CArray<T_DIMM_K, T_DIMM_K> akey;
	int nNum = GetSelectedDimmKeyListWithMultiTreeItemSelect(akey);
	for (int i = 0; i < nNum; i++)
	{
		if (I_GENModelBase::GetCurMySelfST()->IsCurShowDimensionLinkeKey(akey[i])) continue;
		else I_GENModelBase::GetCurMySelfST()->AddCurShowDimensionLineKey(akey[i]);
	}

	I_GENModelBase::GetCurMySelfST()->ViewInvalidate4WorksTree(FALSE);

	SetDimensionDisplayText(TRUE);
}

void CTreeWorkCtrl::DisplayStoryTracingAndLineGrid(HTREEITEM ht)
{
	CArray<T_STOR_K, T_STOR_K> akey;

	int nNum = GetSelectedStorKeyListWithMultiTreeItemSelect(akey);
	DisplayStoryTracingAndLineGrid(akey);
}

void CTreeWorkCtrl::DisplayStoryTracingAndLineGridAll(HTREEITEM ht)
{
	CArray<T_STOR_K, T_STOR_K> akey;

	CDBDoc* pDoc = (CDBDoc*)CTreeMenuBarBase::GetDocST();
	pDoc->m_pAttrCtrl->GetStorKeyList(akey);
	DisplayStoryTracingAndLineGrid(akey);
}

void CTreeWorkCtrl::DisplayStoryTracingAndLineGrid(const CArray<T_STOR_K, T_STOR_K>& akey)
{
	CDBDoc* pDoc = (CDBDoc*)CTreeMenuBarBase::GetDocST();
	const int nNum = akey.GetSize();
	for (int i = 0; i < nNum; i++)
	{
		T_STOR_D StorD;
		if (!pDoc->m_pAttrCtrl->GetStor(akey[i], StorD)) continue;

		if (pDoc->m_pAttrCtrl2->ExistTdas(StorD.TdasK))
		{
			if (I_GENModelBase::GetCurMySelfST()->IsCurShowTracingStoryKey(akey[i]) == FALSE)
				I_GENModelBase::GetCurMySelfST()->AddCurShowTracingStoryKey(akey[i]);
		}

		if (CStorSubData::GetInstance().HasStorKeyForLineGrid(akey[i]))
		{
			// set이라 중복을 거른다.
			I_GENModelBase::GetCurMySelfST()->AddCurShowLineGridStoryKey(akey[i]);
			I_GENModelBase::GetCurMySelfST()->UpdateLineGrid(false);
		}
	}

	I_GENModelBase::GetCurMySelfST()->ViewInvalidate4WorksTree(FALSE);

	SetTracingAndLineGridDisplayText(true);

	T_UPDATE_HINT Hint;
	Hint.csNotifyCmd = _LSX(DIMM_DISPLAY_CHANGED);
	CDBDoc::GetDocPoint()->UpdateAllViews(NULL, D_UPDATE_NOTIFY, &Hint);
}

void CTreeWorkCtrl::OnSelchanged(NMHDR* pNMHDR, LRESULT* pResult)
{
	NM_TREEVIEW* pNMTreeView = (NM_TREEVIEW*)pNMHDR;

	*pResult = 0;
}

void CTreeWorkCtrl::OnSelchanging(NMHDR* pNMHDR, LRESULT* pResult)
{
	NM_TREEVIEW* pNMTreeView = (NM_TREEVIEW*)pNMHDR;

	CArray<HTREEITEM, HTREEITEM> aItem;
	int selItemNum = GetSelectedItemList(aItem);
	BOOL  bMulti = FALSE;

	short nKeyState = GetKeyState(VK_LCONTROL);
	if (nKeyState & 0x8000) bMulti = TRUE;
	if (bMulti == FALSE) { nKeyState = GetKeyState(VK_LSHIFT); if (nKeyState & 0x8000) bMulti = TRUE; }

	if (selItemNum && bMulti)
	{
		HTREEITEM preParItem = GetParentItem(aItem[0]);
		UINT preParData = GetItemData(preParItem);
		HTREEITEM newParItem = GetParentItem(pNMTreeView->itemNew.hItem);
		UINT newParData = GetItemData(newParItem);
		if (preParData != newParData) { *pResult = TRUE; return; }
	}
	// need to debug

	*pResult = 0;
}


int CTreeWorkCtrl::GetSelectedGrupKeyListWithMultiTreeItemSelect(CArray<T_GRUP_K, T_GRUP_K> &aKey)
{
	CDBDoc* pDoc = (CDBDoc*)CTreeMenuBarBase::GetDocST();
	if (!pDoc)
	{
		TRACE(_LS(IDS_TMWK__MSG1));
		return FALSE;
	}

	CArray<HTREEITEM, HTREEITEM> aItem;
	int selItemNum = GetSelectedItemList(aItem);

	CArray<T_GRUP_K, T_GRUP_K> aKeyList;
	pDoc->m_pAttrCtrl->GetGrupKeyList(aKeyList);

	// 선택한 Group의 Key값 찾기

	HTREEITEM prvHt, ht, nxtHt;
	int pos = 0, nSt = 0;
	ht = aItem[0];

	for (prvHt = ht;;) { prvHt = GetPrevSiblingItemWithoutFilter(ht); if (prvHt == NULL) break; ht = prvHt; } // 그룹 아이템의 제일 앞으로 가기 
	for (nxtHt = ht; nxtHt != NULL; ht = nxtHt, pos++) // 뒤로 하나식 가면서 선택된 것인지 확인해서 배열에 넣기
	{
		for (int i = nSt; i < aItem.GetSize(); i++)
			if (ht == aItem[i]) { aKey.Add(aKeyList[pos]); nSt += 1; }
		nxtHt = GetNextSiblingItemWithoutFilter(ht);
	}
	return aKey.GetSize();
}

int CTreeWorkCtrl::GetSelectedElemKeyListWithMultiTreeItemSelect(CArray<T_ELEM_K, T_ELEM_K> &aKey)
{
	CDBDoc* pDoc = (CDBDoc*)CTreeMenuBarBase::GetDocST();
	if (!pDoc)
	{
		TRACE(_LS(IDS_TMWK__MSG1));
		return FALSE;
	}

	CArray<HTREEITEM, HTREEITEM> aItem;
	int selItemNum = GetSelectedItemList(aItem);
	CArray<int, int> aElList;
	CArray<T_NODE_K, T_NODE_K> pKeyNode;

	for (int i = 0; i < aItem.GetSize(); i++)
	{
		UINT data = GetItemData(aItem[i]);
		if (data == WORK_TRUSS_LST) aElList.Add(TRUSS_EL);
		else if (data == WORK_TRTENS_LST) aElList.Add(TRTENS_EL);
		else if (data == WORK_TRCOMP_LST) aElList.Add(TRCOMP_EL);
		else if (data == WORK_BEAM_LST) aElList.Add(BEAM_EL);
		else if (data == WORK_PLATE_LST) aElList.Add(PLATE_EL);
		else if (data == WORK_PLSTRS_LST) aElList.Add(PLSTRS_EL);
		else if (data == WORK_PLSTRN_LST) aElList.Add(PLSTRN_EL);
		else if (data == WORK_AXISYM_LST) aElList.Add(AXISYM_EL);
		else if (data == WORK_SOLID_LST) aElList.Add(SOLID_EL);
		else if (data == WORK_WALL_LST) aElList.Add(WALL_EL);
		else if (data == WORK_WALLOPEN_LST) aElList.Add(WALLOPEN_EL);
		else if (data == WORK_ESSF_LST) aElList.Add(BEAM_EL);
	}
	pDoc->m_pAttrCtrl->GetKeyListEltypeUser(&aElList, &pKeyNode, &aKey);
	return aKey.GetSize();
}

int CTreeWorkCtrl::GetSelectedStorKeyListWithMultiTreeItemSelect(CArray<T_STOR_K, T_STOR_K> &aKey)
{
	CDBDoc* pDoc = (CDBDoc*)CTreeMenuBarBase::GetDocST();
	if (!pDoc) { TRACE(_LS(IDS_TMWK__MSG1));    return FALSE; }

	CArray<HTREEITEM, HTREEITEM> aItem;
	int selItemNum = GetSelectedItemList(aItem);
	if (selItemNum == 0) return FALSE;

	HTREEITEM prvHt, ht, nxtHt;
	int pos = 0, nSt = 0;
	ht = aItem[0];

	CArray<T_STOR_K, T_STOR_K> aStorK;
	pDoc->m_pAttrCtrl->GetStorKeyListByModlSort(aStorK);

	for (prvHt = ht;;) { prvHt = GetPrevSiblingItemWithoutFilter(ht); if (prvHt == NULL) break; ht = prvHt; }
	for (nxtHt = ht; nxtHt != NULL; ht = nxtHt, pos++)
	{
		for (int i = nSt; i < aItem.GetSize(); i++)
			if (ht == aItem[i]) { aKey.Add(aStorK[pos]); nSt += 1; }
		nxtHt = GetNextSiblingItemWithoutFilter(ht);
	}
	return aKey.GetSize();
}

