int CTreeWorkCtrl::GetSelectedDomainKeyListWithMultiTreeItemSelect(std::vector<T_SBDO_K> &aKey)
{
	CDBDoc* pDoc = (CDBDoc*)CTreeMenuBarBase::GetDocST();
	if (!pDoc)
	{
		TRACE(_LS(IDS_TMWK__MSG1));
		return FALSE;
	}

	CArray<HTREEITEM, HTREEITEM> aItem;
	int selItemNum = GetSelectedItemList(aItem);
	if (selItemNum == 0) return FALSE;

	int pos = 0;
	HTREEITEM prvHt, ht, nxtHt;
	for (int i = 0; i < aItem.GetSize(); ++i)
	{
		ht = aItem[i];

		// 첫번째 tree item
		for (prvHt = ht;;) { prvHt = GetPrevSiblingItemWithoutFilter(ht); if (prvHt == NULL) break; ht = prvHt; }

		// 동일 Level item 중에서 선택된 item의 index(몇번째 item인가?)
		for (nxtHt = ht, pos = 0; nxtHt != NULL; ht = nxtHt, pos++)
		{
			if (ht == aItem[i])
			{
				T_MADO_K MadoK = GetMadoKeyItemSbdo(ht);
				if (MadoK == 0)
				{
					nxtHt = GetNextSiblingItemWithoutFilter(ht);
					continue;
				}
				std::vector<T_SBDO_K> arSbdoKey; arSbdoKey.clear();
				int nSbdoSize = pDoc->m_pAttrCtrl->GetSbdoKeyList(MadoK, arSbdoKey, TRUE);
				aKey.push_back(arSbdoKey[pos]);
			}
			nxtHt = GetNextSiblingItemWithoutFilter(ht);
		}
	}

	return (int)aKey.size();
}

T_MADO_K CTreeWorkCtrl::GetMadoKeyItemSbdo(HTREEITEM SbdoHt)
{
	CDBDoc* pDoc = (CDBDoc*)CTreeMenuBarBase::GetDocST();

	HTREEITEM parentMadoItem = GetParentItem(SbdoHt);
	UINT parentMadoData = GetItemData(parentMadoItem);
	if (parentMadoData != WORK_MADO_LST)
	{
		ASSERT(0);
		return 0;
	}

	HTREEITEM prvHt, ht, nxtHt;
	int pos = 0, nSt = 0;
	ht = parentMadoItem;

	std::vector<T_MADO_K> aMadoK;
	pDoc->m_pAttrCtrl->GetMadoKeyList(aMadoK);

	for (prvHt = ht;;) { prvHt = GetPrevSiblingItemWithoutFilter(ht); if (prvHt == NULL) break; ht = prvHt; }
	for (nxtHt = ht; nxtHt != NULL; ht = nxtHt, pos++)
	{
		if (ht == parentMadoItem)
		{
			return aMadoK[pos];
		}
		nxtHt = GetNextSiblingItemWithoutFilter(ht);
	}
	return 0;
}

