int CTreeWorkCtrl::GetSelectedCrgrGrupDataWithMultiTreeItemSelect(T_CRGR_D& CrgrD, CArray<T_NODE_K, T_NODE_K> &rNode)
{
	CDBDoc* pDoc = (CDBDoc*)CTreeMenuBarBase::GetDocST();
	if (!pDoc)
	{
		TRACE(_LS(IDS_TMWK__MSG1));
		return FALSE;
	}

	CMap<T_GRUP_K, T_GRUP_K, int, int> mapKeyDel;
	mapKeyDel.InitHashTable(11);

	CArray<T_GRUP_K, T_GRUP_K> aKey;

	CArray<HTREEITEM, HTREEITEM> aItem;
	int selItemNum = GetSelectedItemList(aItem);
	if (selItemNum == 0) return FALSE;

	T_CRGR_D CrgrData;
	pDoc->m_pAttrCtrl->GetCrgr(CrgrData);


	HTREEITEM prvHt, ht, nxtHt;
	int pos = 0, nSt = 0;
	ht = aItem[0];

	for (prvHt = ht;;) { prvHt = GetPrevSiblingItemWithoutFilter(ht); if (prvHt == NULL) break; ht = prvHt; }
	for (nxtHt = ht; nxtHt != NULL; ht = nxtHt, pos++)
	{
		for (int i = nSt; i < aItem.GetSize(); i++)
		{
			if (ht == aItem[i])
			{
				aKey.Add(CrgrData.aSelectedGroup[pos]);
				mapKeyDel.SetAt(CrgrData.aSelectedGroup[pos], 1);
				nSt += 1;
			}

		}
		nxtHt = GetNextSiblingItemWithoutFilter(ht);
	}


	// 변경될 데이타.
	int nTemp = 0;
	for (int i = 0; i < CrgrData.aSelectedGroup.GetSize(); i++)
	{
		if (mapKeyDel.Lookup(CrgrData.aSelectedGroup[i], nTemp)) continue;

		CrgrD.aSelectedGroup.Add(CrgrData.aSelectedGroup[i]);
	}

	// 현재 선택된 node
	rNode.RemoveAll();
	for (int i = 0; i < aKey.GetSize(); i++)
	{
		T_GRUP_D GrupData;
		pDoc->m_pAttrCtrl->GetGrup(aKey[i], GrupData);

		rNode.Append(GrupData.arKeyNode);
	}

	return aKey.GetSize();

}

