int CTreeWorkCtrl::GetSelectedConsKeyListWithMultiTreeItemSelect(CArray<T_CONS_K, T_CONS_K> &aKey)
{
	CDBDoc* pDoc = (CDBDoc*)CTreeMenuBarBase::GetDocST();
	if (!pDoc)
	{
		TRACE(_LS(IDS_TMWK__MSG1));
		return FALSE;
	}

	CArray<T_CONS_K, T_CONS_K> aConsKeyList;
	pDoc->m_pAttrCtrl->GetConsKeyList(aConsKeyList);
	int nConsCount = aConsKeyList.GetSize();

	T_CONS_D consData;
	CArray<T_CONS_D, T_CONS_D> aSelKey;
	GetSelectedConsDataListWithMultiTreeItemSelect(aSelKey);

	for (int i = 0; i < nConsCount; i++)
	{
		pDoc->m_pAttrCtrl->GetCons(aConsKeyList[i], consData);
		for (int j = 0; j < aSelKey.GetSize(); j++)
		{
			if (consData.Constraint[0] == aSelKey[j].Constraint[0] && consData.Constraint[1] == aSelKey[j].Constraint[1] &&
				consData.Constraint[2] == aSelKey[j].Constraint[2] && consData.Constraint[3] == aSelKey[j].Constraint[3] &&
				consData.Constraint[4] == aSelKey[j].Constraint[4] && consData.Constraint[5] == aSelKey[j].Constraint[5] &&
				consData.Constraint[6] == aSelKey[j].Constraint[6])
			{
				aKey.Add(aConsKeyList[i]); break;
			}
		}
	}
	return aKey.GetSize();
}

