int CTreeWorkCtrl::GetSelectedNsprLinearKeyListWithMultiTreeItemSelect(CArray<T_NSPR_K, T_NSPR_K> &aKey)
{
	CDBDoc* pDoc = (CDBDoc*)CTreeMenuBarBase::GetDocST();
	if (!pDoc)
	{
		TRACE(_LS(IDS_TMWK__MSG1));
		return FALSE;
	}
	const double zero = pDoc->m_pInitCtrl->GetPreferenceRegardZero();

	CArray<T_NSPR_K, T_NSPR_K> aNsprKeyList, tempKeyList;
	pDoc->m_pAttrCtrl->GetNsprKeyList(aNsprKeyList);
	T_NSPR_D NsprData;
	for (int i = 0; i < aNsprKeyList.GetSize(); i++)
	{
		if (!pDoc->m_pAttrCtrl->GetNspr(aNsprKeyList[i], NsprData)) ASSERT(0);
		if (NsprData.nGenCompTen == 0) tempKeyList.Add(aNsprKeyList[i]);
	}
	aNsprKeyList.RemoveAll();
	aNsprKeyList.Copy(tempKeyList);

	int nNsprCount = aNsprKeyList.GetSize();

	T_NSPR_D nsprData;
	CArray<T_NSPR_D, T_NSPR_D> aSelKey;
	GetSelectedNsprLinearDataListWithMultiTreeItemSelect(aSelKey);

	for (int i = 0; i < nNsprCount; i++)
	{
		pDoc->m_pAttrCtrl->GetNspr(aNsprKeyList[i], nsprData);
		for (int j = 0; j < aSelKey.GetSize(); j++)
		{
			if (fabs(nsprData.Spring[0] - aSelKey[j].Spring[0]) <= zero && fabs(nsprData.Spring[1] - aSelKey[j].Spring[1]) <= zero &&
				fabs(nsprData.Spring[2] - aSelKey[j].Spring[2]) <= zero && fabs(nsprData.Spring[3] - aSelKey[j].Spring[3]) <= zero &&
				fabs(nsprData.Spring[4] - aSelKey[j].Spring[4]) <= zero && fabs(nsprData.Spring[5] - aSelKey[j].Spring[5]) <= zero &&
				fabs(nsprData.dDamping[0] - aSelKey[j].dDamping[0]) <= zero && fabs(nsprData.dDamping[1] - aSelKey[j].dDamping[1]) <= zero &&
				fabs(nsprData.dDamping[2] - aSelKey[j].dDamping[2]) <= zero && fabs(nsprData.dDamping[3] - aSelKey[j].dDamping[3]) <= zero &&
				fabs(nsprData.dDamping[4] - aSelKey[j].dDamping[4]) <= zero && fabs(nsprData.dDamping[5] - aSelKey[j].dDamping[5]) <= zero &&
				nsprData.bDamping == aSelKey[j].bDamping)
			{
				aKey.Add(aNsprKeyList[i]); break;
			}
		}
	}
	return aKey.GetSize();
}

