int CTreeWorkCtrl::GetSelectedNsprNonKeyListWithMultiTreeItemSelect(CArray<T_NSPR_K, T_NSPR_K> &aKey)
{
	CDBDoc* pDoc = (CDBDoc*)CTreeMenuBarBase::GetDocST();
	if (!pDoc)
	{
		TRACE(_LS(IDS_TMWK__MSG1));
		return FALSE;
	}
	const double zero = pDoc->m_pInitCtrl->GetPreferenceRegardZero();

	CArray<T_NSPR_K, T_NSPR_K> aNsprKeyList, tempKeyList;
	pDoc->m_pAttrCtrl->GetNsprKeyList(aNsprKeyList);

	T_NSPR_D NsprData;
	for (int i = 0; i < aNsprKeyList.GetSize(); i++)
	{
		if (!pDoc->m_pAttrCtrl->GetNspr(aNsprKeyList[i], NsprData)) ASSERT(0);
		if (NsprData.nGenCompTen == 1 || NsprData.nGenCompTen == 2) tempKeyList.Add(aNsprKeyList[i]);
	}
	aNsprKeyList.RemoveAll();
	aNsprKeyList.Copy(tempKeyList);

	int nNsprCount = aNsprKeyList.GetSize();

	T_NSPR_D nsprData;
	CArray<T_NSPR_D, T_NSPR_D> aSelKey;
	GetSelectedNsprNonDataListWithMultiTreeItemSelect(aSelKey);

	for (int i = 0; i < nNsprCount; i++)
	{
		pDoc->m_pAttrCtrl->GetNspr(aNsprKeyList[i], nsprData);
		for (int j = 0; j < aSelKey.GetSize(); j++)
		{
			if (nsprData.nGenCompTen == aSelKey[j].nGenCompTen &&
				fabs(nsprData.dStiffness - aSelKey[j].dStiffness) <= zero && nsprData.nDirection == aSelKey[j].nDirection)
			{
				if (nsprData.nDirection != 6)
				{
					aKey.Add(aNsprKeyList[i]); break;
				}
				else
				{
					if (fabs(nsprData.dVx - aSelKey[j].dVx) <= zero && fabs(nsprData.dVy - aSelKey[j].dVy) <= zero && fabs(nsprData.dVz - aSelKey[j].dVz) <= zero)
					{
						aKey.Add(aNsprKeyList[i]); break;
					}
				}
			}
		}
	}
	return aKey.GetSize();
}

