int CTreeWorkCtrl::GetSelectedCnldKeyListWithMultiTreeItemSelect(CArray<T_CNLD_K, T_CNLD_K> &aKey)
{
	CArray<HTREEITEM, HTREEITEM> aItem;
	int selItemNum = GetSelectedItemList(aItem);
	if (selItemNum == 0) return FALSE;

	CDBDoc* pDoc = (CDBDoc*)CTreeMenuBarBase::GetDocST();

	CArray<UINT, UINT> aSelDataList;
	CArray<T_STLD_K, T_STLD_K> aStldKeyList, aSelStldKeyList;
	pDoc->m_pAttrCtrl->GetStldKeyList(aStldKeyList);

	for (int i = 0; i < aItem.GetSize(); i++)
	{
		HTREEITEM parentItem = GetParentItem(aItem[i]);
		HTREEITEM prvHt;
		int pos = 0;
		for (prvHt = parentItem; prvHt != NULL; parentItem = prvHt, pos++) prvHt = GetPrevSiblingItemWithoutFilter(parentItem);
		aSelStldKeyList.Add(aStldKeyList[pos - 1]);
		aSelDataList.Add(GetItemData(aItem[i]));
	}

	for (int i = 0; i < aSelDataList.GetSize(); i++)
	{
		POSITION  cnldPos;
		T_CNLD_K  cnldKey;
		T_CNLD_D  cnldData;
		int       cnldNum = 0;

		cnldPos = pDoc->m_pAttrCtrl->GetStartCnld();
		while (cnldPos != NULL)
		{
			pDoc->m_pAttrCtrl->GetNextCnld(cnldPos, cnldKey, cnldData);
			if (cnldData.LoadCaseKey == aSelStldKeyList[i]) aKey.Add(cnldKey);
		}
	}

	return aKey.GetSize();
}

