int CTreeWorkCtrl::GetSelectedRfstKeyListWithMultiTreeItemSelect(CArray<T_RFST_K, T_RFST_K>& aKey)
{
	CDBDoc* pDoc = (CDBDoc*)CTreeMenuBarBase::GetDocST();
	if (!pDoc)
	{
		TRACE(_LS(IDS_TMWK__MSG1));
		return FALSE;
	}

	CArray<HTREEITEM, HTREEITEM> aItem;
	int selItemNum = GetSelectedItemList(aItem);
	if (selItemNum == 0) return FALSE;

	HTREEITEM prvHt, ht, nxtHt;
	int pos = 0, nSt = 0;
	ht = aItem[0];

	for (prvHt = ht;;)
	{
		prvHt = GetPrevSiblingItem(ht); 
		if (prvHt == NULL) 
			break; 
		ht = prvHt;
	}
	CArray<T_RFST_K, T_RFST_K> aKeyList;
	pDoc->m_pAttrCtrl->GetRfstKeyList(aKeyList);
	for (nxtHt = ht; nxtHt != NULL; ht = nxtHt, pos++)
	{
		for (int i = nSt; i < aItem.GetSize(); i++)
			if (ht == aItem[i])
			{
				aKey.Add(aKeyList[pos]); nSt += 1;
			}
		nxtHt = GetNextSiblingItem(ht);
	}
	return aKey.GetSize();
}

