int CTreeWorkCtrl::GetSelectedSspsNonKeyListWithMultiTreeItemSelect(CArray<T_SSPS_K, T_SSPS_K> &aKey)
{
	CDBDoc* pDoc = (CDBDoc*)CTreeMenuBarBase::GetDocST();
	if (!pDoc)
	{
		TRACE(_LS(IDS_TMWK__MSG1));
		return FALSE;
	}
	const double zero = pDoc->m_pInitCtrl->GetPreferenceRegardZero();

	CArray<T_SSPS_K, T_SSPS_K> aSspsKeyList, tempKeyList;
	pDoc->m_pAttrCtrl->GetSspsKeyList(aSspsKeyList);

	T_SSPS_D SspsData;
	for (int i = 0; i < aSspsKeyList.GetSize(); i++)
	{
		if (!pDoc->m_pAttrCtrl->GetSsps(aSspsKeyList[i], SspsData)) ASSERT(0);
		if (SspsData.nSpringType == 1 || SspsData.nSpringType == 2) tempKeyList.Add(aSspsKeyList[i]);
	}
	aSspsKeyList.RemoveAll();
	aSspsKeyList.Copy(tempKeyList);

	int nSspsCount = aSspsKeyList.GetSize();

	CArray<T_SSPS_D, T_SSPS_D> aSelKey;
	GetSelectedSspsNonDataListWithMultiTreeItemSelect(aSelKey);

	for (int i = 0; i < nSspsCount; i++)
	{
		pDoc->m_pAttrCtrl->GetSsps(aSspsKeyList[i], SspsData);

		for (int j = 0; j < aSelKey.GetSize(); j++)
		{
			if (SspsData.nElementType == aSelKey[j].nElementType)
			{
				aKey.Add(aSspsKeyList[i]);
				break;
			}
		}
	}
	return aKey.GetSize();
}

int CTreeWorkCtrl::GetSelectedFrlsDataListWithMultiTreeItemSelect(CArray<T_FRLS_D, T_FRLS_D> &aKey)
{
	CDBDoc* pDoc = (CDBDoc*)CTreeMenuBarBase::GetDocST();
	if (!pDoc)
	{
		TRACE(_LS(IDS_TMWK__MSG1));
		return FALSE;
	}

	CArray<HTREEITEM, HTREEITEM> aItem;
	int selItemNum = GetSelectedItemList(aItem);
	if (selItemNum == 0) return FALSE;

	HTREEITEM prvHt, ht, nxtHt;
	int pos = 0, nSt = 0;
	ht = aItem[0];

	for (prvHt = ht;;) { prvHt = GetPrevSiblingItemWithoutFilter(ht); if (prvHt == NULL) break; ht = prvHt; } // 그룹 아이템의 제일 앞으로 가기 
	for (nxtHt = ht; nxtHt != NULL; ht = nxtHt, pos++) // 뒤로 하나식 가면서 선택된 것인지 확인해서 배열에 넣기
	{
		for (int i = nSt; i < aItem.GetSize(); i++)
			if (ht == aItem[i]) { aKey.Add(m_aFrlsInfo[pos]); nSt += 1; }
		nxtHt = GetNextSiblingItemWithoutFilter(ht);
	}
	return aKey.GetSize();
}

int CTreeWorkCtrl::GetSelectedFrlsKeyListWithMultiTreeItemSelect(CArray<T_FRLS_K, T_FRLS_K> &aKey)
{
	CDBDoc* pDoc = (CDBDoc*)CTreeMenuBarBase::GetDocST();
	if (!pDoc)
	{
		TRACE(_LS(IDS_TMWK__MSG1));
		return FALSE;
	}

	// 선택한 Beam End Release의 Data List 얻기
	CArray<T_FRLS_D, T_FRLS_D> aSelFrlsList;
	GetSelectedFrlsDataListWithMultiTreeItemSelect(aSelFrlsList);
	const double zero = pDoc->m_pInitCtrl->GetPreferenceRegardZero();

	// 선택한 Beam End Release Type이 할당된 Element list 만들기
	CArray<T_FRLS_K, T_FRLS_K> aFrlsKeyList;  // Beam end release
	pDoc->m_pAttrCtrl->GetFrlsKeyList(aFrlsKeyList);
	int nFrlsCount = aFrlsKeyList.GetSize();
	T_FRLS_D  frlsData;

	for (int i = 0; i < nFrlsCount; i++)
	{
		pDoc->m_pAttrCtrl->GetFrls(aFrlsKeyList[i], frlsData);
		for (int m = 0; m < aSelFrlsList.GetSize(); m++)
		{
			BOOL bSame = TRUE;
			if (frlsData.nType != aSelFrlsList[m].nType) bSame = FALSE;
			else
			{
				for (int k = 0; k < 2; k++) for (int l = 0; l < FRLS_SIZE; l++)
				{
					if (fabs(frlsData.Fixity[k][l] - aSelFrlsList[m].Fixity[k][l]) > zero ||
						frlsData.Release[k][l] != aSelFrlsList[m].Release[k][l]) {
						bSame = FALSE; break;
					}
				}
			}
			if (bSame) { aKey.Add(aFrlsKeyList[i]); break; }
		}
	}
	return aKey.GetSize();
}

