int CTreeWorkCtrl::GetSelectedOffsKeyListWithMultiTreeItemSelect(CArray<T_OFFS_K, T_OFFS_K> &aKey)
{
	CDBDoc* pDoc = (CDBDoc*)CTreeMenuBarBase::GetDocST();
	if (!pDoc)
	{
		TRACE(_LS(IDS_TMWK__MSG1));
		return FALSE;
	}
	const double zero = pDoc->m_pInitCtrl->GetPreferenceRegardZero();
	// 선택한 Beam End Offset의 Data List 얻기

	CArray<T_OFFS_D, T_OFFS_D> aSelOffsList;
	GetSelectedOffsDataListWithMultiTreeItemSelect(aSelOffsList);

	CArray<T_OFFS_K, T_OFFS_K> aOffsKeyList;
	pDoc->m_pAttrCtrl->GetOffsKeyList(aOffsKeyList);
	int nOffsCount = aOffsKeyList.GetSize();
	T_OFFS_D offsData;

	for (int i = 0; i < nOffsCount; i++)
	{
		pDoc->m_pAttrCtrl->GetOffs(aOffsKeyList[i], offsData);
		for (int j = 0; j < aSelOffsList.GetSize(); j++)
		{
			if (fabs(offsData.Offset[0] - aSelOffsList[j].Offset[0]) <= zero && fabs(offsData.Offset[1] - aSelOffsList[j].Offset[1]) <= zero &&
				fabs(offsData.Offset[2] - aSelOffsList[j].Offset[2]) <= zero && fabs(offsData.Offset[3] - aSelOffsList[j].Offset[3]) <= zero &&
				fabs(offsData.Offset[4] - aSelOffsList[j].Offset[4]) <= zero && fabs(offsData.Offset[5] - aSelOffsList[j].Offset[5]) <= zero &&
				offsData.nOffsetType == aSelOffsList[j].nOffsetType) {
				aKey.Add(aOffsKeyList[i]); break;
			}
		}
	}
	return aKey.GetSize();
}

