int CTreeWorkCtrl::GetSelectedHahsKeyListWithMultiTreeItemSelect(CArray<T_HAHS_K, T_HAHS_K> &aKey)
{
	CDBDoc* pDoc = (CDBDoc*)CTreeMenuBarBase::GetDocST();
	if (!pDoc)
	{
		TRACE(_LS(IDS_TMWK__MSG1));
		return FALSE;
	}

	CArray<CString, CString&> aName;
	GetSelectedHsfcKeyListWithMultiTreeItemSelect(aName);

	CArray<T_HAHS_K, T_HAHS_K> aHahsKeyList;
	pDoc->m_pAttrCtrl->GetHahsKeyList(aHahsKeyList);
	int nCount = aHahsKeyList.GetSize();
	T_HAHS_D  hahsData;
	T_HSFC_D  hsfcData;

	for (int i = 0; i < nCount; i++)
	{
		pDoc->m_pAttrCtrl->GetHahs(aHahsKeyList[i], hahsData);
		for (int m = 0; m < aName.GetSize(); m++)
		{
			pDoc->m_pAttrCtrl->GetHsfc(hahsData.nFuncKey, hsfcData);
			if (hsfcData.strFuncName == aName[m]) { aKey.Add(aHahsKeyList[i]); break; }
		}
	}
	aName.RemoveAll();
	aHahsKeyList.RemoveAll();
	return aKey.GetSize();
}

int CTreeWorkCtrl::GetSelectedRigdKeyListWithMultiTreeItemSelect(CArray<T_RIGD_K, T_RIGD_K> &aKey)
{
	CDBDoc* pDoc = (CDBDoc*)CTreeMenuBarBase::GetDocST();
	if (!pDoc)
	{
		TRACE(_LS(IDS_TMWK__MSG1));
		return FALSE;
	}

	CArray<HTREEITEM, HTREEITEM> aItem;
	int selItemNum = GetSelectedItemList(aItem);
	if (selItemNum == 0) return FALSE;

	HTREEITEM prvHt, ht, nxtHt;
	int pos = 0, nSt = 0;
	ht = aItem[0];

	T_RIGD_K KeyRigd;
	T_RIGD_D DataRigd;
	POSITION position = pDoc->m_pAttrCtrl->GetStartRigd();

	for (prvHt = ht;;) { prvHt = GetPrevSiblingItemWithoutFilter(ht); if (prvHt == NULL) break; ht = prvHt; } // 그룹 아이템의 제일 앞으로 가기 
	for (nxtHt = ht; nxtHt != NULL; ht = nxtHt, pos++) // 뒤로 하나식 가면서 선택된 것인지 확인해서 배열에 넣기
	{
		pDoc->m_pAttrCtrl->GetNextRigd(position, KeyRigd, DataRigd);
		for (int i = nSt; i < aItem.GetSize(); i++)
		{
			if (ht == aItem[i])
			{
				aKey.Add(KeyRigd); nSt += 1; break;
			}
		}
		nxtHt = GetNextSiblingItemWithoutFilter(ht);
	}
	return aKey.GetSize();
}

