int CTreeWorkCtrl::GetSelectedSkewKeyListWithMultiTreeItemSelect(CArray<T_SKEW_K, T_SKEW_K> &aKey)
{
	CDBDoc* pDoc = (CDBDoc*)CTreeMenuBarBase::GetDocST();
	if (!pDoc)
	{
		TRACE(_LS(IDS_TMWK__MSG1));
		return FALSE;
	}
	const double zero = pDoc->m_pInitCtrl->GetPreferenceRegardZero();

	CArray<T_SKEW_D, T_SKEW_D> aSelSkewKeyList;
	GetSelectedSkewDataListWithMultiTreeItemSelect(aSelSkewKeyList);

	CArray<T_SKEW_K, T_SKEW_K> aSkewKeyList;
	pDoc->m_pAttrCtrl->GetSkewKeyList(aSkewKeyList);
	int nSkewCount = aSkewKeyList.GetSize();
	T_SKEW_D  skewData;

	for (int i = 0; i < nSkewCount; i++)
	{
		pDoc->m_pAttrCtrl->GetSkew(aSkewKeyList[i], skewData);
		for (int m = 0; m < aSelSkewKeyList.GetSize(); m++)
		{
			BOOL bSame = TRUE;

			if (skewData.nType != aSelSkewKeyList[m].nType) bSame = FALSE;
			if (bSame == TRUE) {
				for (int k = 0; k < 3; k++)
					if (fabs(skewData.dAngle[k] - aSelSkewKeyList[m].dAngle[k]) > zero) { bSame = FALSE; break; }
			}
			if (bSame == TRUE) {
				for (int k = 0; k < 3; k++) for (int l = 0; l < 3; l++)
					if (fabs(skewData.dPoints[k][l] - aSelSkewKeyList[m].dPoints[k][l]) > zero) { bSame = FALSE; break; }
			}
			if (bSame == TRUE) {
				for (int k = 0; k < 3; k++) for (int l = 0; l < 3; l++)
					if (fabs(skewData.LocalVector[k][l] - aSelSkewKeyList[m].LocalVector[k][l]) > zero) { bSame = FALSE; break; }
			}
			if (bSame == TRUE) {
				for (int k = 0; k < 2; k++) for (int l = 0; l < 3; l++)
					if (fabs(skewData.dVector[k][l] - aSelSkewKeyList[m].dVector[k][l]) > zero) { bSame = FALSE; break; }
			}

			if (bSame) { aKey.Add(aSkewKeyList[i]); break; }
		}
	}
	return aKey.GetSize();
}

// Define Constraint Label Direction
int CTreeWorkCtrl::GetSelectedCldrKeyListWithMultiTreeItemSelect(CArray<T_CLDR_K, T_CLDR_K> &aKey)
{
	CDBDoc* pDoc = (CDBDoc*)CTreeMenuBarBase::GetDocST();
	if (!pDoc)
	{
		TRACE(_LS(IDS_TMWK__MSG1));
		return FALSE;
	}

	aKey.RemoveAll();

	CArray<HTREEITEM, HTREEITEM> aItem;
	int selItemNum = GetSelectedItemList(aItem);
	if (selItemNum == 0) return FALSE;

	HTREEITEM prvHt, ht, nxtHt;
	int pos = 0, nSt = 0;
	ht = aItem[0];

	for (prvHt = ht;;) { prvHt = GetPrevSiblingItemWithoutFilter(ht); if (prvHt == NULL) break; ht = prvHt; } // 그룹 아이템의 제일 앞으로 가기 
	for (nxtHt = ht; nxtHt != NULL; ht = nxtHt, pos++) // 뒤로 하나식 가면서 선택된 것인지 확인해서 배열에 넣기
	{
		for (int i = nSt; i < aItem.GetSize(); i++)
			if (ht == aItem[i])
			{
				UINT nDir = m_aCldrDir[pos];

				if (nDir == D_CLDR_LXP)
					aKey.Append(m_aCldrXPKey);
				else if (nDir == D_CLDR_LXM)
					aKey.Append(m_aCldrXNKey);
				else if (nDir == D_CLDR_LYP)
					aKey.Append(m_aCldrYPKey);
				else if (nDir == D_CLDR_LYM)
					aKey.Append(m_aCldrYNKey);
				else if (nDir == D_CLDR_LZP)
					aKey.Append(m_aCldrZPKey);
				else if (nDir == D_CLDR_LZM)
					aKey.Append(m_aCldrZNKey);

				nSt += 1;
			}
		nxtHt = GetNextSiblingItemWithoutFilter(ht);
	}
	return aKey.GetSize();
}

