int CTreeWorkCtrl::GetSelectedThmsKeyListWithMultiTreeItemSelect(CArray<T_THMS_K, T_THMS_K> &aKey)
{
	CDBDoc* pDoc = (CDBDoc*)CTreeMenuBarBase::GetDocST();
	if (!pDoc)
	{
		TRACE(_LS(IDS_TMWK__MSG1));
		return FALSE;
	}

	const double zero = pDoc->m_pInitCtrl->GetPreferenceRegardZero();

	CArray<T_THMS_D, T_THMS_D> aSelThmsData;
	GetSelectedThmsDataListWithMultiTreeItemSelect(aSelThmsData);

	POSITION  thmsPos;
	T_THMS_K  ThmsK;
	T_THMS_D  ThmsD;

	thmsPos = pDoc->m_pAttrCtrl->GetStartThms();
	while (thmsPos != NULL)
	{
		pDoc->m_pAttrCtrl->GetNextThms(thmsPos, ThmsK, ThmsD);
		for (int j = 0; j < aSelThmsData.GetSize(); j++)
		{
			if (ThmsD.ThisKey == aSelThmsData[j].ThisKey &&
				((ThmsD.nThisFuncKey[0] == aSelThmsData[j].nThisFuncKey[0] && fabs(ThmsD.dArrivalTime[0] - aSelThmsData[j].dArrivalTime[0]) <= zero && fabs(ThmsD.dFactor[0] - aSelThmsData[j].dFactor[0]) <= zero)) &&
				((ThmsD.nThisFuncKey[1] == aSelThmsData[j].nThisFuncKey[1] && fabs(ThmsD.dArrivalTime[1] - aSelThmsData[j].dArrivalTime[1]) <= zero && fabs(ThmsD.dFactor[1] - aSelThmsData[j].dFactor[1]) <= zero)) &&
				((ThmsD.nThisFuncKey[2] == aSelThmsData[j].nThisFuncKey[2] && fabs(ThmsD.dArrivalTime[2] - aSelThmsData[j].dArrivalTime[2]) <= zero && fabs(ThmsD.dFactor[2] - aSelThmsData[j].dFactor[2]) <= zero)) &&
				fabs(ThmsD.dAngleHGA - aSelThmsData[j].dAngleHGA) <= zero) {
				aKey.Add(ThmsK); break;
			}
		}
	}
	return aKey.GetSize();
}

