int CTreeWorkCtrl::GetSelectedThnlKeyListWithMultiTreeItemSelect(CArray<T_THNL_K, T_THNL_K> &aKey)
{
	CDBDoc* pDoc = (CDBDoc*)CTreeMenuBarBase::GetDocST();
	if (!pDoc)
	{
		TRACE(_LS(IDS_TMWK__MSG1));
		return FALSE;
	}
	const double zero = pDoc->m_pInitCtrl->GetPreferenceRegardZero();

	CArray<T_THNL_D, T_THNL_D> aSelThnlKey;
	GetSelectedThnlDataListWithMultiTreeItemSelect(aSelThnlKey);

	POSITION  thnlPos;
	T_THNL_K  thnlKey;
	T_THNL_D  thnlData;

	thnlPos = pDoc->m_pAttrCtrl->GetStartThnl();
	while (thnlPos != NULL)
	{
		pDoc->m_pAttrCtrl->GetNextThnl(thnlPos, thnlKey, thnlData);
		for (int j = 0; j < aSelThnlKey.GetSize(); j++)
		{
			if (thnlData.LoadCaseKey == aSelThnlKey[j].LoadCaseKey && thnlData.nLoadType == aSelThnlKey[j].nLoadType &&
				thnlData.nThisFuncKey == aSelThnlKey[j].nThisFuncKey && thnlData.nDirection == aSelThnlKey[j].nDirection &&
				fabs(thnlData.dArrivalTime - aSelThnlKey[j].dArrivalTime) <= zero && fabs(thnlData.dFactor - aSelThnlKey[j].dFactor) <= zero)
			{
				aKey.Add(thnlKey); break;
			}
		}
	}
	return aKey.GetSize();
}

