int CTreeWorkCtrl::GetSelectedNmasKeyListWithMultiTreeItemSelect(CArray<T_NMAS_K, T_NMAS_K> &aKey)
{
	CDBDoc* pDoc = (CDBDoc*)CTreeMenuBarBase::GetDocST();
	if (!pDoc)
	{
		TRACE(_LS(IDS_TMWK__MSG1));
		return FALSE;
	}
	const double zero = pDoc->m_pInitCtrl->GetPreferenceRegardZero();

	CArray<T_NMAS_D, T_NMAS_D> aSelNmasKey;
	GetSelectedNmasDataListWithMultiTreeItemSelect(aSelNmasKey);

	CArray<T_NMAS_K, T_NMAS_K> aNmasKeyList;
	pDoc->m_pAttrCtrl->GetNmasKeyList(aNmasKeyList);
	int nNmasCount = aNmasKeyList.GetSize();
	T_NMAS_D nmasData;

	for (int i = 0; i < nNmasCount; i++)
	{
		pDoc->m_pAttrCtrl->GetNmas(aNmasKeyList[i], nmasData);
		for (int j = 0; j < aSelNmasKey.GetSize(); j++)
		{
			if (fabs(nmasData.Mass[0] - aSelNmasKey[j].Mass[0]) <= zero && fabs(nmasData.Mass[1] - aSelNmasKey[j].Mass[1]) <= zero &&
				fabs(nmasData.Mass[2] - aSelNmasKey[j].Mass[2]) <= zero && fabs(nmasData.Mass[3] - aSelNmasKey[j].Mass[3]) <= zero &&
				fabs(nmasData.Mass[4] - aSelNmasKey[j].Mass[4]) <= zero && fabs(nmasData.Mass[5] - aSelNmasKey[j].Mass[5]) <= zero)
			{
				aKey.Add(aNmasKeyList[i]); break;
			}
		}
	}
	return aKey.GetSize();
}

