int CTreeWorkCtrl::GetSelectedWssfKeyListWithMultiTreeItemSelect(CArray<T_WSSF_K, T_WSSF_K> &aKey)
{
	CDBDoc* pDoc = (CDBDoc*)CTreeMenuBarBase::GetDocST();
	if (!pDoc)
	{
		TRACE(_LS(IDS_TMWK__MSG1));
		return FALSE;
	}

	CArray<HTREEITEM, HTREEITEM> aItem;
	int selItemNum = GetSelectedItemList(aItem);
	if (selItemNum == 0) return FALSE;

	HTREEITEM prvHt, ht, nxtHt;
	int pos = 0, nSt = 0;
	ht = aItem[0];
	CArray<T_WSSF_K, T_WSSF_K> aWssfK;
	pDoc->m_pAttrCtrl->GetWssfKeyList(aWssfK);

	T_WSSF_D  WssfD;
	for (prvHt = ht;;) { prvHt = GetPrevSiblingItemWithoutFilter(ht); if (prvHt == NULL) break; ht = prvHt; }
	for (nxtHt = ht; nxtHt != NULL; ht = nxtHt, pos++)
	{
		for (int i = nSt; i < aItem.GetSize(); i++)
		{
			if (ht == aItem[i])
			{
				for (int j = 0; j < aWssfK.GetSize(); j++)
				{
					pDoc->m_pAttrCtrl->GetWssf(aWssfK[j], WssfD);
					if (
						WssfD.GroupKey == m_aWssfInfo[pos].GroupKey    &&
						WssfD.dShear == m_aWssfInfo[pos].dShear      &&  WssfD.dBending == m_aWssfInfo[pos].dBending    && WssfD.dAxial == m_aWssfInfo[pos].dAxial &&
						WssfD.dOutBending == m_aWssfInfo[pos].dOutBending &&  WssfD.dOutShear == m_aWssfInfo[pos].dOutShear   && WssfD.dOutTorsion == m_aWssfInfo[pos].dOutTorsion)
					{
						T_ELEM_D ElemD, TgtElemD;
						if (!pDoc->m_pAttrCtrl->GetElem(aWssfK[j].key.entity, ElemD)) { ASSERT(0); continue; }
						if (!pDoc->m_pAttrCtrl->GetElem(m_aWssfItemKey[pos].key.entity, TgtElemD)) { ASSERT(0); continue; }
						if (ElemD.nWallType == TgtElemD.nWallType)
						{
							aKey.Add(aWssfK[j]);
						}
					}
				}
				nSt += 1;
			}
		}
		nxtHt = GetNextSiblingItemWithoutFilter(ht);
	}
	aWssfK.RemoveAll();
	return aKey.GetSize();
}

