int CTreeWorkCtrl::GetSelectedSpanKeyListWithMultiTreeItemSelect(CArray<T_SPAN_K, T_SPAN_K> &aKey, CArray<T_ELEM_K, T_ELEM_K> &rElem, int nSectType, BOOL bVirtual/*=FALSE*/)
{
	CDBDoc* pDoc = (CDBDoc*)CTreeMenuBarBase::GetDocST();
	if (!pDoc)
	{
		TRACE(_LS(IDS_TMWK__MSG1));
		return FALSE;
	}

	CArray<HTREEITEM, HTREEITEM> aItem;
	int selItemNum = GetSelectedItemList(aItem);

	CArray<T_SPAN_K, T_SPAN_K> aKeyList;
	pDoc->m_pAttrCtrl->GetSpanOrSpavKeyList(aKeyList, nSectType, bVirtual);

	// 선택한 SPan의 Key값 찾기

	HTREEITEM prvHt, ht, nxtHt;
	int pos = 0, nSt = 0;
	ht = aItem[0];

	for (prvHt = ht;;) { prvHt = GetPrevSiblingItemWithoutFilter(ht); if (prvHt == NULL) break; ht = prvHt; } // 그룹 아이템의 제일 앞으로 가기 
	for (nxtHt = ht; nxtHt != NULL; ht = nxtHt, pos++) // 뒤로 하나식 가면서 선택된 것인지 확인해서 배열에 넣기
	{
		for (int i = nSt; i < aItem.GetSize(); i++)
			if (ht == aItem[i]) { aKey.Add(aKeyList[pos]); nSt += 1; }
		nxtHt = GetNextSiblingItemWithoutFilter(ht);
	}
	int nSpanCount = aKey.GetSize();
	T_SPAN_D spanData;
	if (nSpanCount)
	{
		int nNum = 0;
		rElem.RemoveAll();
		for (int i = 0; i < nSpanCount; i++)
		{
			pDoc->m_pAttrCtrl->GetSpanOrSpav(aKey[i], spanData, bVirtual);
			nNum = spanData.aElemBase.GetSize();

			if (bVirtual)
			{
				for (int j = 0; j < nNum; j++)
				{
					for (int m = 0; m < spanData.aElemBase.GetSize(); m++)
					{
						T_VBEM_D VbemD;
						T_VBEM_K VbemK = spanData.aElemBase[m].ElemK;

						if (!pDoc->m_pAttrCtrl2->GetVbem(VbemK, VbemD)) { ASSERT(0); continue; }

						T_VSEC_D VsecD;
						if (!pDoc->m_pAttrCtrl2->GetVsec(VbemD.Vsec1, VsecD)) ASSERT(0);
						if (VsecD.arKeyElem.GetSize() > 0) rElem.Append(VsecD.arKeyElem);

						if (!pDoc->m_pAttrCtrl2->GetVsec(VbemD.Vsec2, VsecD)) ASSERT(0);
						if (VsecD.arKeyElem.GetSize() > 0) rElem.Append(VsecD.arKeyElem);
					}
				}
			}
			else
			{
				for (int j = 0; j < nNum; j++)
				{
					rElem.Add(spanData.aElemBase[j].ElemK);
				}
			}
		}
	}
	return aKey.GetSize();
}

int CTreeWorkCtrl::GetSelectedSpanKeyListWithMultiTreeItemSelect(CArray<T_SPAN_K, T_SPAN_K> &aKey, CArray<CString, CString&> &aStrName, CArray<int, int> &aSectType, BOOL bVirtual/*=FALSE*/)
{
	CDBDoc* pDoc = (CDBDoc*)CTreeMenuBarBase::GetDocST();
	if (!pDoc)
	{
		TRACE(_LS(IDS_TMWK__MSG1));
		return FALSE;
	}

	CArray<HTREEITEM, HTREEITEM> aItem;
	int selItemNum = GetSelectedItemList(aItem);

	CArray<T_SPAN_K, T_SPAN_K> aKeyList;
	pDoc->m_pAttrCtrl->GetSpanOrSpavKeyList(aKeyList, bVirtual);

	// 선택한 SPan의 Key값 찾기

	HTREEITEM prvHt, ht, nxtHt;
	int pos = 0, nSt = 0;
	ht = aItem[0];

	for (prvHt = ht;;) { prvHt = GetPrevSiblingItemWithoutFilter(ht); if (prvHt == NULL) break; ht = prvHt; } // 그룹 아이템의 제일 앞으로 가기 
	for (nxtHt = ht; nxtHt != NULL; ht = nxtHt, pos++) // 뒤로 하나식 가면서 선택된 것인지 확인해서 배열에 넣기
	{
		for (int i = nSt; i < aItem.GetSize(); i++)
			if (ht == aItem[i]) { aKey.Add(aKeyList[pos]); nSt += 1; }
		nxtHt = GetNextSiblingItemWithoutFilter(ht);
	}
	int nSpanCount = aKey.GetSize();
	T_SPAN_D spanData;
	if (nSpanCount)
	{
		aStrName.RemoveAll();
		for (int i = 0; i < nSpanCount; i++)
		{
			pDoc->m_pAttrCtrl->GetSpanOrSpav(aKey[i], spanData, bVirtual);
			aStrName.Add(spanData.Name);
			aSectType.Add(spanData.nSectType);
		}
	}
	return aKey.GetSize();
}

int CTreeWorkCtrl::IsUsedMatl(HTREEITEM hItem)
{
	CDBDoc* pDoc = CDBDoc::GetDocPoint();
	if (!pDoc)
	{
		TRACE(_LS(IDS_TMWK__MSG1));
		return FALSE;
	}

	//HTREEITEM ht, prvHt;
	int pos = 0;
	//ht = hItem;
	//for (prvHt = ht; prvHt != NULL; ht = prvHt, pos++) prvHt = GetPrevSiblingItemWithoutFilter(ht);
	GetItemIndexInSiblingItem(hItem, pos);

	T_MATL_D  matData;
	if (pDoc->m_pAttrCtrl->IsUsedMatl(m_aMatlItemKey[pos - 1])) // 사용된 것이면 
	{
		if (pDoc->m_pAttrCtrl->GetMatl(m_aMatlItemKey[pos - 1], matData)) return 1; // 정의 된 것이면 
		else return -1; // 정의 안된 것이면 
	}
	else return 0; // 사용 안된 것이면 
}

