BOOL CTreeWorkCtrl::IsUsedFimp(HTREEITEM hItem)
{
	CDBDoc* pDoc = CDBDoc::GetDocPoint();
	if (!pDoc) { TRACE(_LS(IDS_TMWK__MSG1)); return FALSE; }

	HTREEITEM ht, prvHt;
	int pos = 0;
	ht = hItem;
	for (prvHt = ht; prvHt != NULL; ht = prvHt, pos++) prvHt = GetPrevSiblingItemWithoutFilter(ht);

	CArray<T_FIMP_K, T_FIMP_K> aFimpKeyList;
	pDoc->m_pAttrCtrl->GetFimpKeyList(aFimpKeyList);
	T_FIMP_K FimpKey = aFimpKeyList[pos - 1];

	T_FIBR_D FibrData;
	int nCount = m_aFibrItemKey_TH.GetSize();

	CArray<T_IEHP_K, T_IEHP_K> aIehpKeyList;
	pDoc->m_pAttrCtrl->GetIehpKeyList(aIehpKeyList);
	int nIehpCount = aIehpKeyList.GetSize();

	CArray<T_IEHG_K, T_IEHG_K> aIehgK;
	pDoc->m_pAttrCtrl->GetIehgKeyList(aIehgK);
	int nSize = aIehgK.GetSize();

	// 이거 이중루프 성능개선 할까?
	for (int i = 0; i < nCount; i++)
	{
		for (int j = 0; j < nIehpCount; j++)
		{
			const T_IEHP_D* pIehp = pDoc->m_pAttrCtrl->GetIehpConstPtr(aIehpKeyList[j]);
			if (pIehp == nullptr) continue;

			if (pIehp->nHingeType != D_IEHP_HTYP_BEAM_DIST)
				continue;

			if (pIehp->FibrKey == m_aFibrItemKey_TH[i])
			{
				for (int k = 0; k < nSize; k++)
				{
					T_IEHG_D IehgD;
					if (!pDoc->m_pAttrCtrl->GetIehg(aIehgK[k], IehgD)) continue;
					if (IehgD.IehpKey == aIehpKeyList[j])
					{
						pDoc->m_pAttrCtrl->GetFibr(m_aFibrItemKey_TH[i], FibrData);
						if (FibrData.FimpKey[0] == FimpKey) return 1;
						if (FibrData.FimpKey[1] == FimpKey) return 1;
						if (FibrData.FimpKey[2] == FimpKey) return 1;
						//!@#$ MNET:1691 20051207 LBI : 3 -> 6
						if (FibrData.FimpKey[3] == FimpKey) return 1;
						if (FibrData.FimpKey[4] == FimpKey) return 1;
						if (FibrData.FimpKey[5] == FimpKey) return 1;
					}
				}
			}
		}
	}

	T_FIBW_D FibwData;
	nCount = m_aFibwItemKey_TH.GetSize();
	for (int i = 0; i < nCount; i++)
	{
		for (int j = 0; j < nIehpCount; j++)
		{
			const T_IEHP_D* pIehp = pDoc->m_pAttrCtrl->GetIehpConstPtr(aIehpKeyList[j]);
			if (pIehp == nullptr) continue;

			if (pIehp->nHingeType != D_IEHP_HTYP_WALL)
				continue;

			if (pIehp->FibrKey == m_aFibwItemKey_TH[i])
			{
				for (int k = 0; k < nSize; k++)
				{
					T_IEHG_D IehgD;
					if (!pDoc->m_pAttrCtrl->GetIehg(aIehgK[k], IehgD)) continue;
					if (IehgD.IehpKey == aIehpKeyList[j])
					{
						pDoc->m_pAttrCtrl->GetFibw(m_aFibwItemKey_TH[i], FibwData);
						if (FibwData.FimpKey[0] == FimpKey) return 1;
						if (FibwData.FimpKey[1] == FimpKey) return 1;
						if (FibwData.FimpKey[2] == FimpKey) return 1;
						if (FibwData.FimpKey[3] == FimpKey) return 1;
						if (FibwData.FimpKey[4] == FimpKey) return 1;
						if (FibwData.FimpKey[5] == FimpKey) return 1;
					}
				}
			}
		}
	}

	// 자동생성된 친구들
	T_ELEM_D ElemD;
	T_IEHG_D IehgD;
	for (int i = 0; i < aIehgK.GetSize(); i++)
	{
		if (!pDoc->m_pAttrCtrl->GetIehg(aIehgK[i], IehgD)) continue;
		if (IehgD.FiberKey == 0) continue;

		if (!pDoc->m_pAttrCtrl->GetElem(aIehgK[i].key.objK, ElemD)) continue;
		if (ElemD.eltyp == BEAM_EL)
		{
			if (!pDoc->m_pAttrCtrl->GetFibr(IehgD.FiberKey, FibrData)) continue;
			if (FibrData.FimpKey[0] == FimpKey) return 1;
			if (FibrData.FimpKey[1] == FimpKey) return 1;
			if (FibrData.FimpKey[2] == FimpKey) return 1;
			if (FibrData.FimpKey[3] == FimpKey) return 1;
			if (FibrData.FimpKey[4] == FimpKey) return 1;
			if (FibrData.FimpKey[5] == FimpKey) return 1;
		}
		else
		{
			if (!pDoc->m_pAttrCtrl->GetFibw(IehgD.FiberKey, FibwData)) continue;
			if (FibwData.FimpKey[0] == FimpKey) return 1;
			if (FibwData.FimpKey[1] == FimpKey) return 1;
			if (FibwData.FimpKey[2] == FimpKey) return 1;
			if (FibwData.FimpKey[3] == FimpKey) return 1;
			if (FibwData.FimpKey[4] == FimpKey) return 1;
			if (FibwData.FimpKey[5] == FimpKey) return 1;
		}
	}

	return 0; // 사용 안된 것이면 
}

