BOOL CTreeWorkCtrl::IsUsedIehp(HTREEITEM hItem)
{
	CDBDoc* pDoc = CDBDoc::GetDocPoint();
	if (!pDoc) { TRACE(_LS(IDS_TMWK__MSG1)); return FALSE; }
	if (m_aIehpItemKey.GetSize() == 0) return FALSE;

	HTREEITEM ht, prvHt;
	int pos = 0;
	ht = hItem;
	for (prvHt = ht; prvHt != NULL; ht = prvHt, pos++) prvHt = GetPrevSiblingItemWithoutFilter(ht);
	T_IEHP_K IehpK = m_aIehpItemKey[pos - 1];

	const T_IEHP_D* pIehp = pDoc->m_pAttrCtrl->GetIehpConstPtr(IehpK);
	if (pIehp == nullptr) return FALSE;

	BOOL bFind = FALSE;
	if (pIehp->nHingeType != 2)   // 0=Lumped, 1=Distributed, 2=Spring(6.5.0추가), 3=Truss(6.9.0추가), 4=Wall(CRB)
	{
		///// Inelastic Link
		CArray<T_IEHG_K, T_IEHG_K> aIehgK;
		pDoc->m_pAttrCtrl->GetIehgKeyList(aIehgK);
		int nSize = aIehgK.GetSize();
		for (int i = 0; i < nSize; ++i)
		{
			T_IEHG_D IehgD;
			if (!pDoc->m_pAttrCtrl->GetIehg(aIehgK[i], IehgD)) continue;
			if (IehgD.IehpKey == IehpK)
			{
				bFind = TRUE;
				break;
			}
		}
	}
	else
	{
		///// general link
		CArray<T_NLNK_K, T_NLNK_K> aNlnkK;
		pDoc->m_pAttrCtrl->GetNlnkKeyList(aNlnkK);

		T_NLNK_D NlnkD;
		T_NLLP_D NllpD;
		for (int i = 0; i < aNlnkK.GetSize(); ++i)
		{
			pDoc->m_pAttrCtrl->GetNlnk(aNlnkK[i], NlnkD);
			pDoc->m_pAttrCtrl->GetNllp(NlnkD.PropKey, NllpD); // MNET:1931 20060118 JHKIM
			BOOL bSpring = (NllpD.nApplicationType == 0 && NllpD.nElemType == 0);
			if (bSpring && NlnkD.IehpKey == IehpK)
			{
				bFind = TRUE;
				break;
			}
		}
	}

	if (bFind) return TRUE;
	return FALSE;
}

// 2 가지 용도로 쓰이는 함수
BOOL CTreeWorkCtrl::IsUsedPhgt(HTREEITEM hItem, BOOL bUpdateStatus)
{
	CDBDoc* pDoc = CDBDoc::GetDocPoint();
	if (!pDoc) { TRACE(_LS(IDS_TMWK__MSG1)); return FALSE; }

	if (bUpdateStatus || m_aUsedPhgt.GetSize() == 0)
	{
		CMap<T_PHGT_K, T_PHGT_K, BOOL, BOOL> mapUsed;
		mapUsed.RemoveAll();
		mapUsed.InitHashTable(HASHSIZEPHGT);

		T_PHGE_K PhgeK;
		T_PHGE_D PhgeD;
		BOOL bUsed = FALSE;

		POSITION pos = pDoc->m_pAttrCtrl->GetStartPhge();
		while (pos != NULL)
		{
			pDoc->m_pAttrCtrl->GetNextPhge(pos, PhgeK, PhgeD);
			if (!mapUsed.Lookup(PhgeD.HingeTypeK, bUsed))
				mapUsed.SetAt(PhgeD.HingeTypeK, TRUE);
		}

		// map을 가지고 Array 에 저장
		CArray<T_PHGT_K, T_PHGT_K> aPhgtK;
		pDoc->m_pAttrCtrl->GetPhgtKeyList(aPhgtK);
		int nSize = aPhgtK.GetSize();
		m_aUsedPhgt.RemoveAll(); // 초기화
		m_aUsedPhgt.SetSize(nSize);
		for (int i = 0; i < nSize; ++i)
		{
			if (mapUsed.Lookup(aPhgtK[i], bUsed)) m_aUsedPhgt[i] = 1;
			else m_aUsedPhgt[i] = 0;
		}
		if (bUpdateStatus)
			return FALSE;
	}

	if (!bUpdateStatus)
	{
		HTREEITEM ht, prvHt;
		int pos = 0;
		ht = hItem;
		for (prvHt = ht; prvHt != NULL; ht = prvHt, pos++) prvHt = GetPrevSiblingItemWithoutFilter(ht);

		int i = pos - 1;
		if (i < 0 || i >= m_aUsedPhgt.GetSize())
			return FALSE;
		else
			return (m_aUsedPhgt[pos - 1] == 1);
	}

	return FALSE;

}

