BOOL CTreeWorkCtrl::IsUsedTdmf(HTREEITEM hItem)
{
	CDBDoc* pDoc = CDBDoc::GetDocPoint();
	if (!pDoc)
	{
		TRACE(_LS(IDS_TMWK__MSG1));
		return FALSE;
	}

	HTREEITEM ht, prvHt;
	int pos = 0;
	ht = hItem;
	for (prvHt = ht; prvHt != NULL; ht = prvHt, pos++) prvHt = GetPrevSiblingItemWithoutFilter(ht);

	CArray<T_TDMF_K, T_TDMF_K> aTdmfKey;
	pDoc->m_pAttrCtrl->GetTdmfKeyList(aTdmfKey);

	if (pos > aTdmfKey.GetSize())
		pos = aTdmfKey.GetSize();

	CArray<T_TDMT_K, T_TDMT_K> aTdmtKey;
	pDoc->m_pAttrCtrl->GetTdmtKeyList(aTdmtKey);
	for (int i = 0; i < aTdmtKey.GetSize(); i++)
	{
		T_TDMT_D  tdmtData;
		pDoc->m_pAttrCtrl->GetTdmt(aTdmtKey[i], tdmtData);
		if (tdmtData.COMMON.nCode == 4) // User Define
		{
			if (aTdmfKey[pos - 1] == tdmtData.USER.ShrinkageStrainFuncKey) return TRUE;
			for (int j = 0; j < tdmtData.aCreepFunc.GetSize(); j++)
			{
				if (aTdmfKey[pos - 1] == tdmtData.aCreepFunc[j].CreepFuncKey) return TRUE;
			}
		}
	}

	// Relaxation 관련 (Tendon Property)
	CArray<T_TDNT_K, T_TDNT_K> aTdntKey;
	pDoc->m_pAttrCtrl->GetTdntKeyList(aTdntKey);
	for (int i = 0; i < aTdntKey.GetSize(); i++)
	{
		T_TDNT_D  tdntData;
		pDoc->m_pAttrCtrl->GetTdnt(aTdntKey[i], tdntData);
		if (aTdmfKey[pos - 1] == tdntData.TdmfKey) return TRUE;
	}

	return FALSE;
}

