BOOL CTreeWorkCtrl::IsUsedThfc(HTREEITEM hItem)
{
	CDBDoc* pDoc = CDBDoc::GetDocPoint();
	if (!pDoc)
	{
		TRACE(_LS(IDS_TMWK__MSG1));
		return FALSE;
	}

	HTREEITEM ht, prvHt;
	int pos = 0;
	ht = hItem;
	for (prvHt = ht; prvHt != NULL; ht = prvHt, pos++) prvHt = GetPrevSiblingItemWithoutFilter(ht);

	CArray<T_THFC_K, T_THFC_K> aThfc;
	pDoc->m_pAttrCtrl->GetThfcKeyList(aThfc);

	// Dynamic Nodal Load에서 사용되었는지 확인
	POSITION  thnlPos;
	T_THNL_K  thnlKey;
	T_THNL_D  thnlData;

	thnlPos = pDoc->m_pAttrCtrl->GetStartThnl();
	while (thnlPos != NULL)
	{
		pDoc->m_pAttrCtrl->GetNextThnl(thnlPos, thnlKey, thnlData);
		if (thnlData.nThisFuncKey == aThfc[pos - 1]) { return TRUE; }
	}
	// Ground Acceleration에서 사용되었는지 확인 
	POSITION  thgaPos;
	T_THGA_K  thgaKey;
	T_THGA_D  thgaData;

	thgaPos = pDoc->m_pAttrCtrl->GetStartThga();
	while (thgaPos != NULL)
	{
		pDoc->m_pAttrCtrl->GetNextThga(thgaPos, thgaKey, thgaData);
		if (thgaData.nThisFuncKey[0] == aThfc[pos - 1]) { return TRUE; }
		if (thgaData.nThisFuncKey[1] == aThfc[pos - 1]) { return TRUE; }
		if (thgaData.nThisFuncKey[2] == aThfc[pos - 1]) { return TRUE; }
	}
	// Time Varying Static Load에서 사용되었는지 확인 
	POSITION  thslPos;
	T_THSL_K  thslKey;
	T_THSL_D  thslData;

	thslPos = pDoc->m_pAttrCtrl->GetStartThsl();
	while (thslPos != NULL)
	{
		pDoc->m_pAttrCtrl->GetNextThsl(thslPos, thslKey, thslData);
		if (thslData.nThisFuncKey == aThfc[pos - 1]) { return TRUE; }
	}
	// Multiple Support Excitation에 사용되었는지 확인 
	POSITION ThmsPos;
	T_THMS_K ThmsK;
	T_THMS_D ThmsD;

	ThmsPos = pDoc->m_pAttrCtrl->GetStartThms();
	while (ThmsPos != NULL)
	{
		pDoc->m_pAttrCtrl->GetNextThms(ThmsPos, ThmsK, ThmsD);

		if (ThmsD.nThisFuncKey[0] == aThfc[pos - 1]) { return TRUE; }
		if (ThmsD.nThisFuncKey[1] == aThfc[pos - 1]) { return TRUE; }
		if (ThmsD.nThisFuncKey[2] == aThfc[pos - 1]) { return TRUE; }
	}

	return FALSE;
}

BOOL CTreeWorkCtrl::IsUsedLlan(HTREEITEM hItem)
{
	CDBDoc* pDoc = CDBDoc::GetDocPoint();
	if (!pDoc)
	{
		TRACE(_LS(IDS_TMWK__MSG1));
		return FALSE;
	}

	HTREEITEM ht, prvHt;
	int pos = 0;
	ht = hItem;
	for (prvHt = ht; prvHt != NULL; ht = prvHt, pos++) prvHt = GetPrevSiblingItemWithoutFilter(ht);

	CArray<T_LLAN_K, T_LLAN_K> aLlan;
	pDoc->m_pAttrCtrl->GetLlanKeyList(aLlan);
	int nSize = aLlan.GetSize();
	if (nSize < 1) return FALSE;

	CArray<T_MVLD_K, T_MVLD_K> aMvld;
	pDoc->m_pAttrCtrl->GetMvldKeyList(aMvld);
	//nSize = aMvld.GetSize(); // 20080418 jhyun MQC:1779
	//if(nSize<1) return FALSE;

	T_MVCD_D MvcdD;
	if (!pDoc->m_pAttrCtrl->GetMvcd(MvcdD)) MvcdD.Initialize();

	for (int i = 0; i < aMvld.GetSize(); i++)
	{
		T_MVLD_D  mvldData;
		pDoc->m_pAttrCtrl->GetMvld(aMvld[i], mvldData);
		if (mvldData.bLoadCaseForPermitLoad)
		{
			if (aLlan[pos - 1] == mvldData.RefLaneK) return TRUE;
		}
		else
		{
			if (MvcdD.nCodeType == D_MOVE_CODE_EURO_BS)
			{
				if (mvldData.nLoadModel == 0 || mvldData.nLoadModel == 2 || mvldData.nLoadModel == 3)
				{
					// Seleted Lane 이 선택되야 기타 Lane 을 지정할수 있다.
					for (int j = 0; j < mvldData.SubLoadCase.aSelectedLanes.GetSize(); j++)
					{
						if (aLlan[pos - 1] == mvldData.SubLoadCase.aSelectedLanes[j]) return TRUE;
					}

					if (mvldData.nLoadModel == 0)
					{
						for (int j = 0; j < mvldData.aFootwayLanes.GetSize(); j++)
						{
							if (aLlan[pos - 1] == mvldData.aFootwayLanes[j]) return TRUE;
						}
					}

					for (int j = 0; j < mvldData.aSelectedRemainingArea.GetSize(); j++)
					{
						if (aLlan[pos - 1] == mvldData.aSelectedRemainingArea[j]) return TRUE;
					}
				}
				else
				{
					for (int j = 0; j < mvldData.arSubLoadData.GetSize(); j++)
					{
						for (int k = 0; k < mvldData.arSubLoadData[j].aSelectedLanes.GetSize(); k++)
							if (aLlan[pos - 1] == mvldData.arSubLoadData[j].aSelectedLanes[k]) return TRUE;
					}
				}
			}
			else if (MvcdD.nCodeType == D_MOVE_CODE_SOUTH_AFRICA)
			{
				if (mvldData.bAutoOptimize) continue;

				if (mvldData.nLoadModel == 0 || mvldData.nLoadModel == 1 || mvldData.nLoadModel == 2)
				{
					for (int j = 0; j < mvldData.SubLoadCase.aSelectedLanes.GetSize(); j++)
					{
						if (aLlan[pos - 1] == mvldData.SubLoadCase.aSelectedLanes[j]) return TRUE;
					}
				}
				else if (mvldData.nLoadModel == 3)
				{
					for (int j = 0; j < mvldData.aNCLanes.GetSize(); j++)
					{
						if (aLlan[pos - 1] == mvldData.aNCLanes[j]) return TRUE;
					}

					for (int j = 0; j < mvldData.aNALanes.GetSize(); j++)
					{
						if (aLlan[pos - 1] == mvldData.aNALanes[j]) return TRUE;
					}
				}
				else
				{
					for (int j = 0; j < mvldData.arSubLoadData.GetSize(); j++)
					{
						for (int k = 0; k < mvldData.arSubLoadData[j].aSelectedLanes.GetSize(); k++)
							if (aLlan[pos - 1] == mvldData.arSubLoadData[j].aSelectedLanes[k]) return TRUE;
					}
				}
			}
			else if (MvcdD.nCodeType == D_MOVE_CODE_POLAND)
			{
				if (mvldData.bAutoOptimize) continue;

				if (mvldData.nLoadModel == 0)
				{
					for (int j = 0; j < mvldData.arSubLoadData.GetSize(); j++)
					{
						for (int k = 0; k < mvldData.arSubLoadData[j].aSelectedLanes.GetSize(); k++)
							if (aLlan[pos - 1] == mvldData.arSubLoadData[j].aSelectedLanes[k]) return TRUE;
					}
				}
				else
				{
					for (int j = 0; j < mvldData.SubLoadCase.aSelectedLanes.GetSize(); j++)
					{
						if (aLlan[pos - 1] == mvldData.SubLoadCase.aSelectedLanes[j]) return TRUE;
					}
				}
			}
			else if (MvcdD.nCodeType == D_MOVE_CODE_AUSTRALIA)
			{
				if (mvldData.bAutoOptimize) continue;

				if (mvldData.nLoadModel == 2 || mvldData.nLoadModel == 6) // Heavy / Group2
				{
					for (int j = 0; j < mvldData.aNALanes.GetSize(); j++)
					{
						if (aLlan[pos - 1] == mvldData.aNALanes[j]) return TRUE;
					}
				}
				else if (mvldData.nLoadModel == 4) //B Double
				{
					for (int j = 0; j < mvldData.aNALanes.GetSize(); j++)
					{
						if (aLlan[pos - 1] == mvldData.aNALanes[j]) return TRUE;
					}
				}
				else
				{
					for (int j = 0; j < mvldData.arSubLoadData.GetSize(); j++)
					{
						for (int k = 0; k < mvldData.arSubLoadData[j].aSelectedLanes.GetSize(); k++)
							if (aLlan[pos - 1] == mvldData.arSubLoadData[j].aSelectedLanes[k]) return TRUE;
					}
				}
			}
			else if (MvcdD.nCodeType == D_MOVE_CODE_NEWZEALAND)
			{
				if (mvldData.bAutoOptimize) continue;

				if (mvldData.nLoadModel == 1) //Traffic load
				{
					for (int j = 0; j < mvldData.aNALanes.GetSize(); j++)
					{
						if (aLlan[pos - 1] == mvldData.aNALanes[j]) return TRUE;
					}
					for (int j = 0; j < mvldData.aNCLanes.GetSize(); j++)
					{
						if (aLlan[pos - 1] == mvldData.aNCLanes[j]) return TRUE;
					}
				}
				else
				{
					for (int j = 0; j < mvldData.arSubLoadData.GetSize(); j++)
					{
						for (int k = 0; k < mvldData.arSubLoadData[j].aSelectedLanes.GetSize(); k++)
							if (aLlan[pos - 1] == mvldData.arSubLoadData[j].aSelectedLanes[k]) return TRUE;
					}
				}
			}
			else if (MvcdD.nCodeType == D_MOVE_CODE_BRAZIL)
			{
				if (mvldData.nLoadModel == 0) //Traffic load
				{
					for (int j = 0; j < mvldData.aNALanes.GetSize(); j++)
					{
						if (aLlan[pos - 1] == mvldData.aNALanes[j]) return TRUE;
					}
					for (int j = 0; j < mvldData.aFootwayLanes.GetSize(); j++)
					{
						if (aLlan[pos - 1] == mvldData.aFootwayLanes[j]) return TRUE;
					}
				}
				else
				{
					for (int j = 0; j < mvldData.arSubLoadData.GetSize(); j++)
					{
						for (int k = 0; k < mvldData.arSubLoadData[j].aSelectedLanes.GetSize(); k++)
							if (aLlan[pos - 1] == mvldData.arSubLoadData[j].aSelectedLanes[k]) return TRUE;
					}
				}
			}
			else
			{
				for (int j = 0; j < mvldData.arSubLoadData.GetSize(); j++)
				{
					for (int k = 0; k < mvldData.arSubLoadData[j].aSelectedLanes.GetSize(); k++)
						if (aLlan[pos - 1] == mvldData.arSubLoadData[j].aSelectedLanes[k]) return TRUE;
				}
			}
		}
	}

	CArray<T_MVLDbs_K, T_MVLDbs_K> aMvldbs;
	pDoc->m_pAttrCtrl->GetMvldbsKeyList(aMvldbs);
	for (int i = 0; i < aMvldbs.GetSize(); i++)
	{
		T_MVLDbs_D  mvldData;
		pDoc->m_pAttrCtrl->GetMvldbs(aMvldbs[i], mvldData);

		if (mvldData.bAutoOptimize)
		{
			if (mvldData.nLoadModel == 2) // All Model 1
			{
				for (int j = 0; j < mvldData.aSelectedRemainingArea.GetSize(); j++)
				{
					if (aLlan[pos - 1] == mvldData.aSelectedRemainingArea[j]) return TRUE;
				}
			}
			continue;
		}

		if (mvldData.nLoadModel == 0 || mvldData.nLoadModel == 4)
		{
			for (int j = 0; j < mvldData.arSubLoadData.GetSize(); j++)
			{
				for (int k = 0; k < mvldData.arSubLoadData[j].aSelectedLanes.GetSize(); k++)
					if (aLlan[pos - 1] == mvldData.arSubLoadData[j].aSelectedLanes[k]) return TRUE;
			}
		}
		else
		{
			for (int j = 0; j < mvldData.aSelectedLanes.GetSize(); j++)
			{
				if (aLlan[pos - 1] == mvldData.aSelectedLanes[j]) return TRUE;
			}
		}

		if (mvldData.nLoadModel == 2) // All Model 1
		{
			for (int j = 0; j < mvldData.aSelectedRemainingArea.GetSize(); j++)
			{
				if (aLlan[pos - 1] == mvldData.aSelectedRemainingArea[j]) return TRUE;
			}
		}

	}
	return FALSE;
}

