BOOL CTreeWorkCtrl::IsUsedLlanop(HTREEITEM hItem)
{
	CDBDoc* pDoc = CDBDoc::GetDocPoint();
	if (!pDoc)
	{
		TRACE(_LS(IDS_TMWK__MSG1));
		return FALSE;
	}

	HTREEITEM ht, prvHt;
	int pos = 0;
	ht = hItem;
	for (prvHt = ht; prvHt != NULL; ht = prvHt, pos++) prvHt = GetPrevSiblingItemWithoutFilter(ht);

	CArray<T_LLANop_K, T_LLANop_K> aLlan;
	pDoc->m_pAttrCtrl->GetLlanopKeyList(aLlan);
	int nSize = aLlan.GetSize();
	if (nSize < 1) return FALSE;

	T_MVCD_D MvcdD;
	if (!pDoc->m_pAttrCtrl->GetMvcd(MvcdD)) MvcdD.Initialize();

	CArray<T_MVLD_K, T_MVLD_K> aMvld;
	pDoc->m_pAttrCtrl->GetMvldKeyList(aMvld);

	for (int i = 0; i < aMvld.GetSize(); i++)
	{
		T_MVLD_D  mvldData;
		pDoc->m_pAttrCtrl->GetMvld(aMvld[i], mvldData);
		if (mvldData.bAutoOptimize)
		{
			if (MvcdD.nCodeType == D_MOVE_CODE_EURO_BS)
			{
				if (mvldData.nLoadModel == 3)
				{
					if (aLlan[pos - 1] == mvldData.OptimizeLane2) return TRUE;
				}
				else
				{
					if (aLlan[pos - 1] == mvldData.OptimizeLane)  return TRUE;
				}
			}
			else
			{
				if (aLlan[pos - 1] == mvldData.OptimizeLane)  return TRUE;
			}
		}
	}

	CArray<T_MVLDbs_K, T_MVLDbs_K> aMvldbs;
	pDoc->m_pAttrCtrl->GetMvldbsKeyList(aMvldbs);

	for (int i = 0; i < aMvldbs.GetSize(); i++)
	{
		T_MVLDbs_D  mvldDatabs;
		pDoc->m_pAttrCtrl->GetMvldbs(aMvldbs[i], mvldDatabs);
		if (mvldDatabs.bAutoOptimize)
		{
			if (mvldDatabs.bAutoLiveLoadComb)
			{
				if (aLlan[pos - 1] == mvldDatabs.OptimizeLane2) return TRUE;
			}
			else
			{
				if (aLlan[pos - 1] == mvldDatabs.OptimizeLane)  return TRUE;
			}
		}
	}

	CArray<T_MVLDch_K, T_MVLDch_K> aMvldch;
	pDoc->m_pAttrCtrl->GetMvldchKeyList(aMvldch);

	for (int i = 0; i < aMvldch.GetSize(); i++)
	{
		T_MVLDch_D  mvldDatach;
		pDoc->m_pAttrCtrl->GetMvldch(aMvldch[i], mvldDatach);
		if (mvldDatach.bAutoOptimize)
		{
			if (aLlan[pos - 1] == mvldDatach.OptimizeLane)  return TRUE;
		}
	}

	return FALSE;
}

BOOL CTreeWorkCtrl::IsUsedSlan(HTREEITEM hItem)
{
	CDBDoc* pDoc = CDBDoc::GetDocPoint();
	if (!pDoc)
	{
		TRACE(_LS(IDS_TMWK__MSG1));
		return FALSE;
	}

	HTREEITEM ht, prvHt;
	int pos = 0;
	ht = hItem;
	for (prvHt = ht; prvHt != NULL; ht = prvHt, pos++) prvHt = GetPrevSiblingItemWithoutFilter(ht);

	CArray<T_SLAN_K, T_SLAN_K> aSlan;
	pDoc->m_pAttrCtrl->GetSlanKeyList(aSlan);

	CArray<T_MVLD_K, T_MVLD_K> aMvld;
	pDoc->m_pAttrCtrl->GetMvldKeyList(aMvld);

	T_MVCD_D MvcdD;
	if (!pDoc->m_pAttrCtrl->GetMvcd(MvcdD)) MvcdD.Initialize();

	for (int i = 0; i < aMvld.GetSize(); i++)
	{
		T_MVLD_D  mvldData;
		pDoc->m_pAttrCtrl->GetMvld(aMvld[i], mvldData);
		if (mvldData.bLoadCaseForPermitLoad)
		{
			if (aSlan[pos - 1] == mvldData.RefLaneK) return TRUE;
		}
		else
		{
			if (MvcdD.nCodeType == D_MOVE_CODE_EURO_BS)
			{
				if (mvldData.nLoadModel == 0 || mvldData.nLoadModel == 2 || mvldData.nLoadModel == 3)
				{
					// Seleted Lane 이 선택되야 기타 Lane 을 지정할수 있다.
					for (int j = 0; j < mvldData.SubLoadCase.aSelectedLanes.GetSize(); j++)
					{
						if (aSlan[pos - 1] == mvldData.SubLoadCase.aSelectedLanes[j]) return TRUE;
					}

					if (mvldData.nLoadModel == 0)
					{
						for (int j = 0; j < mvldData.aFootwayLanes.GetSize(); j++)
						{
							if (aSlan[pos - 1] == mvldData.aFootwayLanes[j]) return TRUE;
						}
					}

					for (int j = 0; j < mvldData.aSelectedRemainingArea.GetSize(); j++)
					{
						if (aSlan[pos - 1] == mvldData.aSelectedRemainingArea[j]) return TRUE;
					}
				}
				else
				{
					for (int j = 0; j < mvldData.arSubLoadData.GetSize(); j++)
					{
						for (int k = 0; k < mvldData.arSubLoadData[j].aSelectedLanes.GetSize(); k++)
							if (aSlan[pos - 1] == mvldData.arSubLoadData[j].aSelectedLanes[k]) return TRUE;
					}
				}
			}
			else if (MvcdD.nCodeType == D_MOVE_CODE_SOUTH_AFRICA)
			{
				if (mvldData.bAutoOptimize) continue;

				if (mvldData.nLoadModel == 0 || mvldData.nLoadModel == 1 || mvldData.nLoadModel == 2)
				{
					for (int j = 0; j < mvldData.SubLoadCase.aSelectedLanes.GetSize(); j++)
					{
						if (aSlan[pos - 1] == mvldData.SubLoadCase.aSelectedLanes[j]) return TRUE;
					}
				}
				else if (mvldData.nLoadModel == 3)
				{
					for (int j = 0; j < mvldData.aNCLanes.GetSize(); j++)
					{
						if (aSlan[pos - 1] == mvldData.aNCLanes[j]) return TRUE;
					}

					for (int j = 0; j < mvldData.aNALanes.GetSize(); j++)
					{
						if (aSlan[pos - 1] == mvldData.aNALanes[j]) return TRUE;
					}
				}
				else
				{
					for (int j = 0; j < mvldData.arSubLoadData.GetSize(); j++)
					{
						for (int k = 0; k < mvldData.arSubLoadData[j].aSelectedLanes.GetSize(); k++)
							if (aSlan[pos - 1] == mvldData.arSubLoadData[j].aSelectedLanes[k]) return TRUE;
					}
				}
			}
			else if (MvcdD.nCodeType == D_MOVE_CODE_POLAND)
			{
				if (mvldData.bAutoOptimize) continue;

				if (mvldData.nLoadModel == 0)
				{
					for (int j = 0; j < mvldData.arSubLoadData.GetSize(); j++)
					{
						for (int k = 0; k < mvldData.arSubLoadData[j].aSelectedLanes.GetSize(); k++)
							if (aSlan[pos - 1] == mvldData.arSubLoadData[j].aSelectedLanes[k]) return TRUE;
					}
				}
				else
				{
					for (int j = 0; j < mvldData.SubLoadCase.aSelectedLanes.GetSize(); j++)
					{
						if (aSlan[pos - 1] == mvldData.SubLoadCase.aSelectedLanes[j]) return TRUE;
					}
				}
			}
			else if (MvcdD.nCodeType == D_MOVE_CODE_AUSTRALIA)
			{
				if (mvldData.bAutoOptimize) continue;

				if (mvldData.nLoadModel == 2 || mvldData.nLoadModel == 6) // Heavy / Group2
				{
					for (int j = 0; j < mvldData.aNALanes.GetSize(); j++)
					{
						if (aSlan[pos - 1] == mvldData.aNALanes[j]) return TRUE;
					}
				}
				else if (mvldData.nLoadModel == 4) //B Double
				{
					for (int j = 0; j < mvldData.aNALanes.GetSize(); j++)
					{
						if (aSlan[pos - 1] == mvldData.aNALanes[j]) return TRUE;
					}
				}
				else
				{
					for (int j = 0; j < mvldData.arSubLoadData.GetSize(); j++)
					{
						for (int k = 0; k < mvldData.arSubLoadData[j].aSelectedLanes.GetSize(); k++)
							if (aSlan[pos - 1] == mvldData.arSubLoadData[j].aSelectedLanes[k]) return TRUE;
					}
				}
			}
			else if (MvcdD.nCodeType == D_MOVE_CODE_NEWZEALAND)
			{
				if (mvldData.bAutoOptimize) continue;

				if (mvldData.nLoadModel == 1) //Traffic load
				{
					for (int j = 0; j < mvldData.aNALanes.GetSize(); j++)
					{
						if (aSlan[pos - 1] == mvldData.aNALanes[j]) return TRUE;
					}
					for (int j = 0; j < mvldData.aNCLanes.GetSize(); j++)
					{
						if (aSlan[pos - 1] == mvldData.aNCLanes[j]) return TRUE;
					}
				}
				else
				{
					for (int j = 0; j < mvldData.arSubLoadData.GetSize(); j++)
					{
						for (int k = 0; k < mvldData.arSubLoadData[j].aSelectedLanes.GetSize(); k++)
							if (aSlan[pos - 1] == mvldData.arSubLoadData[j].aSelectedLanes[k]) return TRUE;
					}
				}
			}
			else if (MvcdD.nCodeType == D_MOVE_CODE_BRAZIL)
			{
				if (mvldData.nLoadModel == 0) //Traffic load
				{
					for (int j = 0; j < mvldData.aNALanes.GetSize(); j++)
					{
						if (aSlan[pos - 1] == mvldData.aNALanes[j]) return TRUE;
					}
					for (int j = 0; j < mvldData.aFootwayLanes.GetSize(); j++)
					{
						if (aSlan[pos - 1] == mvldData.aFootwayLanes[j]) return TRUE;
					}
				}
				else
				{
					for (int j = 0; j < mvldData.arSubLoadData.GetSize(); j++)
					{
						for (int k = 0; k < mvldData.arSubLoadData[j].aSelectedLanes.GetSize(); k++)
							if (aSlan[pos - 1] == mvldData.arSubLoadData[j].aSelectedLanes[k]) return TRUE;
					}
				}
				}
			else
			{
				for (int j = 0; j < mvldData.arSubLoadData.GetSize(); j++)
				{
					for (int k = 0; k < mvldData.arSubLoadData[j].aSelectedLanes.GetSize(); k++)
						if (aSlan[pos - 1] == mvldData.arSubLoadData[j].aSelectedLanes[k]) return TRUE;
				}
			}
		}
	}

	CArray<T_MVLDbs_K, T_MVLDbs_K> aMvldbs;
	pDoc->m_pAttrCtrl->GetMvldbsKeyList(aMvldbs);
	for (int i = 0; i < aMvldbs.GetSize(); i++)
	{
		T_MVLDbs_D  mvldData;
		pDoc->m_pAttrCtrl->GetMvldbs(aMvldbs[i], mvldData);

		if (mvldData.bAutoOptimize)
		{
			if (mvldData.nLoadModel == 2) // All Model 1
			{
				for (int j = 0; j < mvldData.aSelectedRemainingArea.GetSize(); j++)
				{
					if (aSlan[pos - 1] == mvldData.aSelectedRemainingArea[j]) return TRUE;
				}
			}
			continue;
		}

		if (mvldData.nLoadModel == 0 || mvldData.nLoadModel == 4)
		{
			for (int j = 0; j < mvldData.arSubLoadData.GetSize(); j++)
			{
				for (int k = 0; k < mvldData.arSubLoadData[j].aSelectedLanes.GetSize(); k++)
					if (aSlan[pos - 1] == mvldData.arSubLoadData[j].aSelectedLanes[k]) return TRUE;
			}
		}
		else
		{
			for (int j = 0; j < mvldData.aSelectedLanes.GetSize(); j++)
			{
				if (aSlan[pos - 1] == mvldData.aSelectedLanes[j]) return TRUE;
			}
		}

		if (mvldData.nLoadModel == 2) // All Model 1
		{
			for (int j = 0; j < mvldData.aSelectedRemainingArea.GetSize(); j++)
			{
				if (aSlan[pos - 1] == mvldData.aSelectedRemainingArea[j]) return TRUE;
			}
		}
	}

	CArray<T_MVLDid_K, T_MVLDid_K> aMvldid;
	pDoc->m_pAttrCtrl->GetMvldidKeyList(aMvldid);
	for (int i = 0; i < aMvldid.GetSize(); i++)
	{
		T_MVLDid_D mvldData;
		pDoc->m_pAttrCtrl->GetMvldid(aMvldid[i], mvldData);
		for (int j = 0; j < mvldData.arSubLoadData.GetSize(); j++)
		{
			for (int k = 0; k < mvldData.arSubLoadData[j].aSelectedLanes.GetSize(); k++)
				if (aSlan[pos - 1] == mvldData.arSubLoadData[j].aSelectedLanes[k]) return TRUE;
			for (int k = 0; k < mvldData.arSubLoadData[j].aSelectedFootwayLanes.GetSize(); k++)
				if (aSlan[pos - 1] == mvldData.arSubLoadData[j].aSelectedFootwayLanes[k]) return TRUE;
		}

		if (mvldData.bLoadCaseForPermitLoad)
		{
			if (aSlan[pos - 1] == mvldData.RefLaneK) return TRUE;
		}
	}

	return FALSE;
}

