BOOL CTreeWorkCtrl::IsUsedAcop(UINT Data)       // 1:사용됨, 0:사용안됨      
{
	CDBDoc* pDoc = CDBDoc::GetDocPoint();
	if (!pDoc)
	{
		TRACE(_LS(IDS_TMWK__MSG1));
		return FALSE;
	}

	T_ACOP_D AcopD;
	pDoc->m_pAttrCtrl->GetAcop(AcopD);
	if (Data == WORK_PDEL_FLD) return AcopD.bPDelta;        // P-Delta
	else if (Data == WORK_BUCK_FLD) return AcopD.bBuckling;      // Buckling
	else if (Data == WORK_EIGV_FLD) return AcopD.bEigen;         // Eigenvalue
	else if (Data == WORK_HHCT_FLD) return AcopD.bHeatHydra;     // Heat of Hydration
	else if (Data == WORK_NLCT_FLD) return AcopD.bNonlinear;     // Nonlinear
	else if (Data == WORK_NLCT_LST) return AcopD.bNonlinear;
	else if (Data == WORK_STCT_FLD) return AcopD.bConstStage;    // Construction Stage
	else if (Data == WORK_BCCT_FLD) return AcopD.bBoundChange;   // Boundary Change Assignment to loadCase/Analysis
	else if (Data == WORK_SPEC_FLD) return AcopD.bResSpec;       // Response Spectrum
	else if (Data == WORK_SBCT_FLD) return AcopD.bSuspension;    // Suspension Bridge

	else if (Data == WORK_MVCT_FLD) return AcopD.bMovingLoad;    // Moving Load
	else if (Data == WORK_MVLDANLjp_FLD) return AcopD.bMovingLoad;    // Moving Load
	else if (Data == WORK_MVLDANLch_FLD) return AcopD.bMovingLoad;    // Moving Load
	else if (Data == WORK_MVLDANLid_FLD) return AcopD.bMovingLoad;    // Moving Load
	else if (Data == WORK_MVLDANLtr_FLD) return AcopD.bMovingLoad;    // Moving Load

	else if (Data == WORK_STTL_FLD) return AcopD.bSettle;        // Settlement
	else if (Data == WORK_CRAN_FLD) return AcopD.bCraneLoad;     // Crane Load
	else if (Data == WORK_PLCB_FLD) return AcopD.bComposSect;    // Composite Section
	else if (Data == WORK_THISANL_FLD) return AcopD.bTimeHist;   // Time History
	else return TRUE;   // PMS:XXXX-JWKWON-20090623 더 추가 해야함

}
