BOOL CTreeWorkCtrl::GetCustomColor(HTREEITEM hItem)
{
	MBaseTreeCtrl::GetCustomColor(hItem);

	CDBDoc* pDoc = CDBDoc::GetDocPoint();
	if (pDoc == 0) return FALSE;
	if (pDoc->m_pMultiDB->IsTempDBMode()) return FALSE;

	UINT Data = GetItemData(hItem);
	int  bUsed = 1;

	if (WORK_MATL_LST == Data)   bUsed = IsUsedMatl(hItem);
	else if (WORK_SECT_LST == Data)   bUsed = IsUsedSect(hItem);
	else if (WORK_SECV_LST == Data)   bUsed = IsUsedSecv(hItem);
	else if (WORK_THIK_LST == Data)   bUsed = IsUsedThik(hItem);
	else if (WORK_SPFC_LST == Data)   bUsed = IsUsedSpfc(hItem);
	else if (WORK_THFC_LST == Data)   bUsed = IsUsedThfc(hItem);
	else if (WORK_LLAN_LST == Data)   bUsed = IsUsedLlan(hItem);
	else if (WORK_LLANch_LST == Data) bUsed = IsUsedLlanch(hItem);
	else if (WORK_LLANid_LST == Data) bUsed = IsUsedLlanid(hItem);
	else if (WORK_LLANfr_LST == Data) bUsed = IsUsedLlanfr(hItem);
	else if (WORK_LLANjp_LST == Data) bUsed = IsUsedLlanjp(hItem);
	else if (WORK_LLANtr_LST == Data) bUsed = IsUsedLlantr(hItem);
	else if (WORK_LLANop_LST == Data) bUsed = IsUsedLlanop(hItem);
	else if (WORK_SLAN_LST == Data)   bUsed = IsUsedSlan(hItem);
	else if (WORK_SLANch_LST == Data) bUsed = IsUsedSlanch(hItem);
	else if (WORK_SLANfr_LST == Data) bUsed = IsUsedSlanfr(hItem);
	else if (WORK_SLANop_LST == Data) bUsed = IsUsedSlanop(hItem);
	else if (WORK_MVHL_LST == Data)
	{
		// 코드에 따른 방식으로 수정 
		T_MVCD_D DataMvcd;
		if (!CDBDoc::GetDocPoint()->m_pAttrCtrl->GetMvcd(DataMvcd)) DataMvcd.Initialize();
		switch (DataMvcd.nCodeType)
		{
		case D_MOVE_CODE_NONE:
		case D_MOVE_CODE_JAPAN:
			break;
		case D_MOVE_CODE_AASHTO_STAN:
		case D_MOVE_CODE_AASHTO_LRFD:
		case D_MOVE_CODE_PENDOT:
		case D_MOVE_CODE_TAIWAN:
		case D_MOVE_CODE_KOREA:
		case D_MOVE_CODE_CANADA:
		case D_MOVE_CODE_BS:
		case D_MOVE_CODE_EURO_BS:
		case D_MOVE_CODE_RUSSIA:
		case D_MOVE_CODE_KOREA_LRFD_2011:
		case D_MOVE_CODE_AUSTRALIA:
		case D_MOVE_CODE_POLAND:
		case D_MOVE_CODE_SOUTH_AFRICA:
		case D_MOVE_CODE_JAPAN_RAIL:
		case D_MOVE_CODE_NEWZEALAND:
		case D_MOVE_CODE_BRAZIL:
			bUsed = IsUsedMvhl(hItem, DataMvcd.nCodeType);
			break;
		case D_MOVE_CODE_CHINA:
			bUsed = IsUsedMvhlch(hItem);
			break;
		case D_MOVE_CODE_INDIA:
			bUsed = IsUsedMvhlid(hItem);
			break;
		case D_MOVE_CODE_FRANCE:
			bUsed = IsUsedMvhlfr(hItem);
			break;
		default: ASSERT(0);
			break;
		}
		/*
		if (CProduct::GetMovingType()==D_PRODUCT_MOVING_US && CProduct::IsIndia())  // India
			bUsed = IsUsedMvhlid(hItem);
		else if (CProduct::GetMovingType()==D_PRODUCT_MOVING_CH) // China
			bUsed = IsUsedMvhlch(hItem);
		else
			bUsed = IsUsedMvhl(hItem);
			*/
	}
	else if (WORK_MVHLtr_LST == Data)
	{
		bUsed = IsUsedMvhltr(hItem);
	}
	else if (WORK_MVHC_LST == Data)
	{
		// 코드에 따른 방식으로 수정 
		T_MVCD_D DataMvcd;
		if (!CDBDoc::GetDocPoint()->m_pAttrCtrl->GetMvcd(DataMvcd)) DataMvcd.Initialize();
		switch (DataMvcd.nCodeType)
		{
		case D_MOVE_CODE_NONE:
			break;
		case D_MOVE_CODE_AASHTO_STAN:
		case D_MOVE_CODE_AASHTO_LRFD:
		case D_MOVE_CODE_PENDOT:
		case D_MOVE_CODE_TAIWAN:
		case D_MOVE_CODE_KOREA:
		case D_MOVE_CODE_CANADA:
		case D_MOVE_CODE_KOREA_LRFD_2011:
		case D_MOVE_CODE_AUSTRALIA:
		case D_MOVE_CODE_RUSSIA:
		case D_MOVE_CODE_POLAND:
		case D_MOVE_CODE_SOUTH_AFRICA:
		case D_MOVE_CODE_NEWZEALAND:
		case D_MOVE_CODE_BRAZIL:
			bUsed = IsUsedMvhc(hItem);
			break;
		case D_MOVE_CODE_CHINA:
			bUsed = IsUsedMvhcch(hItem);
			break;
		case D_MOVE_CODE_JAPAN:
		case D_MOVE_CODE_INDIA:
		case D_MOVE_CODE_BS:
		case D_MOVE_CODE_JAPAN_RAIL:
			break;
		default:
			ASSERT(0);
			break;
		}
		/*
		if (CProduct::GetMovingType() == D_PRODUCT_MOVING_ORG)
			bUsed = IsUsedMvhc(hItem);
		else if (CProduct::GetMovingType() == D_PRODUCT_MOVING_CH)
			bUsed = IsUsedMvhcch(hItem);
			*/
	}
	else if (WORK_SMPT_LST == Data) bUsed = IsUsedSmpt(hItem);
	else if (WORK_TDMT_LST == Data) bUsed = IsUsedTdmt(hItem);
	else if (WORK_TDME_LST == Data) bUsed = IsUsedTdme(hItem);
	else if (WORK_TDMF_LST == Data) bUsed = IsUsedTdmf(hItem);
	else if (WORK_TDNT_LST == Data) bUsed = IsUsedTdnt(hItem);
	else if (WORK_NLLP_LST == Data) bUsed = IsUsedNllp(hItem);
	else if (WORK_EPMT_LST == Data) bUsed = IsUsedEpmt(hItem);
	else if (WORK_FIMP_LST == Data) bUsed = IsUsedFimp(hItem);
	else if (WORK_FIBR_LST == Data) bUsed = IsUsedFibr(hItem);
	else if (WORK_FIBW_LST == Data) bUsed = IsUsedFibw(hItem);
	else if (WORK_IEHP_LST == Data) bUsed = IsUsedIehp(hItem);
	else if (WORK_HNGT_LST == Data) bUsed = IsUsedPhgt(hItem);
	else if (WORK_DIMM_LST == Data) bUsed = IsUsedDimm(hItem);
	else if (WORK_REBB_LST == Data) bUsed = IsUsedRebb(hItem);
	else if (WORK_REBC_LST == Data) bUsed = IsUsedRebc(hItem);
	else if (WORK_REBR_LST == Data) bUsed = IsUsedRebr(hItem);
	else if (WORK_REBW_LST == Data) bUsed = IsUsedRebw(hItem);
	else if (WORK_RBMS_LST == Data) bUsed = IsUsedRbms(hItem);
	else if (WORK_RBSL_LST == Data) bUsed = IsUsedRbsl(hItem);
	else if (WORK_RBMW_LST == Data) bUsed = IsUsedRbmw(hItem);
	else if (WORK_RBST_LST == Data) bUsed = IsUsedRbst(hItem);
	else if (WORK_RIPB_LST == Data) bUsed = IsUsedRipb(hItem);
	else if (WORK_RIPC_LST == Data) bUsed = IsUsedRipc(hItem);
	else if (WORK_PREB_LST == Data) bUsed = IsUsedPreb(hItem);
	else if (WORK_PRCS_LST == Data) bUsed = IsUsedPrcs(hItem);
	else if (WORK_DPAN_LST == Data) bUsed = IsUsedDpan(hItem);
	else if (WORK_CCPT_LST == Data) bUsed = IsUsedCcpt(hItem);
	else if (WORK_MSIS_LST == Data) bUsed = IsUsedMsis(hItem);
	else if (WORK_SDVI_LST == Data) bUsed = IsUsedSdvi(hItem);
	else if (WORK_SDVE_LST == Data) bUsed = IsUsedSdve(hItem);
	else if (WORK_SDST_LST == Data) bUsed = IsUsedSdst(hItem);
	else if (WORK_SDHY_LST == Data) bUsed = IsUsedSdhy(hItem);
	else if (WORK_SDIS_LST == Data) bUsed = IsUsedSdis(hItem);
	else if (WORK_ASGB_LST == Data) bUsed = IsUsedAsgb(hItem);
	else if (WORK_DMGB_LST == Data) bUsed = IsUsedDmgb(hItem);
	else if (WORK_FIMP_PO_LST == Data) bUsed = IsUsedFimp_PO(hItem);
	else if (WORK_FIBR_PO_LST == Data) bUsed = IsUsedFibr_PO(hItem);
	else if (WORK_FIBW_PO_LST == Data) bUsed = IsUsedFibw_PO(hItem);
	else if (WORK_MHTP_LST == Data) bUsed = IsUsedMhtp(hItem);
	else if (WORK_RFST_LST == Data)	bUsed = IsUsedRfst(hItem);
	// analysis Option 에 관한 것들         // PMS:3976-JWKWON-20090710 : 8월에 작업할 예정(우선 주석처리함)
//   else if (Data == WORK_PDEL_FLD || Data == WORK_BUCK_FLD || Data == WORK_EIGV_FLD || Data == WORK_HHCT_FLD ||  // PDelta, Buckling, Eigen, Heat of hydration
//            Data == WORK_NLCT_FLD || Data == WORK_STCT_FLD || Data == WORK_BCCT_FLD || Data == WORK_PLCB_FLD ||  // Nonlinear, Construction Stage, Boundary change, Composite Section
//            Data == WORK_MVCT_FLD || Data == WORK_SBCT_FLD ||                                                    // Moving Load, Suspension Bridge
//            Data == WORK_SPEC_FLD || Data == WORK_STTL_FLD || Data == WORK_CRAN_FLD ||Data == WORK_THISANL_FLD ||// Response Spec, Settlement, Crane Load, Time History
//            Data == WORK_MVLDANLjp_FLD || Data == WORK_MVLDANLch_FLD || Data == WORK_MVLDANLid_FLD ||Data == WORK_MVLDANLtr_FLD
//            ) 
//            bUsed = IsUsedAcop(Data);

	if (bUsed == 1)  m_ColorData.m_clrText = RGB(0, 0, 0);
	else if (bUsed == 0)  m_ColorData.m_clrText = RGB(0, 0, 255);
	else if (bUsed == -1)  m_ColorData.m_clrText = RGB(255, 0, 0);
	else ASSERT(0);

	return TRUE;
}


void CTreeWorkCtrl::OnKeyDown(UINT nChar, UINT nRepCnt, UINT nFlags)
{
	if (nChar == VK_DELETE)
	{
		OnWorktreeDelete();
	}

	MBaseTreeCtrl::OnKeyDown(nChar, nRepCnt, nFlags);
}

