void CTreeWorkCtrl::DisappearGridAnalModel(HTREEITEM ht)
{
	GDisplaySetting dspOpt;
	ExportDisplaySetting::GET(&dspOpt);

	UINT data = GetItemData(ht);
	switch (data)
	{
	case WORK_MGDR_LST: dspOpt.m_Load.bMGDR = FALSE; break;
	case WORK_CBEM_LST: dspOpt.m_Load.bCBEM = FALSE; break;
	case WORK_LDLN_LST: dspOpt.m_Load.bLDLN = FALSE; break;
	case WORK_GILC_LST: dspOpt.m_Load.bGILD = FALSE; break;
	case WORK_BSPN_LST: dspOpt.m_Load.bBSPN = FALSE; break;
	case WORK_GIMP_LST: dspOpt.m_Load.bGIMP = FALSE; break;
	case WORK_GSTY_LST: dspOpt.m_Load.bGSTY = FALSE; break;
	case WORK_P1LA_LST: dspOpt.m_Load.bP1LA = FALSE; break;
	case WORK_LNKF_LST:
	{
		dspOpt.m_Load.bLNKF_ELNK = FALSE;
		dspOpt.m_Load.bLNKF_NLNK = FALSE;
	}
	break;
	case WORK_GMAS_LST: dspOpt.m_Load.bGMAS = FALSE; break;
	}

	ExportDisplaySetting::SET(&dspOpt);
}

