void CTreeWorkCtrl::DisappearHydration(HTREEITEM ht)
{
	UINT data = GetItemData(ht);
	// Display Option Setting
	GDisplaySetting dspOpt;
	ExportDisplaySetting::GET(&dspOpt);

	if (data == WORK_HECB_LST)
	{
		CArray<T_HECB_K, T_HECB_K> aKey;
		CArray<UINT, UINT> aKeymap;
		GetSelectedHecbKeyListWithMultiTreeItemSelect(aKey);
		aKeymap.SetSize(aKey.GetSize());
		for (int i = 0; i < aKey.GetSize(); i++)
			aKeymap[i] = aKey[i].keymap;
		ExportDisplaySetting::SET_Dyn(UR_HECB_DEL, LT_HECB_CMD, aKeymap);
		return;
	}
	else if (data == WORK_HSPT_LST) { dspOpt.m_Bndr.bSpecTemperature = FALSE; dspOpt.m_Bndr.bSpecTemperatureTxt = FALSE; }
	else if (data == WORK_HSFC_LST) { dspOpt.m_Bndr.bHeatSource = FALSE; dspOpt.m_Bndr.bHeatSourceTxt = FALSE; }
	else if (data == WORK_HPCE_LST) { dspOpt.m_Bndr.bPipeCoolingElem = FALSE; dspOpt.m_Bndr.bPipeCoolingElemTxt = FALSE; }

	ExportDisplaySetting::SET(&dspOpt);
}


