void CTreeWorkCtrl::DisappearBoundaries(HTREEITEM ht)
{
	UINT data = GetItemData(ht);
	// Display Option Setting
	//GDisplaySetting *dspOpt = ExportDisplaySetting::GET();
	GDisplaySetting dspOpt;
	ExportDisplaySetting::GET(&dspOpt);

	if (data == WORK_CONS_LST)  dspOpt.m_Bndr.bCons = FALSE;
	else if (data == WORK_NSPR_LIN_LST) dspOpt.m_Bndr.bNspr = FALSE;
	else if (data == WORK_NSPR_NON_LST) dspOpt.m_Bndr.bNsprNon = FALSE;
	else if (data == WORK_NSPR_MLT_LST) dspOpt.m_Bndr.bNsprMulti = FALSE;
	else if (data == WORK_GSTP_LST) dspOpt.m_Bndr.bGspr = FALSE;
	else if (data == WORK_SSPS_LIN_LST) dspOpt.m_Bndr.bSspsLin = FALSE;
	else if (data == WORK_SSPS_NON_LST) dspOpt.m_Bndr.bSspsNon = FALSE;
	else if (data == WORK_DRLS_FLD) dspOpt.m_Bndr.bDiaDiscon = FALSE;
	else if (data == WORK_FRLS_LST) { dspOpt.m_Bndr.bFrls = FALSE; dspOpt.m_Bndr.bFrlsSym = FALSE; }
	else if (data == WORK_OFFS_LST) { dspOpt.m_Bndr.bOffs = FALSE; dspOpt.m_Bndr.bOffs = FALSE; dspOpt.m_Bndr.bOffs = FALSE; }
	else if (data == WORK_PRLS_LST) dspOpt.m_Bndr.bPlateEndR = FALSE;
	else if (data == WORK_RIGD_LST) dspOpt.m_Bndr.bRigd = FALSE;
	else if (data == WORK_MCON_LST) dspOpt.m_Bndr.bMcon = FALSE; // MNET:2790-JHLEE-20070911
	else if (data == WORK_ELNK_FLD) { dspOpt.m_Bndr.bElasticLink = FALSE; dspOpt.m_Bndr.bElasticLinkAxis = FALSE; }
	else if (data == WORK_SKEW_LST) dspOpt.m_Node.bSkew = FALSE;
	else if (data == WORK_NLNK_LST)
	{
		dspOpt.m_Bndr.bNonlinearLink = FALSE;
		dspOpt.m_Bndr.bNonlinearLinkNo = FALSE;
	}
	else if (data == WORK_IEHG_LST) { dspOpt.m_Bndr.bInelasticHingeSymbol = FALSE; dspOpt.m_Bndr.bInelasticHingeName = FALSE; }
	else if (data == WORK_BCCT_LST) // MNET1199, KJH20050217
	{
		CArray<T_BNGR_K, T_BNGR_K> aTemp, aBngrK;
		CString strSel(_T(""));
		GetSelectedBcctBngrKeyListWithMultiTreeItemSelect(aTemp, strSel);

		int nSize = dspOpt.m_Bndr.m_GroupKeys.GetSize();
		if (nSize > 0)
		{
			BOOL bTmp = TRUE;
			CMap<T_BNGR_K, T_BNGR_K, BOOL, BOOL> mTmp;
			for (int i = 0; i < nSize; i++) mTmp.SetAt(dspOpt.m_Bndr.m_GroupKeys[i], bTmp);
			for (int i = 0; i < aTemp.GetSize(); i++) if (mTmp.Lookup(aTemp[i], bTmp))
				mTmp.RemoveKey(aTemp[i]);
			POSITION pos = mTmp.GetStartPosition();
			while (pos)
			{
				T_BNGR_K key;
				mTmp.GetNextAssoc(pos, key, bTmp);
				aBngrK.Add(key);
			}
			qsort(aBngrK.GetData(), aBngrK.GetSize(), sizeof(UINT), CCompFunc::UINTAsc);
			dspOpt.m_Bndr.bAllGroup = FALSE;
			dspOpt.m_Bndr.m_GroupKeys.Copy(aBngrK);
		}

		if (strSel[0] == '1') dspOpt.m_Bndr.bCons = nSize > 0; // Support
		if (strSel[1] == '1') dspOpt.m_Bndr.bNspr = nSize > 0; // Point Spring
		if (strSel[2] == '1') dspOpt.m_Bndr.bGspr = nSize > 0; // General Spring
		if (strSel[3] == '1')                                // Change General Link Property, 신규추가
		{
			dspOpt.m_Bndr.bCGLP = nSize > 0;
		}
		if (strSel[6] == '1') //Beam End Release - // MNET:XXXX-JUAE-20070727
		{
			if (nSize > 0)
			{
				dspOpt.m_Bndr.bFrls = TRUE;
			}
		}
	}
	else if (data == WORK_CRAN_LST || data == WORK_CRAN_FLD)
	{
		dspOpt.m_Bndr.bCraneLane = FALSE;
		dspOpt.m_Bndr.bCraneName = FALSE;
	}

	ExportDisplaySetting::SET(&dspOpt);
}

void CTreeWorkCtrl::DisappearDynamicLoad(HTREEITEM ht)
{
	UINT data = GetItemData(ht);

	HTREEITEM prvHt, curHt = ht;
	int pos = 0;
	BOOL bSuccess = FALSE;
	for (prvHt = curHt; prvHt != NULL; curHt = prvHt, pos++) prvHt = GetPrevSiblingItemWithoutFilter(curHt);

	GDisplaySetting dspOpt;
	ExportDisplaySetting::GET(&dspOpt);

	dspOpt.m_Load.SetDefault();
	dspOpt.m_Load.nOption = 1;
	dspOpt.m_Load.bTxtAll = TRUE;
	dspOpt.m_Load.nLoadCaseType = D_LOADCASE_HISTORY;

	if (data == WORK_THNL_LST)
	{
		dspOpt.m_Load.nLoadCase = m_aThnlInfo[pos - 1].LoadCaseKey;
		dspOpt.m_Load.bDynNodalLoad = FALSE;
	}
	else if (data == WORK_THMS_LST)
	{
		dspOpt.m_Load.nLoadCase = m_aThmsInfo[pos - 1].ThisKey;
		dspOpt.m_Load.bTHMS = FALSE;
	}

	ExportDisplaySetting::SET(&dspOpt);
}

void CTreeWorkCtrl::DisappearStaticLoad(HTREEITEM ht, BOOL fg)
{
	CDBDoc* pDoc = (CDBDoc*)CTreeMenuBarBase::GetDocST();
	if (!pDoc)
	{
		TRACE(_LS(IDS_TMWK__MSG1));
		return;
	}

	if (fg) // 아이템이 하중 종류인 경우
	{
		// 선택한 아이템을 포함하는 하중 조건 찾기
		UINT data = GetItemData(ht);
		if (data == WORK_RPSC_LST) // 특별처리-이게 왜 여기 있을까?
		{
			GDisplaySetting dspOpt;
			ExportDisplaySetting::GET(&dspOpt);
			dspOpt.m_Load.bRPSC = FALSE;
			ExportDisplaySetting::SET(&dspOpt);
			return;
		}

		HTREEITEM parentItem = GetParentItem(ht);
		HTREEITEM prvHt;
		int pos = 0;
		BOOL bSuccess = FALSE;
		for (prvHt = parentItem; prvHt != NULL; parentItem = prvHt, pos++) prvHt = GetPrevSiblingItemWithoutFilter(parentItem);
		CArray<T_STLD_K, T_STLD_K> aStldKeyList;
		pDoc->m_pAttrCtrl->GetStldKeyList(aStldKeyList);

		// Display Option Setting
		//GDisplaySetting *dspOpt = ExportDisplaySetting::GET();
		GDisplaySetting dspOpt;
		ExportDisplaySetting::GET(&dspOpt);

		if (data == WORK_CNLD_FLD)  dspOpt.m_Load.bCnld = FALSE;
		else if (data == WORK_SDSP_FLD) dspOpt.m_Load.bDisplacement = FALSE;
		else if (data == WORK_BMLD_ELEM_FLD || data == WORK_BMLD_LINE_FLD || data == WORK_BMLD_TYPC_FLD || data == WORK_BMLD_FLOR_FLD) dspOpt.m_Load.bBmld = FALSE;
		else if (data == WORK_PRST_FLD) dspOpt.m_Load.bPrestress = FALSE;
		else if (data == WORK_PTNS_FLD) dspOpt.m_Load.bPretention = FALSE;
		else if (data == WORK_FBLA_FLD) dspOpt.m_Load.bFbld = FALSE;
		else if (data == WORK_PNLA_FLD) dspOpt.m_Load.bPlaneLoad = FALSE;
		else if (data == WORK_PRES_FLD) dspOpt.m_Load.bPres = FALSE;
		else if (data == WORK_ARPR_FLD) dspOpt.m_Load.bArpr = FALSE;
		else if (data == WORK_NTMP_FLD) dspOpt.m_Load.bNodalTemp = FALSE;
		else if (data == WORK_ETMP_FLD) dspOpt.m_Load.bElemTemp = FALSE;
		else if (data == WORK_GTMP_FLD) dspOpt.m_Load.bTempGradiant = FALSE;
		else if (data == WORK_WIND_FLD) dspOpt.m_Load.bWind = FALSE;
		else if (data == WORK_WIND_WA_WT_FLD) dspOpt.m_Load.bWind = FALSE;
		else if (data == WORK_SEIS_FLD) dspOpt.m_Load.bSeismic = FALSE;
		else if (data == WORK_SSEI_FLD) dspOpt.m_Load.bSSEI = FALSE;
		else if (data == WORK_TDPL_FLD) dspOpt.m_Load.bTendonPrestress = FALSE;
		else if (data == WORK_FMLD_FLD) dspOpt.m_Load.bFMLD = FALSE;
		else if (data == WORK_FIPA_FLD) dspOpt.m_Load.bFireFipa = FALSE;
		else if (data == WORK_FSSF_FLD) dspOpt.m_Load.bFireFssf = FALSE;
		else if (data == WORK_BTMP_FLD) dspOpt.m_Load.bBTMP = FALSE;
		else if (data == WORK_PTMP_FLD) dspOpt.m_Load.bPTMP = FALSE;
		else if (data == WORK_WDPR_AREA_FLD)  dspOpt.m_Load.bWindPArea = FALSE;
		else if (data == WORK_WDPR_BEAM_FLD)  dspOpt.m_Load.bWindPBeam = FALSE;
		else if (data == WORK_WDPR_NODAL_FLD) dspOpt.m_Load.bWindPNodal = FALSE;
		else if (data == WORK_WDPR_FUNC_FLD)  dspOpt.m_Load.bWindPFunc = FALSE;
		else if (data == WORK_EPST_FLD)  dspOpt.m_Load.bEpst = FALSE;
		else if (data == WORK_EPSE_FLD)  dspOpt.m_Load.bEpse = FALSE;
		else if (data == ID_MAIN_RIBBON_SEISEVAL_PSEUDO_FORCE) dspOpt.m_Load.bPseudoSeismic = FALSE;

		ExportDisplaySetting::SET(&dspOpt);
	}
	else  // 아이템의 하중 조건인 경우
	{
		// 선택한 아이템이 나타내는 하중 조건 찾기

		HTREEITEM parentItem = ht, prvHt;
		int pos = 0;
		for (prvHt = parentItem; prvHt != NULL; parentItem = prvHt, pos++) prvHt = GetPrevSiblingItemWithoutFilter(parentItem);
		CArray<T_STLD_K, T_STLD_K> aStldKeyList;
		pDoc->m_pAttrCtrl->GetStldKeyList(aStldKeyList);

		// Display Option Setting
		//GDisplaySetting *dspOpt = ExportDisplaySetting::GET();
		GDisplaySetting dspOpt;
		ExportDisplaySetting::GET(&dspOpt);
		//dspOpt.m_Load.SetDefault(); // 
		dspOpt.m_Load.nOption = 1;
		dspOpt.m_Load.nLoadCase = aStldKeyList[pos - 1];
		dspOpt.m_Load.bAllGroup = TRUE;
		dspOpt.m_Load.nLoadCaseIndex = pos;
		dspOpt.m_Load.bTxtAll = FALSE;
		dspOpt.m_Load.bCnld = FALSE;
		dspOpt.m_Load.bDisplacement = FALSE;
		dspOpt.m_Load.bBmld = FALSE;
		dspOpt.m_Load.bPrestress = FALSE;
		dspOpt.m_Load.bPretention = FALSE;
		dspOpt.m_Load.bFbld = FALSE;
		dspOpt.m_Load.bPlaneLoad = FALSE;
		dspOpt.m_Load.bPres = FALSE;
		dspOpt.m_Load.bArpr = FALSE;
		dspOpt.m_Load.bNodalTemp = FALSE;
		dspOpt.m_Load.bElemTemp = FALSE;
		dspOpt.m_Load.bTendonPrestress = FALSE;
		dspOpt.m_Load.bTempGradiant = FALSE;
		dspOpt.m_Load.bWind = FALSE;
		dspOpt.m_Load.bSeismic = FALSE;
		dspOpt.m_Load.bFireFipa = FALSE;
		dspOpt.m_Load.bFireFssf = FALSE;
		ExportDisplaySetting::SET(&dspOpt);
	}
}

