void CTreeWorkCtrl::OnWorktreeEnable()
{
	CArray<HTREEITEM, HTREEITEM> aItem;
	int selItemNum = GetSelectedItemList(aItem);
	if (selItemNum == 0) return;
	UINT Data = GetItemData(aItem[0]);

	CDBDoc* pDoc = CDBDoc::GetDocPoint();
	if (!pDoc)
	{
		TRACE(_LS(IDS_TMWK__MSG1));
		return;
	}

	T_ACOP_D AcopD;
	pDoc->m_pAttrCtrl->GetAcop(AcopD);
	if (Data == WORK_PDEL_FLD)  pDoc->m_pDataCtrl->AcopEnableType(D_ACOP_PDEL);   // P-Delta 
	else if (Data == WORK_BUCK_FLD)  pDoc->m_pDataCtrl->AcopEnableType(D_ACOP_BUCK);   // Buckling
	else if (Data == WORK_EIGV_FLD)  pDoc->m_pDataCtrl->AcopEnableType(D_ACOP_EIGE);   // Eigenvalue
	else if (Data == WORK_HHCT_FLD)  pDoc->m_pDataCtrl->AcopEnableType(D_ACOP_HEAT);   // Heat of Hydration
	else if (Data == WORK_NLCT_FLD)  pDoc->m_pDataCtrl->AcopEnableType(D_ACOP_NONL);   // Nonlinear
	else if (Data == WORK_NLCT_LST)  pDoc->m_pDataCtrl->AcopEnableType(D_ACOP_NONL);   // Nonlinear
	else if (Data == WORK_STCT_FLD)  pDoc->m_pDataCtrl->AcopEnableType(D_ACOP_CONS);   // Construction Stage
	else if (Data == WORK_BCCT_FLD)  pDoc->m_pDataCtrl->AcopEnableType(D_ACOP_BOUN);   // Boundary Change Assignment to loacCase/Analysis
	else if (Data == WORK_SPEC_FLD)  pDoc->m_pDataCtrl->AcopEnableType(D_ACOP_RESP);   // Response Spectrum 
	else if (Data == WORK_MVCT_FLD)  pDoc->m_pDataCtrl->AcopEnableType(D_ACOP_MOVI);   // Moving Load
	else if (Data == WORK_SBCT_FLD)  pDoc->m_pDataCtrl->AcopEnableType(D_ACOP_SUSP);   // Suspension Bridge
	else if (Data == WORK_STTL_FLD)  pDoc->m_pDataCtrl->AcopEnableType(D_ACOP_SETT);   // Settlement
	else if (Data == WORK_CRANELOAD_FLD)  pDoc->m_pDataCtrl->AcopEnableType(D_ACOP_CRAN);   // Crane Load
	else if (Data == WORK_PLCB_FLD)  pDoc->m_pDataCtrl->AcopEnableType(D_ACOP_COMP);   // Composite Section
	else if (Data == WORK_THISANL_FLD)  pDoc->m_pDataCtrl->AcopEnableType(D_ACOP_TIME);   // Time History

}
void CTreeWorkCtrl::OnWorktreeDisable()
{
	CArray<HTREEITEM, HTREEITEM> aItem;
	int selItemNum = GetSelectedItemList(aItem);
	if (selItemNum == 0) return;
	UINT Data = GetItemData(aItem[0]);

	CDBDoc* pDoc = CDBDoc::GetDocPoint();
	if (!pDoc)
	{
		TRACE(_LS(IDS_TMWK__MSG1));
		return;
	}

	T_ACOP_D AcopD;
	pDoc->m_pAttrCtrl->GetAcop(AcopD);
	if (Data == WORK_PDEL_FLD)  AcopD.bPDelta = FALSE;
	else if (Data == WORK_BUCK_FLD)  AcopD.bBuckling = FALSE;
	else if (Data == WORK_EIGV_FLD)  AcopD.bEigen = FALSE;
	else if (Data == WORK_HHCT_FLD)  AcopD.bHeatHydra = FALSE;
	else if (Data == WORK_NLCT_FLD)  AcopD.bNonlinear = FALSE;
	else if (Data == WORK_NLCT_LST)  AcopD.bNonlinear = FALSE;
	else if (Data == WORK_STCT_FLD)  AcopD.bConstStage = FALSE;
	else if (Data == WORK_BCCT_FLD)  AcopD.bBoundChange = FALSE;
	else if (Data == WORK_SPEC_FLD)  AcopD.bResSpec = FALSE;
	else if (Data == WORK_MVCT_FLD)  AcopD.bMovingLoad = FALSE;
	else if (Data == WORK_SBCT_FLD)  AcopD.bSuspension = FALSE;
	else if (Data == WORK_STTL_FLD)  AcopD.bSettle = FALSE;
	else if (Data == WORK_CRANELOAD_FLD)  AcopD.bCraneLoad = FALSE;
	else if (Data == WORK_PLCB_FLD)  AcopD.bComposSect = FALSE;
	else if (Data == WORK_THISANL_FLD)  AcopD.bTimeHist = FALSE;

	pDoc->m_pDataCtrl->AddAcop(AcopD);
}

