void CTreeWorkCtrl::SetDimensionDisplayText(BOOL bShow)
{
	CDBDoc* pDoc = (CDBDoc*)CTreeMenuBarBase::GetDocST();
	T_DIMM_D DimmD;
	CString tStr;
	CString strOnOff;
	if (bShow)
		strOnOff = _LS(IDS_TM_WORK__On);
	else
		strOnOff = _LS(IDS_TM_WORK__Off);

	CArray<HTREEITEM, HTREEITEM> aItem;
	int selItemNum = GetSelectedItemList(aItem);

	HTREEITEM prvHt, ht1, nxtHt;
	int pos = 0, nSt = 0;
	ht1 = aItem[0];

	CArray<T_DIMM_K, T_DIMM_K> akey;
	pDoc->m_pAttrCtrl->GetDimmKeyList(akey);

	for (prvHt = ht1;;) { prvHt = GetPrevSiblingItemWithoutFilter(ht1); if (prvHt == NULL) break; ht1 = prvHt; }
	for (nxtHt = ht1; nxtHt != NULL; ht1 = nxtHt, pos++)
	{
		for (int i = nSt; i < aItem.GetSize(); i++)
		{
			if (ht1 == aItem[i])
			{
				DimmD.Initialize();
				pDoc->m_pAttrCtrl->GetDimm(akey[pos], DimmD);
				tStr.Format(_T("%s%s"), DimmD.strName, strOnOff);
				SetItemText(ht1, tStr);
				nSt += 1;
			}
		}
		nxtHt = GetNextSiblingItemWithoutFilter(ht1);
	}
}

void CTreeWorkCtrl::SetTracingAndLineGridDisplayText(bool bShow)
{
	CDBDoc* pDoc = (CDBDoc*)CTreeMenuBarBase::GetDocST();
	T_STOR_D StorD;
	CString tStr;
	CString strOnOff;
	if (bShow)
		strOnOff = _LS(IDS_TM_WORK__On);
	else
		strOnOff = _LS(IDS_TM_WORK__Off);

	CArray<HTREEITEM, HTREEITEM> aItem;
	int selItemNum = GetSelectedItemList(aItem);

	const int idx = selItemNum - 1;
	if (GetItemData(aItem[idx]) == WORK_STOR_FLD)
	{
		HTREEITEM hChildItem = GetChildItem(aItem[idx]);
		HTREEITEM hNextItem = NULL;
		aItem.RemoveAll();
		while (hChildItem != NULL)
		{
			hNextItem = GetNextSiblingItemWithoutFilter(hChildItem);
			aItem.Add(hChildItem);
			hChildItem = hNextItem;
		}
	}

	HTREEITEM prvHt, ht1, nxtHt;
	int pos = 0, nSt = 0;
	ht1 = aItem[0];

	CArray<T_STOR_K, T_STOR_K> akey;
	pDoc->m_pAttrCtrl->GetStorKeyList(akey);

	for (prvHt = ht1;;) { prvHt = GetPrevSiblingItemWithoutFilter(ht1); if (prvHt == NULL) break; ht1 = prvHt; }
	for (nxtHt = ht1; nxtHt != NULL; ht1 = nxtHt, pos++)
	{
		for (int i = nSt; i < aItem.GetSize(); i++)
		{
			if (ht1 == aItem[i])
			{
				CString strStorName = pDoc->m_pAttrCtrl->GetStorNameWithModuleName(akey[pos]);

				StorD.Initialize();
				pDoc->m_pAttrCtrl->GetStor(akey[pos], StorD);
				
				T_TDAS_D tdasData;
				tStr = strStorName;

				const auto hasTdas = pDoc->m_pAttrCtrl2->GetTdas(StorD.TdasK, tdasData);
				const auto hasLineGrid = CStorSubData::GetInstance().HasStorKeyForLineGrid(akey[pos]);
				if (hasTdas)
				{
					tStr += _T("[") + tdasData.strName + _T("]");
				}

				if (hasLineGrid)
				{
					tStr += _T(" (") + _LS(IDS_TM_Line_Grid) + _T(")");
				}

				if (hasTdas || hasLineGrid)
				{
					const auto showTdas = I_GENModelBase::GetCurMySelfST()->IsCurShowTracingStoryKey(akey[pos]);
					const auto showLineGrid = I_GENModelBase::GetCurMySelfST()->IsCurShowLineGridStoryKey(akey[pos]);
					if (showTdas || showLineGrid)
					{
						tStr += _LS(IDS_TM_WORK__On);
					}
					else
					{
						tStr += _LS(IDS_TM_WORK__Off);
					}
				}

				SetItemText(ht1, tStr);
				nSt += 1;
			}
		}
		nxtHt = GetNextSiblingItemWithoutFilter(ht1);
	}
}

BOOL CTreeWorkCtrl::GetSelectedRbmsKey(HTREEITEM& curHt, int pos, T_RBMS_K& RbmsK)
{
	HTREEITEM parentItem = GetParentItem(curHt);
	UINT parentData = GetItemData(parentItem);

	int nLayer;
	if (parentData == WORK_RBMS_T1_FLD) nLayer = 0;
	else if (parentData == WORK_RBMS_B1_FLD) nLayer = 1;
	else if (parentData == WORK_RBMS_T2_FLD) nLayer = 2;
	else if (parentData == WORK_RBMS_B2_FLD) nLayer = 3;
	else { ASSERT(0); return FALSE; }

	CDBDoc* pDoc = CDBDoc::GetDocPoint();
	CArray<T_RBMS_K, T_RBMS_K> aRbmsK;
	pDoc->m_pAttrCtrl->GetRbmsKeyList(aRbmsK, nLayer);

	int nRbmsSize = aRbmsK.GetSize();
	if (pos > nRbmsSize) { return FALSE; }

	RbmsK = aRbmsK[pos - 1];
	return TRUE;
}

BOOL CTreeWorkCtrl::GetSelectedRbslKey(HTREEITEM& curHt, int pos, T_RBSL_K& RbslK)
{
	HTREEITEM parentItem = GetParentItem(curHt);
	UINT parentData = GetItemData(parentItem);

	int nLayer;
	if (parentData == WORK_RBSL_T1_FLD) nLayer = 0;
	else if (parentData == WORK_RBSL_B1_FLD) nLayer = 1;
	else if (parentData == WORK_RBSL_T2_FLD) nLayer = 2;
	else if (parentData == WORK_RBSL_B2_FLD) nLayer = 3;
	else { ASSERT(0); return FALSE; }

	CDBDoc* pDoc = CDBDoc::GetDocPoint();
	CArray<T_RBSL_K, T_RBSL_K> aRbslK;
	pDoc->m_pAttrCtrl->GetRbslKeyList(aRbslK, nLayer);

	int nRbslSize = aRbslK.GetSize();
	if (pos > nRbslSize) { return FALSE; }

	RbslK = aRbslK[pos - 1];
	return TRUE;
}

