COLORREF CTreeWorkCtrl::GetColorPalette(HTREEITEM hTreeItem)
{
	CDBDoc* pDoc = CDBDoc::GetDocPoint();
	BOOL bWireFrame = I_GENModelBase::GetCurMySelfST()->I_IsWireFrameMode();

	//HTREEITEM ht, prvHt;
	//ht = hTreeItem;
	int pos = 0;
	//for (prvHt = ht; prvHt != NULL; ht = prvHt, pos++)
	//	prvHt = GetPrevSiblingItemWithoutFilter(ht);
	GetItemIndexInSiblingItem(hTreeItem, pos);

	T_COLOR_D ColorD;
	ColorD.Initialize();

	UINT Data = GetItemData(hTreeItem);
	if (Data == WORK_MATL_LST)
	{
		T_MATL_K MatlK = m_aMatlItemKey[pos - 1];
		pDoc->m_pAttrCtrl->GetCo_m(MatlK, ColorD);

		if (bWireFrame == TRUE)
			return ColorD.WireFrame;
		else
			return ColorD.HiddenFill;
	}
	else if (Data == WORK_SECT_LST)
	{
		T_SECT_K SectK = m_aSectItemKey[pos - 1];
		pDoc->m_pAttrCtrl->GetCo_s(SectK, ColorD);

		if (bWireFrame == TRUE)
			return ColorD.WireFrame;
		else
			return ColorD.HiddenFill;

		pDoc->m_pDataCtrl->ModifyCo_s(SectK, ColorD);
	}
	else if (WORK_TRUSS_LST == Data ||
		WORK_TRTENS_LST == Data ||
		WORK_TRCOMP_LST == Data ||
		WORK_BEAM_LST == Data ||
		WORK_PLATE_LST == Data ||
		WORK_PLSTRS_LST == Data ||
		WORK_PLSTRN_LST == Data ||
		WORK_AXISYM_LST == Data ||
		WORK_SOLID_LST == Data ||
		WORK_WALL_LST == Data ||
		WORK_WALLOPEN_LST == Data ||
		WORK_CRBWALL_LST == Data)
	{
		CDispOptMgr* pDispOpt = pDoc->GetDispOpt();
		CString strKey = _T("");

		switch (Data)
		{
		case WORK_TRUSS_LST:
			if (bWireFrame == TRUE)
				strKey = _LSX(m_ElemTrussWire);
			else
				strKey = _LSX(m_ElemTrussHidd);
			break;
		case WORK_BEAM_LST:
			if (bWireFrame == TRUE)
				strKey = _LSX(m_ElemBeamWire);
			else
				strKey = _LSX(m_ElemBeamHidd);
			break;
		case WORK_PLSTRS_LST:
			if (bWireFrame == TRUE)
				strKey = _LSX(m_ElemPlaneStressWire);
			else
				strKey = _LSX(m_ElemPlaneStressHidd);
			break;
		case WORK_PLATE_LST:
			if (bWireFrame == TRUE)
				strKey = _LSX(m_ElemPlateWire);
			else
				strKey = _LSX(m_ElemPlateHidd);
			break;
		case WORK_WALL_LST:
			if (bWireFrame == TRUE)
				strKey = _LSX(m_ElemWallWire);
			else
				strKey = _LSX(m_ElemWallHidd);
			break;
		case WORK_WALLOPEN_LST:
			if (bWireFrame == TRUE)
				strKey = _LSX(m_ElemWallOpenWire);
			else
				strKey = _LSX(m_ElemWallOpenHidd);
			break;
		case WORK_PLSTRN_LST:
			if (bWireFrame == TRUE)
				strKey = _LSX(m_ElemPlaneStrainWire);
			else
				strKey = _LSX(m_ElemPlaneStrainHidd);
			break;
		case WORK_AXISYM_LST:
			if (bWireFrame == TRUE)
				strKey = _LSX(m_ElemAxisymmetricWire);
			else
				strKey = _LSX(m_ElemAxisymmetricHidd);
			break;
		case WORK_SOLID_LST:
			if (bWireFrame == TRUE)
				strKey = _LSX(m_ElemSolidWire);
			else
				strKey = _LSX(m_ElemSolidHidd);
			break;
		case WORK_TRTENS_LST:
			if (bWireFrame == TRUE)
				strKey = _LSX(m_ElemTensTrussWire);
			else
				strKey = _LSX(m_ElemTensTrussHidd);
			break;
		case WORK_TRCOMP_LST:
			if (bWireFrame == TRUE)
				strKey = _LSX(m_ElemCompTrussWire);
			else
				strKey = _LSX(m_ElemCompTrussHidd);
			break;
		//case WORK_CRBWALL_LST:
			//	if (bWireFrame == TRUE)
			//		strKey = _LSX(m_ElemCompTrussWire);
			//	else
			//		strKey = _LSX(m_ElemCompTrussHidd);
			//	break;
		default:
			break;
		}
		CDispOptColorObj* pObj = pDispOpt->GetColor(strKey);
		return pObj->m_CurVal;
	}

	return (COLORREF)-1;
}

void CTreeWorkCtrl::OnChangeColorPalette(HTREEITEM hTreeItem, COLORREF clr)
{
	CDBDoc* pDoc = CDBDoc::GetDocPoint();
	BOOL bWireFrame = I_GENModelBase::GetCurMySelfST()->I_IsWireFrameMode();

	HTREEITEM ht, prvHt;
	ht = hTreeItem;
	int pos = 0;
	for (prvHt = ht; prvHt != NULL; ht = prvHt, pos++)
		prvHt = GetPrevSiblingItemWithoutFilter(ht);

	T_COLOR_D ColorD;
	ColorD.Initialize();

	UINT Data = GetItemData(hTreeItem);
	if (Data == WORK_MATL_LST)
	{
		T_MATL_K MatlK = m_aMatlItemKey[pos - 1];
		pDoc->m_pAttrCtrl->GetCo_m(MatlK, ColorD);

		if (bWireFrame == TRUE)
			ColorD.WireFrame = clr;
		else
			ColorD.HiddenFill = clr;

		pDoc->m_pDataCtrl->ModifyCo_m(MatlK, ColorD);
	}
	else if (Data == WORK_SECT_LST)
	{
		T_SECT_K SectK = m_aSectItemKey[pos - 1];
		pDoc->m_pAttrCtrl->GetCo_s(SectK, ColorD);

		if (bWireFrame == TRUE)
			ColorD.WireFrame = clr;
		else
			ColorD.HiddenFill = clr;

		pDoc->m_pDataCtrl->ModifyCo_s(SectK, ColorD);
	}
	else if (WORK_TRUSS_LST == Data ||
		WORK_TRTENS_LST == Data ||
		WORK_TRCOMP_LST == Data ||
		WORK_BEAM_LST == Data ||
		WORK_PLATE_LST == Data ||
		WORK_PLSTRS_LST == Data ||
		WORK_PLSTRN_LST == Data ||
		WORK_AXISYM_LST == Data ||
		WORK_SOLID_LST == Data ||
		WORK_WALL_LST == Data ||
		WORK_WALLOPEN_LST == Data ||
		WORK_CRBWALL_LST == Data)
	{
		CDispOptMgr* pDispOpt = pDoc->GetDispOpt();
		CString strKey = _T("");

		switch (Data)
		{
		case WORK_TRUSS_LST:
			if (bWireFrame == TRUE)
				strKey = _LSX(m_ElemTrussWire);
			else
				strKey = _LSX(m_ElemTrussHidd);
			break;
		case WORK_BEAM_LST:
			if (bWireFrame == TRUE)
				strKey = _LSX(m_ElemBeamWire);
			else
				strKey = _LSX(m_ElemBeamHidd);
			break;
		case WORK_PLSTRS_LST:
			if (bWireFrame == TRUE)
				strKey = _LSX(m_ElemPlaneStressWire);
			else
				strKey = _LSX(m_ElemPlaneStressHidd);
			break;
		case WORK_PLATE_LST:
			if (bWireFrame == TRUE)
				strKey = _LSX(m_ElemPlateWire);
			else
				strKey = _LSX(m_ElemPlateHidd);
			break;
		case WORK_WALL_LST:
			if (bWireFrame == TRUE)
				strKey = _LSX(m_ElemWallWire);
			else
				strKey = _LSX(m_ElemWallHidd);
			break;
		case WORK_WALLOPEN_LST:
			if (bWireFrame == TRUE)
				strKey = _LSX(m_ElemWallOpenWire);
			else
				strKey = _LSX(m_ElemWallOpenHidd);
			break;
		case WORK_PLSTRN_LST:
			if (bWireFrame == TRUE)
				strKey = _LSX(m_ElemPlaneStrainWire);
			else
				strKey = _LSX(m_ElemPlaneStrainHidd);
			break;
		case WORK_AXISYM_LST:
			if (bWireFrame == TRUE)
				strKey = _LSX(m_ElemAxisymmetricWire);
			else
				strKey = _LSX(m_ElemAxisymmetricHidd);
			break;
		case WORK_SOLID_LST:
			if (bWireFrame == TRUE)
				strKey = _LSX(m_ElemSolidWire);
			else
				strKey = _LSX(m_ElemSolidHidd);
			break;
		case WORK_TRTENS_LST:
			if (bWireFrame == TRUE)
				strKey = _LSX(m_ElemTensTrussWire);
			else
				strKey = _LSX(m_ElemTensTrussHidd);
			break;
		case WORK_TRCOMP_LST:
			if (bWireFrame == TRUE)
				strKey = _LSX(m_ElemCompTrussWire);
			else
				strKey = _LSX(m_ElemCompTrussHidd);
			break;
		//case WORK_CRBWALL_LST:
			//	if (bWireFrame == TRUE)
			//		strKey = _LSX(m_ElemCompTrussWire);
			//	else
			//		strKey = _LSX(m_ElemCompTrussHidd);
			//	break;
		default:
			break;
		}
		CDispOptColorObj* pObj = pDispOpt->GetColor(strKey);
		pObj->m_CurVal = clr;
		pDispOpt->WriteToRegistry();
	}
}

void CTreeWorkCtrl::EditProperty_WindVelocity(CDBDoc* pDoc, HTREEITEM ht, UINT data, int pos)
{
	if (data == WORK_WVEP_LST)   // Pushover Hinge Property
	{
		T_WVEP_K WvepK = m_aWvepKey[pos - 1];

		if (CDBDoc::GetDocPoint()->m_pAttrCtrl2->ExistWvep(WvepK))
		{
			CCMWindPressureVelocityAddMod dlg;
			dlg.SetWvepKey(WvepK);
			dlg.DoModal();
		}
	}
}

