int CTreeWorkCtrl::GetSelectedRbstKeyListWithMultiTreeItemSelect(CArray<T_RBST_K, T_RBST_K> &aKey)
{
	CDBDoc* pDoc = (CDBDoc*)CTreeMenuBarBase::GetDocST();
	if (!pDoc)
	{
		TRACE(_LS(IDS_TMWK__MSG1));
		return FALSE;
	}

	CArray<HTREEITEM, HTREEITEM> aItem;
	int selItemNum = GetSelectedItemList(aItem);
	if (selItemNum == 0) return FALSE;

	HTREEITEM prvHt, ht, nxtHt;
	int pos = 0, nSt = 0;
	ht = aItem[0];

	HTREEITEM parentItem = GetParentItem(ht);
	UINT parentData = GetItemData(parentItem);

	int nLayer;
	if (parentData == WORK_RBST_T_FLD) nLayer = 0;
	else if (parentData == WORK_RBST_B_FLD) nLayer = 1;
	else { ASSERT(0); return FALSE; }

	// MQC 20301 워크트리에서 선택이 제대로 안되는 오류 수정
	// top, Bot 순서로 workstree에서 세팅을 하는데 key 받아갈 때는 그냥 받아가서 순서가 안맞음
	CArray<T_RBST_K, T_RBST_K> aRbstK;
	pDoc->m_pAttrCtrl2->GetRbstKeyList(aRbstK, nLayer);

	for (prvHt = ht;;) { prvHt = GetPrevSiblingItemWithoutFilter(ht); if (prvHt == NULL) break; ht = prvHt; }
	for (nxtHt = ht; nxtHt != NULL; ht = nxtHt, pos++)
	{
		for (int i = nSt; i < aItem.GetSize(); i++)
			if (ht == aItem[i]) { aKey.Add(aRbstK[pos]); nSt += 1; }
		nxtHt = GetNextSiblingItemWithoutFilter(ht);
	}
	return aKey.GetSize();
}

