BOOL CTreeWorkCtrl::GetSelectedRbstKey(HTREEITEM& curHt, int pos, T_RBST_K& RbstK)
{
	HTREEITEM parentItem = GetParentItem(curHt);
	UINT parentData = GetItemData(parentItem);

	int nLayer;
	if (parentData == WORK_RBST_T_FLD) nLayer = 0;
	else if (parentData == WORK_RBST_B_FLD) nLayer = 1;
	else { ASSERT(0); return FALSE; }

	CDBDoc* pDoc = CDBDoc::GetDocPoint();
	CArray<T_RBST_K, T_RBST_K> aRbstK;
	pDoc->m_pAttrCtrl2->GetRbstKeyList(aRbstK, nLayer);

	int nRbstSize = aRbstK.GetSize();
	if (pos > nRbstSize) { ASSERT(0); return FALSE; }

	RbstK = aRbstK[pos - 1];
	return TRUE;
}

