BOOL CTreeWorkCtrl::IsUsedSdvi(HTREEITEM hItem)
{
	CDBDoc* pDoc = CDBDoc::GetDocPoint();
	if (!pDoc)
	{
		TRACE(_LS(IDS_TMWK__MSG1));
		return FALSE;
	}

	HTREEITEM ht, prvHt;
	int pos = 0;
	ht = hItem;
	for (prvHt = ht; prvHt != NULL; ht = prvHt, pos++) prvHt = GetPrevSiblingItemWithoutFilter(ht);

	CArray<T_SDVI_K, T_SDVI_K> aSdviK;
	pDoc->m_pAttrCtrl2->GetSdviKeyList(aSdviK);
	T_SDVI_K SdviK = aSdviK[pos - 1];

	CArray<T_NLLP_K, T_NLLP_K> aNllpK;
	pDoc->m_pAttrCtrl->GetNllpKeyList(aNllpK);
	T_NLLP_D NllpD;

	CArray<T_ASGB_K, T_ASGB_K> aAsgbK;
	pDoc->m_pAttrCtrl->GetAsgbKeyList(aAsgbK);
	T_ASGB_D AsgbD;

	CArray<T_NLNK_K, T_NLNK_K> aNlnkKeyList;
	pDoc->m_pAttrCtrl->GetNlnkKeyList(aNlnkKeyList);
	CArray<T_CGLP_K, T_CGLP_K> aCglpKeyList;
	pDoc->m_pAttrCtrl->GetCglpKeyList(aCglpKeyList);

	for (int i = 0; i < aNllpK.GetSize(); i++)
	{
		T_NLLP_K NllpK = aNllpK[i];
		if (!pDoc->m_pAttrCtrl->GetNllp(NllpK, NllpD)) { ASSERT(0); return FALSE; }

		// Element Type2 이고 Viscous/Oil damper 일 때만 검사
		if (NllpD.nApplicationType != 2) continue;
		if (NllpD.nSeisType != 0)        continue;
		if (NllpD.nSeisKey != SdviK)   continue;

		// 이 General link property가 사용되고 있는 건가?
		// general link
		T_NLNK_D NlnkData;
		for (int j = 0; j < aNlnkKeyList.GetSize(); j++)
		{
			pDoc->m_pAttrCtrl->GetNlnk(aNlnkKeyList[j], NlnkData);
			if (NlnkData.PropKey == NllpK) return 1;
		}

		// change general link property
		T_CGLP_D CglpData;
		for (int j = 0; j < aCglpKeyList.GetSize(); j++)
		{
			pDoc->m_pAttrCtrl->GetCglp(aCglpKeyList[j], CglpData);
			if (CglpData.GLinkPropK == NllpK) return 1;
		}
	}

	return FALSE;
}

