// Property Item
HTREEITEM CTreeWorkCtrl::SetInelasticPropertyItemTree(CDBDoc* pDoc, BOOL bInit)
{
	InitializeTree init_tree(this);

	HTREEITEM hTI, ThTi;
	CString   tStr;
	CArray<T_IEHP_K, T_IEHP_K> aIehpKeyList;  // Inelastic Hinge Property
	CArray<T_IEHG_K, T_IEHG_K> aIehgKeyList;  // Inelastic Hinge
	CArray<T_FIMP_K, T_FIMP_K> aFimpKeyList;  // Fiber Material Property
	CArray<T_FIBR_K, T_FIBR_K> aFibrKeyList;  // Fiber Division of Section
	CArray<T_FIBW_K, T_FIBW_K> aFibwKeyList;  // Fiber Division of Section (MCPC Wall)
	CArray<T_SIHO_K, T_SIHO_K> aSihoKeyList;
	CArray<T_SIHG_K, T_SIHG_K> aSihgKeyList;
#if defined(_MEC)
	CArray<T_SIHP_K, T_SIHP_K> aSihpKeyList;
#endif

	pDoc->m_pAttrCtrl->GetIehpKeyList(aIehpKeyList);
	pDoc->m_pAttrCtrl->GetIehgKeyList(aIehgKeyList);
	pDoc->m_pAttrCtrl->GetFimpKeyList(aFimpKeyList);
	pDoc->m_pAttrCtrl->GetFibrKeyList(aFibrKeyList, D_FIBR_TYPE_IEHP);
	pDoc->m_pAttrCtrl->GetFibwKeyList(aFibwKeyList, D_FIBW_TYPE_IEHP);
	pDoc->m_pAttrCtrl->GetSihoKeyList(aSihoKeyList);
	pDoc->m_pAttrCtrl->GetSihgKeyList(aSihgKeyList);
#if defined(_MEC)
	pDoc->m_pAttrCtrl->GetSihpKeyList(aSihpKeyList);
#endif

	int nIehcCount = pDoc->m_pAttrCtrl2->ExistIehc() ? 1 : 0;
	int nIehpCount = aIehpKeyList.GetSize();
	int nIehgCount = aIehgKeyList.GetSize();
	BOOL bTHExist = (nIehcCount + nIehpCount) > 0;
	int nFimpCount = bTHExist ? aFimpKeyList.GetSize() : 0;
	int nFibrCount = aFibrKeyList.GetSize();
	int nFibwCount = aFibwKeyList.GetSize();
	int nSihoCount = aSihoKeyList.GetSize() > 0 ? 1 : 0;
	int nSihgCount = aSihgKeyList.GetSize() > 0 ? 1 : 0;
#if defined(_MEC)
	int nSihpCount = aSihpKeyList.GetSize() > 0 ? 1 : 0;
#endif


	m_aIehpItemKey.RemoveAll();
	m_aIehgInfo.RemoveAll();
	m_aFibrItemKey_TH.RemoveAll();
	m_aFibwItemKey_TH.RemoveAll();

	// === Properties 정보 표시 ===
#if defined(_MEC)
	int nTotalNum = nIehcCount + nIehpCount + nIehgCount + nFimpCount + nFibrCount + nFibwCount + nSihoCount + nSihgCount + nSihpCount;
#else
	int nTotalNum = nIehcCount + nIehpCount + nIehgCount + nFimpCount + nFibrCount + nFibwCount + nSihoCount + nSihgCount;
#endif
	hTI = SetSub1TreeItem(WORK_INEL_PROP_FLD, bInit, nTotalNum, 6);
	if (hTI == NULL) return NULL;

	// Inelastic Properties Control Data
	if (nIehcCount + nIehpCount > 0)
	{
		ThTi = InsertTreeItem(hTI, WORK_IEHC_FLD, _LS(IDS_TM_IEHC_TITLE), _T("ico24_properties_inelproperties_inelcontraldata"));
	}

	if (nIehcCount + nIehpCount > 0) // 힌지 있으면..
	{
		ThTi = InsertTreeItem(hTI, WORK_SIHO_FLD, _LS(IDS_MAIN_SIHO_ELEM), _T("ico24_properties_inelproperties_selectindlastichingeresultoutput(elements)"));
		SetItemDisplayCount(ThTi, nSihoCount);
	}

	if (pDoc->m_pAttrCtrl->GetCountNlnk() > 0) // General Link 존재하면 보여줌
	{
		ThTi = InsertTreeItem(hTI, WORK_SIHG_FLD, _LS(IDS_MAIN_SIHO_GLINK), _T("ico24_properties_inelproperties_selectindlastichingeresultoutput(generallink)"));
		SetItemDisplayCount(ThTi, nSihgCount);
	}

#if defined(_MEC)
	CArray<T_KEY, T_KEY> aIehg_PS_List;
	pDoc->m_pAttrCtrl->GetIehgObjKeyList(D_IEHG_TYPE_POINTSPRING, aIehg_PS_List);
	if (aIehg_PS_List.GetCount())
	{
		ThTi = InsertTreeItem(hTI, WORK_SIHP_FLD, _LS(IDS_MAIN_SIHO_PSSPOT), _T("ico24_properties_inelproperties_selectindlastichingeresultoutput(generallink)")); // 아이콘 개발 필요
		SetItemDisplayCount(ThTi, nSihpCount);
	}
#endif

	// Inelastic Hinge Property
	if (nIehpCount)
	{
		ThTi = InsertTreeItem(hTI, WORK_IEHP_FLD, _LS(IDS_TW_NC_INELATIC_HINGE_PROPERTIES_d), _T("ico24_properties_inelproperties_inelastichingeproperties"));
		SetItemDisplayCount(ThTi, nIehpCount);

		CString strAdd;
		CString aInteraction[] = { _LS(IDS_TW_INELATIC_NONE), _LS(IDS_TW_INELATIC_PM), _LS(IDS_TW_INELATIC_PMM), _LS(IDS_TW_INELATIC_PM_Multi) };

		for (int i = 0; i < nIehpCount; i++)
		{
			const T_IEHP_D* pIehp = pDoc->m_pAttrCtrl->GetIehpConstPtr(aIehpKeyList[i]);
			if (pIehp == nullptr) continue;
			ASSERT(pIehp->nInteractionType >= 0 && pIehp->nInteractionType <= 3);

			strAdd.Empty();
			for (int k = 0; k < 6; k++) strAdd += pIehp->cDir[k];

			// Wall-Membrane-Fiber일 때는 Mz성분은 UI에서는 미사용으로 표시. 실제 솔버에는 사용함으로 출력함.
			int nLocation = 0;
			BOOL bWallConsOut = FALSE;
			double dShearR = 0.0;
			pDoc->m_pAttrCtrl2->GetIehpFibrAutoVal(*pIehp, nLocation, bWallConsOut, dShearR);
			if (pIehp->nHingeType == D_IEHP_HTYP_WALL && (pIehp->nWallType == 0 || !bWallConsOut) && pIehp->nDefinition == 1)
			{
				strAdd.SetAt(strAdd.GetLength() - 1, '0');
			}

			if (pIehp->nHingeType == 0)  // lumped
			{
				tStr.Format(_LS(IDS_TW_INELATIC_HINGE_PROPERTIES_INFO1),
					pIehp->strName, aInteraction[pIehp->nInteractionType], strAdd);
			}
			else if (pIehp->nHingeType == 1)   // distributed
			{
				if (pIehp->nDefinition == 0)
					tStr.Format(_LS(IDS_TW_INELATIC_HINGE_PROPERTIES_INFO2),
						pIehp->strName, aInteraction[pIehp->nInteractionType], strAdd);
				else if (pIehp->nDefinition == 1)
					tStr.Format(_LS(IDS_TW_INELATIC_HINGE_PROPERTIES_INFO3), pIehp->strName, strAdd);
				else ASSERT(0);
			}
			else if (pIehp->nHingeType == 2)   // spring
			{
				tStr.Format(_LS(IDS_TW_INELATIC_HINGE_PROPERTIES_INFO4), pIehp->strName, strAdd);
			}
			else if (pIehp->nHingeType == 3)   // truss
			{
				tStr.Format(_LS(IDS_TW_INELATIC_HINGE_PROPERTIES_INFO5), pIehp->strName, strAdd);
			}
			else if (pIehp->nHingeType == 4)   // Wall
			{
				tStr.Format(_LS(IDS_TW_INELATIC_HINGE_PROPERTIES_INFO6), pIehp->strName, strAdd);
			}
			else if (pIehp->nHingeType == D_IEHP_HTYP_POINTSPRING)
			{
				tStr.Format(_LS(IDS_TW_INELATIC_HINGE_PROPERTIES_INFO7), pIehp->strName, strAdd);
			}
			else ASSERT(0);

			InsertTreeItem(ThTi, WORK_IEHP_LST, tStr, _T("ico24_properties_inelproperties_inelastichingeproperties"));
			m_aIehpItemKey.Add(aIehpKeyList[i]);
		}
	}

	// Inelastic Hinge
	if (nIehgCount)
	{
		ThTi = InsertTreeItem(hTI, WORK_IEHG_FLD, _LS(IDS_TW_NC_INELATIC_HINGES_d), _T("ico24_properties_inelproperties_assigninelastichingeproperties"));
		SetItemDisplayCount(ThTi, nIehgCount);
		T_IEHG_D IehgD;

		// Wall 타입은 층이름을 함께 표시하기 위해 미리 정보를 생성해 둔다.
		CMapEx<T_ELEM_K, T_ELEM_K, int, int> mElemK_wall;   mElemK_wall.RemoveAll();
		mElemK_wall.InitHashTable(HASHSIZEELEM);
		for (int i = 0; i < aIehgKeyList.GetSize(); ++i)
		{
			pDoc->m_pAttrCtrl->GetIehg(aIehgKeyList[i], IehgD);

			const T_IEHP_D* pIehp = pDoc->m_pAttrCtrl->GetIehpConstPtr(IehgD.IehpKey);
			if (pIehp == nullptr) continue;
			if (pIehp->nHingeType != 4) continue;  // Wall 인가?

			mElemK_wall.SetAt(aIehgKeyList[i].key.objK, 0);
		}

		CMap<T_ELEM_K, T_ELEM_K, T_STOR_K, T_STOR_K> mWallElemK2StorK;  mWallElemK2StorK.RemoveAll();
		CMap<T_STOR_K, T_STOR_K, CString, LPCTSTR> mStorK2Name;   mStorK2Name.RemoveAll();
		T_STOR_K StorK = 0;
		CString strStorName;  strStorName.Empty();
		if (mElemK_wall.GetCount() > 0)
		{
			CArray<T_ELEM_K, T_ELEM_K> aElemK_wall;
			mElemK_wall.GetKeyList(aElemK_wall);

			//CStoryData storyData(pDoc);
			CStoryData* pStoryData = pDoc->GetStoryData();
			if (!pStoryData->GetWallElemToStorMap(aElemK_wall, mWallElemK2StorK))  ASSERT(0);

			T_STOR_D StorD;
			mStorK2Name.RemoveAll();    mStorK2Name.InitHashTable(HASHSIZESTOR);
			POSITION pos = pDoc->m_pAttrCtrl->GetStartStor();
			while (pos)
			{
				pDoc->m_pAttrCtrl->GetNextStor(pos, StorK, StorD, FALSE);
				mStorK2Name.SetAt(StorK, StorD.StoryName);
			}
		}

		for (int i = 0; i < nIehgCount; i++)
		{
			pDoc->m_pAttrCtrl->GetIehg(aIehgKeyList[i], IehgD);
			const T_IEHP_D* pIehp = pDoc->m_pAttrCtrl->GetIehpConstPtr(IehgD.IehpKey);
			if (pIehp == nullptr) continue;

			CString strHingeType;
			if (pIehp->nHingeType == 0 || pIehp->nHingeType == 1)	strHingeType = _LS(IDS_TW_INELASTIC_BEAM);
			else if (pIehp->nHingeType == 2)											strHingeType = _LS(IDS_TW_INELASTIC_GENERAL_LINK);
			else if (pIehp->nHingeType == 3)											strHingeType = _LS(IDS_TW_INELASTIC_TRUSS);
			else if (pIehp->nHingeType == 4)											strHingeType = _LS(IDS_TW_INELASTIC_WALL);

			if (pIehp->nHingeType == 4)
			{
				T_ELEM_D ElemD;
				T_ELEM_K ElemK = aIehgKeyList[i];

				if (!pDoc->m_pAttrCtrl->GetElem(ElemK, ElemD)) continue;
				if (!pDoc->m_pAttrCtrl->IsWall(ElemD.eltyp))	continue;

				if (!mWallElemK2StorK.Lookup(ElemK, StorK)) StorK = 0;
				if (!mStorK2Name.Lookup(StorK, strStorName)) strStorName = _T("");

				tStr.Format(_T("%s%d_%s-%s%d_%s"), strHingeType, aIehgKeyList[i].key.objK, strStorName, _T("ID"), ElemD.nWallId, pIehp->strName);
			}
			else
			{
				tStr.Format(_T("%s%d_%s"), strHingeType, aIehgKeyList[i].key.objK, pIehp->strName);
			}

			InsertTreeItem(ThTi, WORK_IEHG_LST, tStr, _T("ico24_properties_inelproperties_assigninelastichingeproperties"));
			m_aIehgInfo.Add(IehgD);
		}
	}

	// Fiber Material Property
	if (nFimpCount)
	{
		ThTi = InsertTreeItem(hTI, WORK_FIMP_FLD, _LS(IDS_TM_NC_WORKTREE_Fiber_Material_Property_d), _T("ico24_properties_inelproperties_inelasticmaterialproperties"));
		SetItemDisplayCount(ThTi, nFimpCount);

		T_FIMP_D FimpD;
		for (int i = 0; i < nFimpCount; i++)
		{
			pDoc->m_pAttrCtrl->GetFimp(aFimpKeyList[i], FimpD);
			if (FimpD.nMaterialType == 0) // concrete
			{
				if (FimpD.nHysModelType == 0)
					tStr.Format(_LS(IDS_TM_WORKTREE_FIMP_CONC_KENTPK), FimpD.strName, FimpD.PROP.CON_KENTPK.dFc);
				else if (FimpD.nHysModelType == 1)
					tStr.Format(_LS(IDS_TM_WORKTREE_FIMP_CONC_STANJP), FimpD.strName, FimpD.PROP.CON_STANJP.dFc);
				else if (FimpD.nHysModelType == 2)
					tStr.Format(_LS(IDS_TM_WORKTREE_FIMP_CONC_ROADJP), FimpD.strName, FimpD.PROP.CON_ROADJP.dSigmack);
				else if (FimpD.nHysModelType == 3)
					tStr.Format(_LS(IDS_TM_WORKTREE_FIMP_CONC_NAGOYA), FimpD.strName, FimpD.PROP.CON_NAGOYA.dSigmack);
				else if (FimpD.nHysModelType == 4)
					tStr.Format(_LS(IDS_TM_WORKTREE_FIMP_CONC_TRILIN), FimpD.strName, FimpD.PROP.CON_TRILIN.dSigmay[0]);
				else if (FimpD.nHysModelType == 5)
					tStr.Format(_LS(IDS_TM_WORKTREE_FIMP_CONC_GBCHINA), FimpD.strName, FimpD.PROP.CON_GB1002.dFck);
				else if (FimpD.nHysModelType == 6)
					tStr.Format(_LS(IDS_TM_WORKTREE_FIMP_CONC_MANDER), FimpD.strName);
				else if (FimpD.nHysModelType == 7)
					tStr.Format(_LS(IDS_TM_WORKTREE_FIMP_CONC_ROADJP_H24), FimpD.strName, FimpD.PROP.CON_ROADJP_H24.dSigmack);
				else if (FimpD.nHysModelType == 8)
					tStr.Format(_LS(IDS_TM_WORKTREE_FIMP_CONC_GBCHINA2010), FimpD.strName, FimpD.PROP.CON_GB1010.dFcr);
			}
			else if (FimpD.nMaterialType == 1)  // steel
			{
				if (FimpD.nHysModelType == 0)
					tStr.Format(_LS(IDS_TM_WORKTREE_FIMP_STL_MENEGO), FimpD.strName, FimpD.PROP.STL_MENEGO.dFy);
				else if (FimpD.nHysModelType == 1)
					tStr.Format(_LS(IDS_TM_WORKTREE_FIMP_STL_BILINE), FimpD.strName, FimpD.PROP.STL_BILINE.dFy);
				else if (FimpD.nHysModelType == 2)
					tStr.Format(_LS(IDS_TM_WORKTREE_FIMP_STL_GENBIL), FimpD.strName, FimpD.PROP.STL_GENBIL.dSigmay);
				else if (FimpD.nHysModelType == 3)
					tStr.Format(_LS(IDS_TM_WORKTREE_FIMP_STL_TRILIN), FimpD.strName, FimpD.PROP.STL_TRILIN.dSigmay[0]);
				else if (FimpD.nHysModelType == 4)
					tStr.Format(_LS(IDS_TM_WORKTREE_FIMP_STL_PARK), FimpD.strName, FimpD.PROP.STL_PARK.dFy);
				else if (FimpD.nHysModelType == 5)
					tStr.Format(_LS(IDS_TM_WORKTREE_FIMP_STL_JBRIDGE), FimpD.strName, FimpD.PROP.STL_ROADJP.dSigsy);
				else if (FimpD.nHysModelType == 6)
					tStr.Format(_LS(IDS_TM_WORKTREE_FIMP_STL_GBCHINA2010), FimpD.strName, FimpD.PROP.STL_GB2010.dFyr);
				else if (FimpD.nHysModelType == D_FIMP_CURV_STEL_ENRGDS)
					tStr.Format(_LS(IDS_TM_WORKTREE_FIMP_STL_ENRGDS), FimpD.strName);
			}
			else if (FimpD.nMaterialType == 2)  // rebar
			{
				if (FimpD.nHysModelType == 6)
					tStr.Format(_LS(IDS_TM_WORKTREE_FIMP_STL_GBCHINA2010), FimpD.strName, FimpD.PROP.STL_GB2010.dFyr);
			}
			else ASSERT(0);
			InsertTreeItem(ThTi, WORK_FIMP_LST, tStr, _T("ico24_properties_inelproperties_inelasticmaterialproperties"));
		}
	}

	// Fiber Division of Section
	if (nFibrCount)
	{
		// civil, gen 나뉨
#if defined(_MGEN)
		CString strSVGName = _T("ico24_properties_inelasticproperties_fiberdivisionofsectionbeamcolumn");
#else
		CString strSVGName = _T("ico24_properties_inelproperties_fiberdivisionofsection");
#endif
		ThTi = InsertTreeItem(hTI, WORK_FIBR_FLD, _LS(IDS_TM_NC_WORKTREE_Fiber_Division_Section_d), strSVGName);
		SetItemDisplayCount(ThTi, nFibrCount);

		T_FIBR_D FibrD;
		T_SECT_D SectD;
		T_FIMP_D FimpD[3];
		for (int i = 0; i < nFibrCount; i++)
		{
			if (!pDoc->m_pAttrCtrl->GetFibr(aFibrKeyList[i], FibrD)) ASSERT(0);
			if (!pDoc->m_pAttrCtrl->GetSect(FibrD.SectKey, SectD)) ASSERT(0);
			if (!pDoc->m_pAttrCtrl->GetFimp(FibrD.FimpKey[0], FimpD[0])) ASSERT(0);
			if (!pDoc->m_pAttrCtrl->GetFimp(FibrD.FimpKey[1], FimpD[1])) ASSERT(0);
			if (!pDoc->m_pAttrCtrl->GetFimp(FibrD.FimpKey[2], FimpD[2])) ASSERT(0);

			tStr.Format(_LS(IDS_TM_WORKTREE_Fiber_Division_Info),
				FibrD.strName, SectD.SName, FimpD[0].strName, FimpD[1].strName, FimpD[2].strName);
			InsertTreeItem(ThTi, WORK_FIBR_LST, tStr, strSVGName);

			m_aFibrItemKey_TH.Add(aFibrKeyList[i]);
		}
	}

	// Fiber Division of Section (MCPM Wall)
	if (nFibwCount)
	{
		ThTi = InsertTreeItem(hTI, WORK_FIBW_FLD, _LS(IDS_TM_NC_WORKTREE_Fiber_Division_Section_Wall_d), _T("ico24_properties_inelasticproperties_fiberdivisionofsectionmcpmwall"));
		SetItemDisplayCount(ThTi, nFibwCount);

		T_FIBW_D FibwD;
		T_STOR_D StorD;
		T_FIMP_D FimpD[3];
		for (int i = 0; i < nFibwCount; i++)
		{
			if (!pDoc->m_pAttrCtrl->GetFibw(aFibwKeyList[i], FibwD)) ASSERT(0);
			if (!pDoc->m_pAttrCtrl->GetStor(FibwD.StorK, StorD)) ASSERT(0);
			if (!pDoc->m_pAttrCtrl->GetFimp(FibwD.FimpKey[0], FimpD[0])) ASSERT(0);
			if (!pDoc->m_pAttrCtrl->GetFimp(FibwD.FimpKey[1], FimpD[1])) ASSERT(0);
			if (!pDoc->m_pAttrCtrl->GetFimp(FibwD.FimpKey[2], FimpD[2])) ASSERT(0);

			tStr.Format(_LS(IDS_TM_WORKTREE_Fiber_Division_Info_Wall),
				FibwD.strName, FibwD.nWallID, StorD.StoryName, FimpD[0].strName, FimpD[1].strName, FimpD[2].strName);
			InsertTreeItem(ThTi, WORK_FIBW_LST, tStr, _T("ico24_properties_inelasticproperties_fiberdivisionofsectionmcpmwall"));

			m_aFibwItemKey_TH.Add(aFibwKeyList[i]);
		}
	}

	if (hTI != NULL)
	{
		if (bInit) Expand(hTI, TVE_EXPAND);// 최초에 보여줄 때는 한단계만...
		else ExpandCompletely(hTI, TRUE);
	}
	return hTI;
}

void CTreeWorkCtrl::EditProperty_InelasticProperty(CDBDoc* pDoc, HTREEITEM ht, UINT data, int pos)
{
	if (data == WORK_IEHC_FLD)
	{
		CCMIehcDlg dlg;
		dlg.SetInitPos(D_INIT_POS_LT, 0, 50);

		T_IEHC_D IehcD;
		if (!pDoc->m_pAttrCtrl2->GetIehc(IehcD)) IehcD.Initialize();
		dlg.SetData(D_FIBR_TYPE_IEHP, IehcD.nBeamLoc, IehcD.nBeamDivNumNy, IehcD.nBeamDivNumNz, IehcD.nBeamDivNumNyCover, IehcD.nBeamDivNumNzCover,
			IehcD.bWallConsOut, IehcD.nWallDivNumZ, IehcD.nWallDivNumY, IehcD.nWallDivNumZCover, IehcD.nWallDivNumYCover, IehcD.dR, IehcD.nFAreaSizeCore, IehcD.nFAreaSizeCover, IehcD.nWAreaSize, IehcD.nWAreaSizeCover, IehcD.bConsiderRebarArea1D, IehcD.bConsiderRebarAreaWall);
		dlg.DoModal();
	}
	else if (data == WORK_IEHP_LST)    // Inelastic Hinge Property
	{
		T_IEHP_K IehpK = m_aIehpItemKey[pos - 1];
		T_IEHP_D IehpD;
		if (pDoc->m_pAttrCtrl->GetIehp(IehpK, IehpD) == TRUE)
		{
#if defined (_MEC)
			CIehpItemDlg_MEC* pDlg = new CIehpItemDlg_MEC();
#else
			CIehpItemDlg* pDlg = new CIehpItemDlg();
#endif
			T_IEHG_K IehgK;
			pDlg->SetAssignHingeMode(FALSE, IehgK);
			pDlg->SetParamData(IehpK, IehpD);
			pDlg->DoModal();
			delete pDlg;
		}
	}
	else if (data == WORK_IEHG_LST)
	{
		T_IEHG_D IehgD = m_aIehgInfo[pos - 1];

		CArray<T_IEHG_K, T_IEHG_K> aKey;
		GetSelectedIehgKeyListWithMultiTreeItemSelect(aKey);
		if (aKey.GetSize() == 0)	ASSERT(0);

		T_IEHP_D IehpD;
		if (!pDoc->m_pAttrCtrl->GetIehp(IehgD.IehpKey, IehpD)) return;

#if defined (_MEC)
		CIehpItemDlg_MEC* pDlg = new CIehpItemDlg_MEC();
#else
		CIehpItemDlg* pDlg = new CIehpItemDlg();
#endif
		pDlg->SetAssignHingeMode(TRUE, aKey[0]);
		pDlg->SetParamData(IehgD.IehpKey, IehpD);
		pDlg->DoModal();
		delete pDlg;
	}
	else if (data == WORK_FIMP_LST)
	{
		CArray<T_FIMP_K, T_FIMP_K> aFimpKeyList;
		pDoc->m_pAttrCtrl->GetFimpKeyList(aFimpKeyList);
		T_FIMP_K FimpKey = aFimpKeyList[pos - 1];
		CMD2_DoModal(D_CMD2_FIBER_MATERIAL_PROP_ITEM, &FimpKey);
	}
	else if (data == WORK_FIBR_LST)
	{
		T_FIBR_K FibrKey = m_aFibrItemKey_TH[pos - 1];
		ExportDisplaySetting::ShowSectDivDlg(this, FibrKey, D_FIBR_DLG_TYPE_IEHP_BEAM);
	}
	else if (data == WORK_FIBW_LST)
	{
		T_FIBW_K FibwKey = m_aFibwItemKey_TH[pos - 1];
		ExportDisplaySetting::ShowSectDivDlg(this, FibwKey, D_FIBR_DLG_TYPE_IEHP_WALL);
	}
	else if (data == WORK_SIHO_FLD)
	{
		CBarTreeMenu* pTree = (CBarTreeMenu*)CTreeMenuBarBase::GetMySelfST();
		pTree->ShowDlgWithInit(__TMMODE_CMD_SIHO_ELEM__, 0);
	}
	else if (data == WORK_SIHG_FLD)
	{
		CBarTreeMenu* pTree = (CBarTreeMenu*)CTreeMenuBarBase::GetMySelfST();
		pTree->ShowDlgWithInit(__TMMODE_CMD_SIHO_GLINK__, 0);
	}
	else if (data == WORK_SIHP_FLD)
	{
		CBarTreeMenu* pTree = (CBarTreeMenu*)CTreeMenuBarBase::GetMySelfST();
		pTree->ShowDlgWithInit(__TMMODE_CMD_SIHO_PSSPOT__, 0);
	}
}

BOOL CTreeWorkCtrl::IsUsedFimp_PO(HTREEITEM hItem)
{
	CDBDoc* pDoc = CDBDoc::GetDocPoint();
	if (!pDoc) { TRACE(_LS(IDS_TMWK__MSG1)); return FALSE; }

	HTREEITEM ht, prvHt;
	int pos = 0;
	ht = hItem;
	for (prvHt = ht; prvHt != NULL; ht = prvHt, pos++) prvHt = GetPrevSiblingItemWithoutFilter(ht);

	CArray<T_FIMP_K, T_FIMP_K> aFimpKeyList;
	pDoc->m_pAttrCtrl->GetFimpKeyList(aFimpKeyList);
	T_FIMP_K FimpKey = aFimpKeyList[pos - 1];

	T_FIBR_D FibrData;
	int nCount = m_aFibrItemKey_PO.GetSize();

	CArray<T_PHGT_K, T_PHGT_K> aPhgtKeyList;
	pDoc->m_pAttrCtrl->GetPhgtKeyList(aPhgtKeyList);
	T_PHGT_D PhgtData;
	int nPhgtCount = aPhgtKeyList.GetSize();

	CArray<T_PHGE_K, T_PHGE_K> aPhgeK;
	pDoc->m_pAttrCtrl->GetPhgeKeyListSolOrd(aPhgeK);
	int nSize = aPhgeK.GetSize();

	for (int i = 0; i < nCount; i++)
	{
		for (int j = 0; j < nPhgtCount; j++)
		{
			const T_PHGT_D* pPhgt = pDoc->m_pAttrCtrl->GetPhgtConstPtr(aPhgtKeyList[j]);
			if (pPhgt->nElemType != D_PHGT_ELEM_BEAM)
				continue;

			if (pPhgt->FibrKey == m_aFibrItemKey_PO[i])
			{
				for (int k = 0; k < nSize; k++)
				{
					T_PHGE_D PhgeD;
					if (!pDoc->m_pAttrCtrl->GetPhge(aPhgeK[k], PhgeD)) continue;
					if (PhgeD.HingeTypeK == aPhgtKeyList[j])
					{
						pDoc->m_pAttrCtrl->GetFibr(m_aFibrItemKey_PO[i], FibrData);
						if (FibrData.FimpKey[0] == FimpKey) return 1;
						if (FibrData.FimpKey[1] == FimpKey) return 1;
						if (FibrData.FimpKey[2] == FimpKey) return 1;
						//!@#$ MNET:1691 20051207 LBI : 3 -> 6
						if (FibrData.FimpKey[3] == FimpKey) return 1;
						if (FibrData.FimpKey[4] == FimpKey) return 1;
						if (FibrData.FimpKey[5] == FimpKey) return 1;
					}
				}
			}
		}
	}

	T_FIBW_D FibwData;
	nCount = m_aFibwItemKey_PO.GetSize();
	for (int i = 0; i < nCount; i++)
	{
		for (int j = 0; j < nPhgtCount; j++)
		{
			const T_PHGT_D* pPhgt = pDoc->m_pAttrCtrl->GetPhgtConstPtr(aPhgtKeyList[j]);
			if (pPhgt->nElemType != D_PHGT_ELEM_WALL)
				continue;

			if (pPhgt->FibrKey == m_aFibwItemKey_PO[i])
			{
				for (int k = 0; k < nSize; k++)
				{
					T_PHGE_D PhgeD;
					if (!pDoc->m_pAttrCtrl->GetPhge(aPhgeK[k], PhgeD)) continue;
					if (PhgeD.HingeTypeK == aPhgtKeyList[j])
					{
						pDoc->m_pAttrCtrl->GetFibw(m_aFibwItemKey_PO[i], FibwData);
						if (FibwData.FimpKey[0] == FimpKey) return 1;
						if (FibwData.FimpKey[1] == FimpKey) return 1;
						if (FibwData.FimpKey[2] == FimpKey) return 1;
						if (FibwData.FimpKey[3] == FimpKey) return 1;
						if (FibwData.FimpKey[4] == FimpKey) return 1;
						if (FibwData.FimpKey[5] == FimpKey) return 1;
					}
				}
			}
		}
	}

	// 자동생성된 친구들
	T_PHGE_D PhgeD;
	for (int i = 0; i < aPhgeK.GetSize(); i++)
	{
		if (!pDoc->m_pAttrCtrl->GetPhge(aPhgeK[i], PhgeD)) continue;
		if (PhgeD.FiberKey == 0) continue;

		if (aPhgeK[i].key.type == 1) // Beam
		{
			if (!pDoc->m_pAttrCtrl->GetFibr(PhgeD.FiberKey, FibrData)) continue;
			if (FibrData.FimpKey[0] == FimpKey) return 1;
			if (FibrData.FimpKey[1] == FimpKey) return 1;
			if (FibrData.FimpKey[2] == FimpKey) return 1;
			if (FibrData.FimpKey[3] == FimpKey) return 1;
			if (FibrData.FimpKey[4] == FimpKey) return 1;
			if (FibrData.FimpKey[5] == FimpKey) return 1;
		}
		else
		{
			if (!pDoc->m_pAttrCtrl->GetFibw(PhgeD.FiberKey, FibwData)) continue;
			if (FibwData.FimpKey[0] == FimpKey) return 1;
			if (FibwData.FimpKey[1] == FimpKey) return 1;
			if (FibwData.FimpKey[2] == FimpKey) return 1;
			if (FibwData.FimpKey[3] == FimpKey) return 1;
			if (FibwData.FimpKey[4] == FimpKey) return 1;
			if (FibwData.FimpKey[5] == FimpKey) return 1;
		}
	}

	return 0; // 사용 안된 것이면 
}

BOOL CTreeWorkCtrl::IsUsedFibr_PO(HTREEITEM hItem)
{
	CDBDoc* pDoc = CDBDoc::GetDocPoint();
	if (!pDoc) { TRACE(_LS(IDS_TMWK__MSG1)); return FALSE; }

	HTREEITEM ht, prvHt;
	int pos = 0;
	ht = hItem;
	for (prvHt = ht; prvHt != NULL; ht = prvHt, pos++) prvHt = GetPrevSiblingItemWithoutFilter(ht);

	T_FIBR_K FibrKey = m_aFibrItemKey_PO[pos - 1];

	CArray<T_PHGT_K, T_PHGT_K> aPhgtKeyList;
	pDoc->m_pAttrCtrl->GetPhgtKeyList(aPhgtKeyList);
	int nCount = aPhgtKeyList.GetSize();

	CArray<T_PHGE_K, T_PHGE_K> aPhgeK;
	pDoc->m_pAttrCtrl->GetPhgeKeyListSolOrd(aPhgeK);
	int nSize = aPhgeK.GetSize();

	for (int i = 0; i < nCount; i++)
	{
		const T_PHGT_D* pPhgt = pDoc->m_pAttrCtrl->GetPhgtConstPtr((T_PHGT_K)aPhgtKeyList[i]);
		if (pPhgt->FibrKey == FibrKey)
		{
			for (int j = 0; j < nSize; j++)
			{
				T_PHGE_D PhgeD;
				if (!pDoc->m_pAttrCtrl->GetPhge(aPhgeK[j], PhgeD)) continue;
				if (PhgeD.HingeTypeK == aPhgtKeyList[i]) return 1;
			}
		}
	}
	// PMS 5317 : 자동 생성된 Fiber 단면
	for (int i = 0; i < aPhgeK.GetSize(); i++)
	{
		T_PHGE_D PhgeD;
		if (!pDoc->m_pAttrCtrl->GetPhge(aPhgeK[i], PhgeD)) continue;
		if (PhgeD.FiberKey == FibrKey) return 1;
	}
	return 0; // 사용 안된 것이면 
}

