int CTreeWorkCtrl::GetNonDissipativeListBySpfc(CDBDoc* pDoc, T_SPFC_K SpfcK, CArray<double, double>& aNonDissipative)
{
	aNonDissipative.RemoveAll();

	CArray<T_SPLC_K, T_SPLC_K> aSplcKeyList;
	pDoc->m_pAttrCtrl->GetSplcKeyList(aSplcKeyList);
	int nSplcCount = aSplcKeyList.GetSize();
	T_SPLC_D SplcD;
	CMapEx<CString, LPCTSTR, BOOL, BOOL> mSpfcND;
	CString strSpfcNDKey = _T("");
	CString strSpfcND = _T("");
	for (int k = 0; k < nSplcCount; k++)
	{
		pDoc->m_pAttrCtrl->GetSplc(aSplcKeyList[k], SplcD);
		if (!SplcD.bNonDissipative) continue;

		BOOL bExist = FALSE;
		for (int f = 0; f < SplcD.aSpfcKey.GetSize(); f++)
		{
			if (SplcD.aSpfcKey[f] != SpfcK) continue;
			bExist = TRUE;
			break;
		}
		if (bExist == FALSE) continue;

		strSpfcNDKey.Format(_T("%d_%g"), SpfcK, SplcD.dNonDissipative);
		if (mSpfcND.Exist(strSpfcNDKey)) continue;
		mSpfcND.SetAt(strSpfcNDKey, TRUE);

		aNonDissipative.Add(SplcD.dNonDissipative);
	}

	return aNonDissipative.GetSize();
}

